42:     /** How a checkpoint should be aligned. */
43:     public enum AlignmentType {
44:         AT_LEAST_ONCE,
45:         ALIGNED,
46:         UNALIGNED,
47:         FORCED_ALIGNED
48:     }
49: 
50:     public static final long NO_ALIGNED_CHECKPOINT_TIME_OUT = Long.MAX_VALUE;
51: 
52:     private static final long serialVersionUID = 5010126558083292915L;
53: 
54:     /** Type of the checkpoint. */
55:     private final SnapshotType checkpointType;
56: 
57:     /** Target location for the checkpoint. */
58:     private final CheckpointStorageLocationReference targetLocation;
59: 
60:     private final AlignmentType alignmentType;
61: 
62:     private final long alignedCheckpointTimeout;
63: 
64:     public static CheckpointOptions notExactlyOnce(
65:             SnapshotType type, CheckpointStorageLocationReference location) {
66:         return new CheckpointOptions(
67:                 type, location, AlignmentType.AT_LEAST_ONCE, NO_ALIGNED_CHECKPOINT_TIME_OUT);
68:     }
69: 
70:     public static CheckpointOptions alignedNoTimeout(
71:             SnapshotType type, CheckpointStorageLocationReference location) {
72:         return new CheckpointOptions(
73:                 type, location, AlignmentType.ALIGNED, NO_ALIGNED_CHECKPOINT_TIME_OUT);
74:     }
75: 
76:     public static CheckpointOptions unaligned(
77:             SnapshotType type, CheckpointStorageLocationReference location) {
78:         checkArgument(!type.isSavepoint(), "Savepoints can not be unaligned");
79:         return new CheckpointOptions(
80:                 type, location, AlignmentType.UNALIGNED, NO_ALIGNED_CHECKPOINT_TIME_OUT);
81:     }
82: 
83:     public static CheckpointOptions alignedWithTimeout(
84:             SnapshotType type,
85:             CheckpointStorageLocationReference location,
86:             long alignedCheckpointTimeout) {
87:         checkArgument(!type.isSavepoint(), "Savepoints can not be unaligned");
88:         return new CheckpointOptions(
89:                 type, location, AlignmentType.ALIGNED, alignedCheckpointTimeout);
90:     }
91: 
92:     private static CheckpointOptions forceAligned(
93:             SnapshotType type,
94:             CheckpointStorageLocationReference location,
95:             long alignedCheckpointTimeout) {
96:         checkArgument(!type.isSavepoint(), "Savepoints can not be unaligned");
97:         return new CheckpointOptions(
98:                 type, location, AlignmentType.FORCED_ALIGNED, alignedCheckpointTimeout);
99:     }
100: 
101:     public static CheckpointOptions forConfig(
102:             SnapshotType checkpointType,
103:             CheckpointStorageLocationReference locationReference,
104:             boolean isExactlyOnceMode,
105:             boolean isUnalignedEnabled,
106:             long alignedCheckpointTimeout) {
107:         if (!isExactlyOnceMode) {
108:             return notExactlyOnce(checkpointType, locationReference);
109:         } else if (checkpointType.isSavepoint()) {
110:             return alignedNoTimeout(checkpointType, locationReference);
111:         } else if (!isUnalignedEnabled) {
112:             return alignedNoTimeout(checkpointType, locationReference);
113:         } else if (alignedCheckpointTimeout == 0
114:                 || alignedCheckpointTimeout == NO_ALIGNED_CHECKPOINT_TIME_OUT) {
115:             return unaligned(checkpointType, locationReference);
116:         } else {
117:             return alignedWithTimeout(checkpointType, locationReference, alignedCheckpointTimeout);
118:         }
119:     }
