127:     public CheckpointOptions(
128:             SnapshotType checkpointType,
129:             CheckpointStorageLocationReference targetLocation,
130:             AlignmentType alignmentType,
131:             long alignedCheckpointTimeout) {
132: 
133:         checkArgument(
134:                 alignmentType != AlignmentType.UNALIGNED || !checkpointType.isSavepoint(),
135:                 "Savepoint can't be unaligned");
136:         checkArgument(
137:                 alignedCheckpointTimeout == NO_ALIGNED_CHECKPOINT_TIME_OUT
138:                         || alignmentType != AlignmentType.UNALIGNED,
139:                 "Unaligned checkpoint can't have timeout (%s)",
140:                 alignedCheckpointTimeout);
141:         this.checkpointType = checkNotNull(checkpointType);
142:         this.targetLocation = checkNotNull(targetLocation);
143:         this.alignmentType = checkNotNull(alignmentType);
144:         this.alignedCheckpointTimeout = alignedCheckpointTimeout;
145:     }
146: 
147:     public boolean needsAlignment() {
148:         return isExactlyOnceMode()
149:                 && (getCheckpointType().isSavepoint() || !isUnalignedCheckpoint());
150:     }
151: 
152:     public long getAlignedCheckpointTimeout() {
153:         return alignedCheckpointTimeout;
154:     }
155: 
156:     public AlignmentType getAlignment() {
157:         return alignmentType;
158:     }
159: 
160:     public boolean isTimeoutable() {
161:         if (alignmentType == AlignmentType.FORCED_ALIGNED) {
162:             return false;
163:         }
164:         return alignmentType == AlignmentType.ALIGNED
165:                 && (alignedCheckpointTimeout > 0
166:                         && alignedCheckpointTimeout != NO_ALIGNED_CHECKPOINT_TIME_OUT);
167:     }
168: 
169:     // ------------------------------------------------------------------------
170: 
171:     /** Returns the type of checkpoint to perform. */
172:     public SnapshotType getCheckpointType() {
173:         return checkpointType;
174:     }
175: 
176:     /** Returns the target location for the checkpoint. */
177:     public CheckpointStorageLocationReference getTargetLocation() {
178:         return targetLocation;
179:     }
180: 
181:     public boolean isExactlyOnceMode() {
182:         return alignmentType != AlignmentType.AT_LEAST_ONCE;
183:     }
184: 
185:     public boolean isUnalignedCheckpoint() {
186:         return alignmentType == AlignmentType.UNALIGNED;
187:     }
188: 
189:     public boolean needsChannelState() {
190:         return isUnalignedCheckpoint() || isTimeoutable();
191:     }
192: 
193:     public CheckpointOptions withUnalignedSupported() {
194:         if (alignmentType == AlignmentType.FORCED_ALIGNED) {
195:             return alignedCheckpointTimeout != NO_ALIGNED_CHECKPOINT_TIME_OUT
196:                     ? alignedWithTimeout(checkpointType, targetLocation, alignedCheckpointTimeout)
197:                     : unaligned(checkpointType, targetLocation);
198:         }
199:         return this;
200:     }
201: 
202:     public CheckpointOptions withUnalignedUnsupported() {
203:         if (needsChannelState()) {
204:             return forceAligned(checkpointType, targetLocation, alignedCheckpointTimeout);
205:         }
206:         return this;
207:     }
208: 
209:     // ------------------------------------------------------------------------
210: 
211:     @Override
212:     public int hashCode() {
213:         return Objects.hash(
214:                 targetLocation, checkpointType, alignmentType, alignedCheckpointTimeout);
215:     }
216: 
217:     @Override
218:     public boolean equals(Object obj) {
219:         if (this == obj) {
220:             return true;
221:         } else if (obj != null && obj.getClass() == CheckpointOptions.class) {
222:             final CheckpointOptions that = (CheckpointOptions) obj;
223:             return this.checkpointType.equals(that.checkpointType)
224:                     && this.targetLocation.equals(that.targetLocation)
225:                     && this.alignmentType == that.alignmentType
226:                     && this.alignedCheckpointTimeout == that.alignedCheckpointTimeout;
227:         } else {
228:             return false;
229:         }
230:     }
231: 
232:     @Override
233:     public String toString() {
234:         return "CheckpointOptions{"
235:                 + "checkpointType="
236:                 + checkpointType
237:                 + ", targetLocation="
238:                 + targetLocation
239:                 + ", alignmentType="
240:                 + alignmentType
241:                 + ", alignedCheckpointTimeout="
242:                 + alignedCheckpointTimeout
243:                 + '}';
244:     }
245: 
246:     // ------------------------------------------------------------------------
247:     //  Factory methods
248:     // ------------------------------------------------------------------------
249: 
250:     private static final CheckpointOptions CHECKPOINT_AT_DEFAULT_LOCATION =
251:             new CheckpointOptions(
252:                     CheckpointType.CHECKPOINT, CheckpointStorageLocationReference.getDefault());
253: 
254:     @VisibleForTesting
255:     public static CheckpointOptions forCheckpointWithDefaultLocation() {
256:         return CHECKPOINT_AT_DEFAULT_LOCATION;
257:     }
258: 
259:     public CheckpointOptions toUnaligned() {
260:         checkState(alignmentType == AlignmentType.ALIGNED);
261:         return unaligned(checkpointType, targetLocation);
262:     }
263: }
