645:     /**
646:      * The core method that control space if needed. This method will compare the desired space
647:      * amplification with current one, and if it exceeds the configured amplification, this method
648:      * will mark minimal set of {@link PhysicalFile}s not to be reused anymore.
649:      */
650:     private void controlSpace() {
651:         if (maxSpaceAmplification != Float.MAX_VALUE
652:                 && spaceStat.logicalFileSize.get() * maxSpaceAmplification
653:                         < spaceStat.physicalFileSize.get()) {
654:             // may need control space
655:             long goalPhysicalSize =
656:                     Math.round(spaceStat.logicalFileSize.get() * maxSpaceAmplification);
657:             final AtomicLong aliveSize = new AtomicLong(0L);
658:             // retrieve all the physical files and calculate current alive size
659:             Set<PhysicalFile> knownPhysicalFiles = new HashSet<>();
660:             knownLogicalFiles.values().stream()
661:                     .map(LogicalFile::getPhysicalFile)
662:                     .forEach(
663:                             file -> {
664:                                 if (file.isCouldReuse()) {
665:                                     if (knownPhysicalFiles.add(file)) {
666:                                         aliveSize.addAndGet(file.getSize());
667:                                     }
668:                                 }
669:                             });
670:             // the alive size still greater than the goal
671:             if (aliveSize.get() > goalPhysicalSize) {
672:                 // sort in DESC order on wasted size
673:                 SortedSet<PhysicalFile> sortedPhysicalFile =
674:                         new TreeSet<>((a, b) -> Long.compare(b.wastedSize(), a.wastedSize()));
675:                 knownPhysicalFiles.stream()
676:                         .filter(PhysicalFile::closed)
677:                         .forEach(sortedPhysicalFile::add);
678:                 // mark the physical file un-alive, until it reaches our goal.
679:                 for (PhysicalFile file : sortedPhysicalFile) {
680:                     if (!file.checkReuseOnSpaceAmplification(maxSpaceAmplification)) {
681:                         if (aliveSize.addAndGet(-file.wastedSize()) <= goalPhysicalSize) {
682:                             break;
683:                         }
684:                     }
685:                 }
686:             }
687:         }
688:     }
