326:             this.physicalFileCount = new AtomicLong(physicalFileCount);
327:             this.physicalFileSize = new AtomicLong(physicalFileSize);
328:             this.logicalFileCount = new AtomicLong(logicalFileCount);
329:             this.logicalFileSize = new AtomicLong(logicalFileSize);
330:         }
331: 
