338:             logicalFileSize.addAndGet(-size);
339:             logicalFileCount.decrementAndGet();
340:         }
341: 
342:         public void onPhysicalFileUpdate(long size) {
343:             physicalFileSize.addAndGet(size);
344:         }
345: 
346:         public void onPhysicalFileCreate() {
347:             physicalFileCount.incrementAndGet();
348:         }
349: 
350:         public void onPhysicalFileDelete(long size) {
351:             physicalFileSize.addAndGet(-size);
352:             physicalFileCount.decrementAndGet();
353:         }
