311:     private static class NotifyingDefiniteKeySource extends RichParallelSourceFunction<Integer> {
312: 
313:         private static final long serialVersionUID = 1L;
314: 
315:         private final int numberKeys;
316:         protected final int numberElements;
317:         private final boolean failAfterEmission;
318:         protected int counter = 0;
319:         private boolean running = true;
320: 
321:         public NotifyingDefiniteKeySource(
322:                 int numberKeys, int numberElements, boolean failAfterEmission) {
323:             Preconditions.checkState(numberElements > 0);
324:             this.numberKeys = numberKeys;
325:             this.numberElements = numberElements;
326:             this.failAfterEmission = failAfterEmission;
327:         }
328: 
329:         public boolean waitCheckpointCompleted() throws Exception {
330:             return true;
331:         }
332: 
333:         @Override
334:         public void run(SourceContext<Integer> ctx) throws Exception {
335:             final int subtaskIndex = getRuntimeContext().getTaskInfo().getIndexOfThisSubtask();
336:             while (running) {
337:                 if (counter < numberElements) {
338:                     synchronized (ctx.getCheckpointLock()) {
339:                         for (int value = subtaskIndex;
340:                                 value < numberKeys;
341:                                 value +=
342:                                         getRuntimeContext()
343:                                                 .getTaskInfo()
344:                                                 .getNumberOfParallelSubtasks()) {
345:                             ctx.collect(value);
346:                         }
347:                         counter++;
348:                     }
349:                 } else {
350:                     boolean newCheckpoint = false;
351:                     long waited = 0L;
352:                     // maximum wait 5min
353:                     while (!newCheckpoint && waited < 30000L) {
354:                         synchronized (ctx.getCheckpointLock()) {
355:                             newCheckpoint = waitCheckpointCompleted();
356:                         }
357:                         if (!newCheckpoint) {
358:                             waited += 10L;
359:                             Thread.sleep(10L);
360:                         }
361:                     }
362:                     if (failAfterEmission) {
363:                         throw new FlinkRuntimeException(
364:                                 "Make job fail artificially, to retain completed checkpoint.");
365:                     } else {
366:                         running = false;
367:                     }
368:                 }
369:             }
370:         }
371: 
372:         @Override
373:         public void cancel() {
374:             running = false;
375:         }
376:     }
377: 
378:     private static class SubtaskIndexFlatMapper
379:             extends RichFlatMapFunction<Integer, Tuple2<Integer, Integer>>
380:             implements CheckpointedFunction {
381: 
382:         private static final long serialVersionUID = 1L;
383: 
384:         private transient ValueState<Integer> counter;
385:         private transient ValueState<Integer> sum;
386: 
387:         private final int numberElements;
388: 
389:         public SubtaskIndexFlatMapper(int numberElements) {
390:             this.numberElements = numberElements;
391:         }
392: 
393:         @Override
394:         public void flatMap(Integer value, Collector<Tuple2<Integer, Integer>> out)
395:                 throws Exception {
396:             Integer counterValue = counter.value();
397:             int count = counterValue == null ? 1 : counterValue + 1;
398:             counter.update(count);
399: 
400:             Integer sumValue = sum.value();
401:             int s = sumValue == null ? value : sumValue + value;
402:             sum.update(s);
403: 
404:             if (count == numberElements) {
405:                 out.collect(
406:                         Tuple2.of(getRuntimeContext().getTaskInfo().getIndexOfThisSubtask(), s));
407:             }
408:         }
409: 
410:         @Override
411:         public void snapshotState(FunctionSnapshotContext context) throws Exception {
412:             // all managed, nothing to do.
413:         }
414: 
415:         @Override
416:         public void initializeState(FunctionInitializationContext context) throws Exception {
417:             counter =
418:                     context.getKeyedStateStore()
419:                             .getState(new ValueStateDescriptor<>("counter", Integer.class));
420:             sum =
421:                     context.getKeyedStateStore()
422:                             .getState(new ValueStateDescriptor<>("sum", Integer.class));
423:         }
424:     }
425: 
426:     private static class CollectionSink<IN> implements Sink<IN> {
427: 
428:         private static final ConcurrentHashMap<JobID, CollectionSinkWriter<?>> writers =
429:                 new ConcurrentHashMap<>();
430: 
431:         private static final long serialVersionUID = 1L;
432: 
433:         @SuppressWarnings("unchecked")
434:         public static <IN> Set<IN> getElementsSet(JobID jobID) {
435:             CollectionSinkWriter<IN> writer = (CollectionSinkWriter<IN>) writers.get(jobID);
436:             if (writer == null) {
437:                 return Collections.emptySet();
438:             } else {
439:                 return writer.getElementsSet();
440:             }
441:         }
442: 
443:         public static void clearElementsSet(JobID jobID) {
444:             writers.remove(jobID);
445:         }
446: 
447:         @Override
448:         @SuppressWarnings("unchecked")
449:         public SinkWriter<IN> createWriter(WriterInitContext context) throws IOException {
450:             final CollectionSinkWriter<IN> writer =
451:                     (CollectionSinkWriter<IN>)
452:                             writers.computeIfAbsent(
453:                                     context.getJobInfo().getJobId(),
454:                                     (k) -> new CollectionSinkWriter<IN>());
455:             return writer;
456:         }
457: 
458:         private static class CollectionSinkWriter<IN> implements SinkWriter<IN> {
459: 
460:             private final Set<Object> elements =
461:                     Collections.newSetFromMap(new ConcurrentHashMap<>());
462: 
463:             @Override
464:             public void write(IN element, Context context)
465:                     throws IOException, InterruptedException {
466:                 elements.add(element);
467:             }
468: 
469:             @Override
470:             public void flush(boolean endOfInput) throws IOException, InterruptedException {}
471: 
472:             @Override
473:             public void close() throws Exception {}
474: 
475:             @SuppressWarnings("unchecked")
476:             public <IN> Set<IN> getElementsSet() {
477:                 return (Set<IN>) elements;
478:             }
479:         }
480:     }
481: }
