136:             CloseableRegistry cancelStreamRegistry,
137:             ClassLoader userCodeClassLoader,
138:             Map<String, ForStOperationUtils.ForStKvStateInfo> kvStateInformation,
139:             StateSerializerProvider<K> keySerializerProvider,
140:             ForStResourceContainer optionsContainer,
141:             Path forstBasePath,
142:             Path instanceRocksDBPath,
143:             DBOptions dbOptions,
144:             Function<String, ColumnFamilyOptions> columnFamilyOptionsFactory,
145:             ForStNativeMetricOptions nativeMetricOptions,
146:             MetricGroup metricGroup,
147:             @Nonnull ForStDBTtlCompactFiltersManager ttlCompactFiltersManager,
148:             @Nonnegative long writeBatchSize,
149:             Long writeBufferManagerCapacity,
150:             CustomInitializationMetrics customInitializationMetrics,
151:             @Nonnull Collection<IncrementalRemoteKeyedStateHandle> restoreStateHandles,
152:             double overlapFractionThreshold,
153:             boolean useIngestDbRestoreMode,
154:             boolean useDeleteFilesInRange,
155:             RecoveryClaimMode recoveryClaimMode) {
156: 
157:         this.forstHandle =
