165:                         ttlCompactFiltersManager,
166:                         writeBufferManagerCapacity);
167:         this.operatorIdentifier = operatorIdentifier;
168:         this.restoredSstFiles = new TreeMap<>();
169:         this.lastCompletedCheckpointId = -1L;
170:         this.backendUID = UUID.randomUUID();
171:         this.customInitializationMetrics = customInitializationMetrics;
172:         this.restoreStateHandles = restoreStateHandles.stream().collect(Collectors.toList());
173:         this.cancelStreamRegistry = cancelStreamRegistry;
174:         this.keyGroupRange = keyGroupRange;
175:         this.keyGroupPrefixBytes = keyGroupPrefixBytes;
