187:     /**
188:      * Root method that branches for different implementations of {@link
189:      * IncrementalKeyedStateHandle}.
190:      */
191:     @Override
192:     public ForStRestoreResult restore() throws Exception {
193: 
194:         if (restoreStateHandles == null || restoreStateHandles.isEmpty()) {
195:             return null;
196:         }
197: 
198:         logger.info(
199:                 "Starting RocksDB incremental recovery in operator {} "
200:                         + "target key-group range {}. Use IngestDB={}, State Handles={}",
201:                 operatorIdentifier,
202:                 keyGroupRange.prettyPrintInterval(),
203:                 useIngestDbRestoreMode,
204:                 restoreStateHandles);
205: 
206:         List<StateHandleTransferSpec> toTransferSpecs = new ArrayList<>();
207:         int bestStateHandleForInit = -1;
208:         if (!useIngestDbRestoreMode || restoreStateHandles.size() == 1) {
209:             bestStateHandleForInit =
210:                     findTheBestStateHandleForInitial(
211:                             restoreStateHandles, keyGroupRange, overlapFractionThreshold);
212:             toTransferSpecs.add(
213:                     new StateHandleTransferSpec(
214:                             restoreStateHandles.get(bestStateHandleForInit),
215:                             new Path(forstBasePath, DB_DIR_STRING)));
216:         }
217:         for (int i = 0; i < restoreStateHandles.size(); i++) {
218:             if (i != bestStateHandleForInit) {
219:                 IncrementalRemoteKeyedStateHandle handle = restoreStateHandles.get(i);
220:                 toTransferSpecs.add(
221:                         new StateHandleTransferSpec(
222:                                 handle, new Path(forstBasePath, UUID.randomUUID().toString())));
223:             }
224:         }
225: 
226:         try {
227:             runAndReportDuration(
228:                     () -> transferAllStateHandles(toTransferSpecs),
229:                     // TODO: use new metric name, such as "TransferStateDurationMs"
230:                     DOWNLOAD_STATE_DURATION);
231: 
232:             runAndReportDuration(() -> innerRestore(toTransferSpecs), RESTORE_STATE_DURATION);
233: 
234:             return new ForStRestoreResult(
235:                     this.forstHandle.getDb(),
236:                     this.forstHandle.getDefaultColumnFamilyHandle(),
237:                     this.forstHandle.getNativeMetricMonitor(),
238:                     lastCompletedCheckpointId,
239:                     backendUID,
240:                     restoredSstFiles);
241:         } finally {
242:             if (!useIngestDbRestoreMode || restoreStateHandles.size() == 1) {
243:                 toTransferSpecs.remove(0);
244:             }
245:             // Delete the transfer destination quietly.
246:             toTransferSpecs.stream()
247:                     .map(StateHandleTransferSpec::getTransferDestination)
248:                     .forEach(
249:                             dir -> {
250:                                 try {
251:                                     FileSystem fs = getFileSystem(dir);
252:                                     fs.delete(dir, true);
253:                                 } catch (IOException ignored) {
254:                                     logger.warn("Failed to delete transfer destination {}", dir);
255:                                 }
256:                             });
257:         }
258:     }
