260:     private void transferAllStateHandles(List<StateHandleTransferSpec> specs) throws Exception {
261:         try (ForStStateDataTransfer transfer =
262:                 new ForStStateDataTransfer(
263:                         ForStStateDataTransfer.DEFAULT_THREAD_NUM,
264:                         optionsContainer.getFileSystem())) {
265:             transfer.transferAllStateDataToDirectory(
266:                     specs, cancelStreamRegistry, recoveryClaimMode);
267:         }
268:     }
