270:     private void innerRestore(List<StateHandleTransferSpec> stateHandles) throws Exception {
271:         if (stateHandles.size() == 1) {
272:             // This happens if we don't rescale and for some scale out scenarios.
273:             initBaseDBFromSingleStateHandle(stateHandles.get(0));
274:         } else {
275:             // This happens for all scale ins and some scale outs.
276:             restoreFromMultipleStateHandles(stateHandles);
277:         }
278:     }
279: 
280:     /**
281:      * Initializes the base DB that we restore from a single local state handle.
282:      *
283:      * @param stateHandleSpec the state handle to restore the base DB from.
284:      * @throws Exception on any error during restore.
285:      */
286:     private void initBaseDBFromSingleStateHandle(StateHandleTransferSpec stateHandleSpec)
287:             throws Exception {
288:         IncrementalRemoteKeyedStateHandle stateHandle = stateHandleSpec.getStateHandle();
289:         logger.info(
290:                 "Starting opening base ForSt instance in operator {} with target key-group range {} from state handle {}.",
291:                 operatorIdentifier,
292:                 keyGroupRange.prettyPrintInterval(),
293:                 stateHandleSpec);
294: 
295:         // Restore base DB from selected initial handle
296:         restoreBaseDBFromMainHandle(stateHandleSpec);
297: 
298:         KeyGroupRange stateHandleKeyGroupRange = stateHandle.getKeyGroupRange();
299: 
300:         // Check if the key-groups range has changed.
301:         if (Objects.equals(stateHandleKeyGroupRange, keyGroupRange)) {
302:             // This is the case if we didn't rescale, so we can restore all the info from the
303:             // previous backend instance (backend id and incremental checkpoint history).
304:             restorePreviousIncrementalFilesStatus(stateHandle);
305:         } else {
306:             // If the key-groups don't match, this was a scale out, and we need to clip the
307:             // key-groups range of the db to the target range for this backend.
308:             try {
309:                 clipDBWithKeyGroupRange(
310:                         this.forstHandle.getDb(),
311:                         this.forstHandle.getColumnFamilyHandles(),
312:                         keyGroupRange,
313:                         stateHandleKeyGroupRange,
314:                         keyGroupPrefixBytes,
315:                         useDeleteFilesInRange);
316:             } catch (RocksDBException e) {
317:                 String errMsg = "Failed to clip DB after initialization.";
318:                 logger.error(errMsg, e);
319:                 throw new BackendBuildingException(errMsg, e);
320:             }
321:         }
322:         logger.info(
323:                 "Finished opening base ForSt instance in operator {} with target key-group range {}.",
324:                 operatorIdentifier,
325:                 keyGroupRange.prettyPrintInterval());
326:     }
