328:     /**
329:      * Initializes the base DB that we restore from a list of multiple local state handles.
330:      *
331:      * @param stateHandles the list of state handles to restore the base DB from.
332:      * @throws Exception on any error during restore.
333:      */
334:     private void restoreFromMultipleStateHandles(List<StateHandleTransferSpec> stateHandles)
335:             throws Exception {
336: 
337:         logger.info(
338:                 "Starting to restore backend with range {} in operator {} from multiple state handles {} with useIngestDbRestoreMode = {}.",
339:                 keyGroupRange.prettyPrintInterval(),
340:                 operatorIdentifier,
341:                 stateHandles,
342:                 useIngestDbRestoreMode);
343: 
344:         byte[] startKeyGroupPrefixBytes = new byte[keyGroupPrefixBytes];
345:         CompositeKeySerializationUtils.serializeKeyGroup(
346:                 keyGroupRange.getStartKeyGroup(), startKeyGroupPrefixBytes);
347: 
348:         byte[] stopKeyGroupPrefixBytes = new byte[keyGroupPrefixBytes];
349:         CompositeKeySerializationUtils.serializeKeyGroup(
350:                 keyGroupRange.getEndKeyGroup() + 1, stopKeyGroupPrefixBytes);
351: 
352:         if (useIngestDbRestoreMode) {
353:             // Optimized path for merging multiple handles with Ingest/Clip
354:             mergeStateHandlesWithClipAndIngest(
355:                     stateHandles, startKeyGroupPrefixBytes, stopKeyGroupPrefixBytes);
356:         } else {
357:             // Optimized path for single handle and legacy path for merging multiple handles.
358:             StateHandleTransferSpec baseSpec = stateHandles.remove(0);
359:             mergeStateHandlesWithCopyFromTemporaryInstance(
360:                     baseSpec, stateHandles, startKeyGroupPrefixBytes, stopKeyGroupPrefixBytes);
361:         }
362:         logger.info(
363:                 "Completed restoring backend with range {} in operator {} from multiple state handles with useIngestDbRestoreMode = {}.",
364:                 keyGroupRange.prettyPrintInterval(),
365:                 operatorIdentifier,
366:                 useIngestDbRestoreMode);
367:     }
