369:     private void restoreBaseDBFromMainHandle(StateHandleTransferSpec handleSpec) throws Exception {
370:         KeyedBackendSerializationProxy<K> serializationProxy =
371:                 readMetaData(handleSpec.getStateHandle().getMetaDataStateHandle());
372:         List<StateMetaInfoSnapshot> stateMetaInfoSnapshots =
373:                 serializationProxy.getStateMetaInfoSnapshots();
374:         this.forstHandle.openDB(
375:                 createColumnFamilyDescriptors(stateMetaInfoSnapshots, true),
376:                 stateMetaInfoSnapshots,
377:                 cancelStreamRegistry);
378:     }
