380:     /**
381:      * Restores the checkpointing status and state for this backend. This can only be done if the
382:      * backend was not rescaled and is therefore identical to the source backend in the previous
383:      * run.
384:      *
385:      * @param incrementalHandle the single state handle from which the backend is restored.
386:      */
387:     private void restorePreviousIncrementalFilesStatus(
388:             IncrementalKeyedStateHandle incrementalHandle) {
389:         backendUID = incrementalHandle.getBackendIdentifier();
390:         restoredSstFiles.put(
391:                 incrementalHandle.getCheckpointId(), incrementalHandle.getSharedStateHandles());
392:         lastCompletedCheckpointId = incrementalHandle.getCheckpointId();
393:         logger.info(
394:                 "Restored previous incremental files status in backend with range {} in operator {}: backend uuid {}, last checkpoint id {}.",
395:                 keyGroupRange.prettyPrintInterval(),
396:                 operatorIdentifier,
397:                 backendUID,
398:                 lastCompletedCheckpointId);
399:     }
