401:     /**
402:      * This method recreates and registers all {@link ColumnFamilyDescriptor} from Flink's state
403:      * metadata snapshot.
404:      */
405:     private List<ColumnFamilyDescriptor> createColumnFamilyDescriptors(
406:             List<StateMetaInfoSnapshot> stateMetaInfoSnapshots, boolean registerTtlCompactFilter) {
407: 
408:         List<ColumnFamilyDescriptor> columnFamilyDescriptors =
409:                 new ArrayList<>(stateMetaInfoSnapshots.size());
410: 
411:         for (StateMetaInfoSnapshot stateMetaInfoSnapshot : stateMetaInfoSnapshots) {
412:             RegisteredStateMetaInfoBase metaInfoBase =
413:                     RegisteredStateMetaInfoBase.fromMetaInfoSnapshot(stateMetaInfoSnapshot);
414: 
415:             ColumnFamilyDescriptor columnFamilyDescriptor =
416:                     ForStOperationUtils.createColumnFamilyDescriptor(
417:                             metaInfoBase,
418:                             this.forstHandle.getColumnFamilyOptionsFactory(),
419:                             registerTtlCompactFilter
420:                                     ? this.forstHandle.getTtlCompactFiltersManager()
421:                                     : null,
422:                             this.forstHandle.getWriteBufferManagerCapacity());
423: 
424:             columnFamilyDescriptors.add(columnFamilyDescriptor);
425:         }
426:         return columnFamilyDescriptors;
427:     }
