429:     private void runAndReportDuration(RunnableWithException runnable, String metricName)
430:             throws Exception {
431:         final SystemClock clock = SystemClock.getInstance();
432:         final long startTime = clock.relativeTimeMillis();
433:         runnable.run();
434:         customInitializationMetrics.addMetric(metricName, clock.relativeTimeMillis() - startTime);
435:     }
