437:     /** Reads Flink's state meta data file from the state handle. */
438:     private KeyedBackendSerializationProxy<K> readMetaData(StreamStateHandle metaStateHandle)
439:             throws Exception {
440: 
441:         InputStream inputStream = null;
442: 
443:         try {
444:             inputStream = metaStateHandle.openInputStream();
445:             cancelStreamRegistry.registerCloseable(inputStream);
446:             DataInputView in = new DataInputViewStreamWrapper(inputStream);
447:             return readMetaData(in);
448:         } finally {
449:             if (cancelStreamRegistry.unregisterCloseable(inputStream)) {
450:                 inputStream.close();
451:             }
452:         }
453:     }
454: 
455:     KeyedBackendSerializationProxy<K> readMetaData(DataInputView dataInputView)
456:             throws IOException, StateMigrationException {
457:         // isSerializerPresenceRequired flag is set to false, since for the RocksDB state backend,
458:         // deserialization of state happens lazily during runtime; we depend on the fact
459:         // that the new serializer for states could be compatible, and therefore the restore can
460:         // continue
461:         // without old serializers required to be present.
462:         KeyedBackendSerializationProxy<K> serializationProxy =
463:                 new KeyedBackendSerializationProxy<>(userCodeClassLoader);
464:         serializationProxy.read(dataInputView);
465:         if (!isKeySerializerCompatibilityChecked) {
466:             // fetch current serializer now because if it is incompatible, we can't access
467:             // it anymore to improve the error message
468:             TypeSerializer<K> currentSerializer = keySerializerProvider.currentSchemaSerializer();
469:             // check for key serializer compatibility; this also reconfigures the
470:             // key serializer to be compatible, if it is required and is possible
471:             TypeSerializerSchemaCompatibility<K> keySerializerSchemaCompat =
472:                     keySerializerProvider.setPreviousSerializerSnapshotForRestoredState(
473:                             serializationProxy.getKeySerializerSnapshot());
474:             if (keySerializerSchemaCompat.isCompatibleAfterMigration()
475:                     || keySerializerSchemaCompat.isIncompatible()) {
476:                 throw new StateMigrationException(
477:                         "The new key serializer ("
478:                                 + currentSerializer
479:                                 + ") must be compatible with the previous key serializer ("
480:                                 + keySerializerProvider.previousSchemaSerializer()
481:                                 + ").");
482:             }
483: 
484:             isKeySerializerCompatibilityChecked = true;
485:         }
486: 
487:         return serializationProxy;
488:     }
