495:     /**
496:      * Helper method tp copy all data from an open temporary DB to the base DB.
497:      *
498:      * @param tmpRestoreDBInfo the temporary instance.
499:      * @param writeBatchWrapper write batch wrapper for writes against the base DB.
500:      * @param startKeyGroupPrefixBytes the min/start key of the key groups range as bytes.
501:      * @param stopKeyGroupPrefixBytes the max+1/end key of the key groups range as bytes.
502:      * @throws Exception on any copy error.
503:      */
504:     private void copyTempDbIntoBaseDb(
505:             RestoredDBInstance tmpRestoreDBInfo,
506:             ForStDBWriteBatchWrapper writeBatchWrapper,
507:             byte[] startKeyGroupPrefixBytes,
508:             byte[] stopKeyGroupPrefixBytes)
509:             throws Exception {
510:         logger.debug(
511:                 "Starting copy of state handle {} for backend with range {} in operator {} to base DB using temporary instance.",
512:                 tmpRestoreDBInfo.srcStateHandle,
513:                 keyGroupRange.prettyPrintInterval(),
514:                 operatorIdentifier);
515: 
516:         List<ColumnFamilyDescriptor> tmpColumnFamilyDescriptors =
517:                 tmpRestoreDBInfo.columnFamilyDescriptors;
518:         List<ColumnFamilyHandle> tmpColumnFamilyHandles = tmpRestoreDBInfo.columnFamilyHandles;
519: 
520:         // iterating only the requested descriptors automatically skips the default column family
521:         // handle
522:         for (int descIdx = 0; descIdx < tmpColumnFamilyDescriptors.size(); ++descIdx) {
523:             ColumnFamilyHandle tmpColumnFamilyHandle = tmpColumnFamilyHandles.get(descIdx);
524: 
525:             ColumnFamilyHandle targetColumnFamilyHandle =
526:                     this.forstHandle.getOrRegisterStateColumnFamilyHandle(
527:                                     null,
528:                                     tmpRestoreDBInfo.stateMetaInfoSnapshots.get(descIdx),
529:                                     cancelStreamRegistry)
530:                             .columnFamilyHandle;
531: 
532:             try (ForStIteratorWrapper iterator =
533:                     ForStOperationUtils.getForStIterator(
534:                             tmpRestoreDBInfo.db,
535:                             tmpColumnFamilyHandle,
536:                             tmpRestoreDBInfo.readOptions)) {
537: 
538:                 iterator.seek(startKeyGroupPrefixBytes);
539: 
540:                 while (iterator.isValid()) {
541: 
542:                     if (beforeThePrefixBytes(iterator.key(), stopKeyGroupPrefixBytes)) {
543:                         writeBatchWrapper.put(
544:                                 targetColumnFamilyHandle, iterator.key(), iterator.value());
545:                     } else {
546:                         // Since the iterator will visit the record according to the sorted order,
547:                         // we can just break here.
548:                         break;
549:                     }
550: 
551:                     iterator.next();
552:                 }
553:             } // releases native iterator resources
554:         }
555:         logger.debug(
556:                 "Finished copy of state handle {} for backend with range {} in operator {} using temporary instance.",
557:                 tmpRestoreDBInfo.srcStateHandle,
558:                 keyGroupRange.prettyPrintInterval(),
559:                 operatorIdentifier);
560:     }
