570:     /**
571:      * Helper method to copy all data from the given local state handles to the base DB by using
572:      * temporary DB instances.
573:      *
574:      * @param toImportSpecs the state handles to import.
575:      * @param startKeyGroupPrefixBytes the min/start key of the key groups range as bytes.
576:      * @param stopKeyGroupPrefixBytes the max+1/end key of the key groups range as bytes.
577:      * @throws Exception on any copy error.
578:      */
579:     private void copyToBaseDBUsingTempDBs(
580:             List<StateHandleTransferSpec> toImportSpecs,
581:             byte[] startKeyGroupPrefixBytes,
582:             byte[] stopKeyGroupPrefixBytes)
583:             throws Exception {
584:         if (toImportSpecs.isEmpty()) {
585:             return;
586:         }
587: 
588:         logger.info(
589:                 "Starting to copy state handles for backend with range {} in operator {} using temporary instances.",
590:                 keyGroupRange.prettyPrintInterval(),
591:                 operatorIdentifier);
592: 
593:         try (ForStDBWriteBatchWrapper writeBatchWrapper =
594:                         new ForStDBWriteBatchWrapper(this.forstHandle.getDb(), writeBatchSize);
595:                 Closeable ignored =
596:                         cancelStreamRegistry.registerCloseableTemporarily(
597:                                 writeBatchWrapper.getCancelCloseable())) {
598:             for (StateHandleTransferSpec handleToCopy : toImportSpecs) {
599:                 try (RestoredDBInstance restoredDBInstance = restoreTempDBInstance(handleToCopy)) {
600:                     copyTempDbIntoBaseDb(
601:                             restoredDBInstance,
602:                             writeBatchWrapper,
603:                             startKeyGroupPrefixBytes,
604:                             stopKeyGroupPrefixBytes);
605:                 }
606:             }
607:         }
608: 
609:         logger.info(
610:                 "Competed copying state handles for backend with range {} in operator {} using temporary instances.",
611:                 keyGroupRange.prettyPrintInterval(),
612:                 operatorIdentifier);
613:     }
