615:     /**
616:      * Helper method that merges the data from multiple state handles into the restoring base DB by
617:      * the help of copying through temporary RocksDB instances.
618:      *
619:      * @param keyedStateHandles the state handles to merge into the base DB.
620:      * @param startKeyGroupPrefixBytes the min/start key of the key groups range as bytes.
621:      * @param stopKeyGroupPrefixBytes the max+1/end key of the key groups range as bytes.
622:      * @throws Exception on any merge error.
623:      */
624:     private void mergeStateHandlesWithCopyFromTemporaryInstance(
625:             StateHandleTransferSpec baseSpec,
626:             List<StateHandleTransferSpec> keyedStateHandles,
627:             byte[] startKeyGroupPrefixBytes,
628:             byte[] stopKeyGroupPrefixBytes)
629:             throws Exception {
630: 
631:         logger.info(
632:                 "Starting to merge state for backend with range {} in operator {} from multiple state handles using temporary instances.",
633:                 keyGroupRange.prettyPrintInterval(),
634:                 operatorIdentifier);
635: 
636:         // Init the base DB instance with the initial state
637:         initBaseDBFromSingleStateHandle(baseSpec);
638: 
639:         // Copy remaining handles using temporary RocksDB instances
640:         copyToBaseDBUsingTempDBs(
641:                 keyedStateHandles, startKeyGroupPrefixBytes, stopKeyGroupPrefixBytes);
642: 
643:         logger.info(
644:                 "Completed merging state for backend with range {} in operator {} from multiple state handles using temporary instances.",
645:                 keyGroupRange.prettyPrintInterval(),
646:                 operatorIdentifier);
647:     }
