83:         for (Map.Entry<OperatorID, OperatorSubtaskState> subtaskStateEntry :
84:                 localState.getSubtaskStateMappings()) {
85:             for (KeyedStateHandle keyedStateHandle :
86:                     subtaskStateEntry.getValue().getManagedKeyedState()) {
87:                 if (keyedStateHandle instanceof ChangelogStateBackendHandle) {
88:                     ChangelogStateBackendHandle changelogStateBackendHandle =
89:                             (ChangelogStateBackendHandle) keyedStateHandle;
90:                     long materializationID = changelogStateBackendHandle.getMaterializationID();
91:                     if (mapToMaterializationId.containsKey(checkpointId)) {
92:                         checkState(
93:                                 materializationID == mapToMaterializationId.get(checkpointId),
94:                                 "one checkpoint contains at most one materializationID");
95:                     } else {
96:                         mapToMaterializationId.put(checkpointId, materializationID);
97:                     }
98:                 }
99:             }
100:         }
101:     }
