103:     public static Path getLocalTaskOwnedDirectory(
104:             LocalSnapshotDirectoryProvider provider, JobID jobID) {
105:         File outDir =
106:                 provider.selectAllocationBaseDirectory(
107:                         (jobID.hashCode() & Integer.MAX_VALUE)
108:                                 % provider.allocationBaseDirsCount());
109:         if (!outDir.exists() && !outDir.mkdirs()) {
110:             LOG.error(
111:                     "Local state base directory does not exist and could not be created: "
112:                             + outDir);
