120:         if (checkpointId < lastCheckpointId) {
121:             LOG.info(
122:                     "Current checkpoint {} is out of order, smaller than last CheckpointId {}.",
123:                     lastCheckpointId,
124:                     checkpointId);
125:             return;
126:         } else {
127:             lastCheckpointId = checkpointId;
128:         }
129:         synchronized (lock) {
130:             updateReference(checkpointId, localState);
131:         }
132:         super.storeLocalState(checkpointId, localState);
133:     }
