142:     private void deleteMaterialization(LongPredicate pruningChecker) {
143:         Set<Long> materializationToRemove;
144:         synchronized (lock) {
145:             Set<Long> checkpoints =
146:                     mapToMaterializationId.keySet().stream()
147:                             .filter(pruningChecker::test)
148:                             .collect(Collectors.toSet());
149:             materializationToRemove =
150:                     checkpoints.stream()
151:                             .map(mapToMaterializationId::remove)
152:                             .collect(Collectors.toSet());
153:             materializationToRemove.removeAll(mapToMaterializationId.values());
154:         }
155: 
156:         discardExecutor.execute(
157:                 () ->
158:                         syncDiscardFileForCollection(
159:                                 materializationToRemove.stream()
160:                                         .map(super::getCheckpointDirectory)
161:                                         .collect(Collectors.toList())));
162:     }
163: 
164:     private void syncDiscardFileForCollection(Collection<File> toDiscard) {
165:         for (File directory : toDiscard) {
166:             if (directory.exists()) {
167:                 try {
168:                     // TODO: This is guaranteed by the wrapped backend only using this folder for
169:                     // its local state, the materialized handle should be discarded here too.
170:                     deleteDirectory(directory);
171:                 } catch (IOException ex) {
172:                     LOG.warn(
173:                             "Exception while deleting local state directory of {} in subtask ({} - {} - {}).",
174:                             directory,
175:                             jobID,
176:                             jobVertexID,
177:                             subtaskIndex,
178:                             ex);
179:                 }
180:             }
181:         }
182:     }
183: 
184:     @Override
185:     public void pruneCheckpoints(LongPredicate pruningChecker, boolean breakOnceCheckerFalse) {
186:         // Scenarios:
187:         //   c1,m1
188:         //   confirm c1, do nothing.
189:         //   c2,m1
190:         //   confirm c2, delete c1, don't delete m1
191:         //   c3,m2
192:         //   confirm c3, delete c2, delete m1
193: 
194:         // delete changelog-chk
195:         super.pruneCheckpoints(pruningChecker, false);
196:         deleteMaterialization(pruningChecker);
197:     }
198: 
199:     @Override
200:     public CompletableFuture<Void> dispose() {
201:         deleteMaterialization(id -> true);
202:         // delete all ChangelogStateHandle in taskowned directory.
203:         discardExecutor.execute(
204:                 () ->
205:                         syncDiscardFileForCollection(
206:                                 Collections.singleton(
207:                                         new File(
208:                                                 getLocalTaskOwnedDirectory(
209:                                                                 getLocalRecoveryDirectoryProvider(),
210:                                                                 jobID)
211:                                                         .toUri()))));
