167:     public ResultFetcher callMaterializedTableOperation(
168:             OperationExecutor operationExecutor,
169:             OperationHandle handle,
170:             MaterializedTableOperation op,
171:             String statement) {
172:         if (op instanceof CreateMaterializedTableOperation) {
173:             return callCreateMaterializedTableOperation(
174:                     operationExecutor, handle, (CreateMaterializedTableOperation) op);
175:         } else if (op instanceof AlterMaterializedTableRefreshOperation) {
176:             return callAlterMaterializedTableRefreshOperation(
177:                     operationExecutor, handle, (AlterMaterializedTableRefreshOperation) op);
178:         } else if (op instanceof AlterMaterializedTableSuspendOperation) {
179:             return callAlterMaterializedTableSuspend(
180:                     operationExecutor, handle, (AlterMaterializedTableSuspendOperation) op);
181:         } else if (op instanceof AlterMaterializedTableResumeOperation) {
182:             return callAlterMaterializedTableResume(
183:                     operationExecutor, handle, (AlterMaterializedTableResumeOperation) op);
184:         } else if (op instanceof DropMaterializedTableOperation) {
185:             return callDropMaterializedTableOperation(
186:                     operationExecutor, handle, (DropMaterializedTableOperation) op);
187:         } else if (op instanceof AlterMaterializedTableAsQueryOperation) {
188:             return callAlterMaterializedTableAsQueryOperation(
189:                     operationExecutor, handle, (AlterMaterializedTableAsQueryOperation) op);
190:         }
191: 
192:         throw new SqlExecutionException(
193:                 String.format(
194:                         "Unsupported Operation %s for materialized table.", op.asSummaryString()));
195:     }
