197:     private ResultFetcher callCreateMaterializedTableOperation(
198:             OperationExecutor operationExecutor,
199:             OperationHandle handle,
200:             CreateMaterializedTableOperation createMaterializedTableOperation) {
201:         CatalogMaterializedTable materializedTable =
202:                 createMaterializedTableOperation.getCatalogMaterializedTable();
203:         if (CatalogMaterializedTable.RefreshMode.CONTINUOUS == materializedTable.getRefreshMode()) {
204:             createMaterializedTableInContinuousMode(
205:                     operationExecutor, handle, createMaterializedTableOperation);
206:         } else {
207:             createMaterializedTableInFullMode(
208:                     operationExecutor, handle, createMaterializedTableOperation);
209:         }
210:         // Just return ok for unify different refresh job info of continuous and full mode, user
211:         // should get the refresh job info via desc table.
212:         return ResultFetcher.fromTableResult(handle, TABLE_RESULT_OK, false);
213:     }
