215:     private void createMaterializedTableInContinuousMode(
216:             OperationExecutor operationExecutor,
217:             OperationHandle handle,
218:             CreateMaterializedTableOperation createMaterializedTableOperation) {
219:         // create materialized table first
220:         operationExecutor.callExecutableOperation(handle, createMaterializedTableOperation);
221: 
222:         ObjectIdentifier materializedTableIdentifier =
223:                 createMaterializedTableOperation.getTableIdentifier();
224:         CatalogMaterializedTable catalogMaterializedTable =
225:                 createMaterializedTableOperation.getCatalogMaterializedTable();
226: 
227:         try {
228:             executeContinuousRefreshJob(
229:                     operationExecutor,
230:                     handle,
231:                     catalogMaterializedTable,
232:                     materializedTableIdentifier,
233:                     Collections.emptyMap(),
234:                     Optional.empty());
235:         } catch (Exception e) {
236:             // drop materialized table while submit flink streaming job occur exception. Thus, weak
237:             // atomicity is guaranteed
238:             operationExecutor.callExecutableOperation(
239:                     handle, new DropMaterializedTableOperation(materializedTableIdentifier, true));
240:             throw new SqlExecutionException(
241:                     String.format(
242:                             "Submit continuous refresh job for materialized table %s occur exception.",
243:                             materializedTableIdentifier),
244:                     e);
245:         }
246:     }
