248:     private void createMaterializedTableInFullMode(
249:             OperationExecutor operationExecutor,
250:             OperationHandle handle,
251:             CreateMaterializedTableOperation createMaterializedTableOperation) {
252:         if (workflowScheduler == null) {
253:             throw new SqlExecutionException(
254:                     "The workflow scheduler must be configured when creating materialized table in full refresh mode.");
255:         }
256:         // create materialized table first
257:         operationExecutor.callExecutableOperation(handle, createMaterializedTableOperation);
258: 
259:         ObjectIdentifier materializedTableIdentifier =
260:                 createMaterializedTableOperation.getTableIdentifier();
261:         CatalogMaterializedTable catalogMaterializedTable =
262:                 createMaterializedTableOperation.getCatalogMaterializedTable();
263: 
264:         // convert duration to cron expression
265:         String cronExpression =
266:                 convertFreshnessToCron(catalogMaterializedTable.getDefinitionFreshness());
267:         // create full refresh job
268:         CreateRefreshWorkflow createRefreshWorkflow =
269:                 new CreatePeriodicRefreshWorkflow(
270:                         materializedTableIdentifier,
271:                         catalogMaterializedTable.getDefinitionQuery(),
272:                         cronExpression,
273:                         getSessionInitializationConf(operationExecutor),
274:                         Collections.emptyMap(),
275:                         restEndpointUrl);
276: 
277:         try {
278:             RefreshHandler refreshHandler =
279:                     workflowScheduler.createRefreshWorkflow(createRefreshWorkflow);
280:             RefreshHandlerSerializer refreshHandlerSerializer =
281:                     workflowScheduler.getRefreshHandlerSerializer();
282:             byte[] serializedRefreshHandler = refreshHandlerSerializer.serialize(refreshHandler);
283: 
284:             updateRefreshHandler(
285:                     operationExecutor,
286:                     handle,
287:                     materializedTableIdentifier,
288:                     catalogMaterializedTable,
289:                     CatalogMaterializedTable.RefreshStatus.ACTIVATED,
290:                     refreshHandler.asSummaryString(),
291:                     serializedRefreshHandler);
292:         } catch (Exception e) {
293:             // drop materialized table while create refresh workflow occur exception. Thus, weak
294:             // atomicity is guaranteed
295:             operationExecutor.callExecutableOperation(
296:                     handle, new DropMaterializedTableOperation(materializedTableIdentifier, true));
297:             throw new SqlExecutionException(
298:                     String.format(
299:                             "Failed to create refresh workflow for materialized table %s.",
300:                             materializedTableIdentifier),
301:                     e);
302:         }
303:     }
