305:     private ResultFetcher callAlterMaterializedTableSuspend(
306:             OperationExecutor operationExecutor,
307:             OperationHandle handle,
308:             AlterMaterializedTableSuspendOperation op) {
309:         ObjectIdentifier tableIdentifier = op.getTableIdentifier();
310:         CatalogMaterializedTable materializedTable =
311:                 getCatalogMaterializedTable(operationExecutor, tableIdentifier);
312: 
313:         // Initialization phase doesn't support resume operation.
314:         if (CatalogMaterializedTable.RefreshStatus.INITIALIZING
315:                 == materializedTable.getRefreshStatus()) {
316:             throw new SqlExecutionException(
317:                     String.format(
318:                             "Materialized table %s is being initialized and does not support suspend operation.",
319:                             tableIdentifier));
320:         }
321: 
322:         if (CatalogMaterializedTable.RefreshMode.CONTINUOUS == materializedTable.getRefreshMode()) {
323:             suspendContinuousRefreshJob(
324:                     operationExecutor, handle, tableIdentifier, materializedTable);
325:         } else {
326:             suspendRefreshWorkflow(operationExecutor, handle, tableIdentifier, materializedTable);
327:         }
328:         return ResultFetcher.fromTableResult(handle, TABLE_RESULT_OK, false);
329:     }
