331:     private CatalogMaterializedTable suspendContinuousRefreshJob(
332:             OperationExecutor operationExecutor,
333:             OperationHandle handle,
334:             ObjectIdentifier tableIdentifier,
335:             CatalogMaterializedTable materializedTable) {
336:         try {
337:             ContinuousRefreshHandler refreshHandler =
338:                     deserializeContinuousHandler(materializedTable.getSerializedRefreshHandler());
339: 
340:             if (CatalogMaterializedTable.RefreshStatus.SUSPENDED
341:                     == materializedTable.getRefreshStatus()) {
342:                 throw new SqlExecutionException(
343:                         String.format(
344:                                 "Materialized table %s continuous refresh job has been suspended, jobId is %s.",
345:                                 tableIdentifier, refreshHandler.getJobId()));
346:             }
347: 
348:             String savepointPath = stopJobWithSavepoint(operationExecutor, handle, refreshHandler);
349: 
350:             ContinuousRefreshHandler updateRefreshHandler =
351:                     new ContinuousRefreshHandler(
352:                             refreshHandler.getExecutionTarget(),
353:                             refreshHandler.getClusterId(),
354:                             refreshHandler.getJobId(),
355:                             savepointPath);
356: 
357:             return updateRefreshHandler(
358:                     operationExecutor,
359:                     handle,
360:                     tableIdentifier,
361:                     materializedTable,
362:                     CatalogMaterializedTable.RefreshStatus.SUSPENDED,
363:                     updateRefreshHandler.asSummaryString(),
364:                     serializeContinuousHandler(updateRefreshHandler));
365:         } catch (Exception e) {
366:             throw new SqlExecutionException(
367:                     String.format(
368:                             "Failed to suspend the continuous refresh job for materialized table %s.",
369:                             tableIdentifier),
370:                     e);
371:         }
372:     }
