374:     private void suspendRefreshWorkflow(
375:             OperationExecutor operationExecutor,
376:             OperationHandle handle,
377:             ObjectIdentifier tableIdentifier,
378:             CatalogMaterializedTable materializedTable) {
379:         if (CatalogMaterializedTable.RefreshStatus.SUSPENDED
380:                 == materializedTable.getRefreshStatus()) {
381:             throw new SqlExecutionException(
382:                     String.format(
383:                             "Materialized table %s refresh workflow has been suspended.",
384:                             tableIdentifier));
385:         }
386: 
387:         if (workflowScheduler == null) {
388:             throw new SqlExecutionException(
389:                     "The workflow scheduler must be configured when suspending materialized table in full refresh mode.");
390:         }
391: 
392:         try {
393:             RefreshHandlerSerializer<?> refreshHandlerSerializer =
394:                     workflowScheduler.getRefreshHandlerSerializer();
395:             RefreshHandler refreshHandler =
396:                     refreshHandlerSerializer.deserialize(
397:                             materializedTable.getSerializedRefreshHandler(), userCodeClassLoader);
398:             ModifyRefreshWorkflow modifyRefreshWorkflow =
399:                     new SuspendRefreshWorkflow(refreshHandler);
400:             workflowScheduler.modifyRefreshWorkflow(modifyRefreshWorkflow);
401: 
402:             updateRefreshHandler(
403:                     operationExecutor,
404:                     handle,
405:                     tableIdentifier,
406:                     materializedTable,
407:                     CatalogMaterializedTable.RefreshStatus.SUSPENDED,
408:                     refreshHandler.asSummaryString(),
409:                     materializedTable.getSerializedRefreshHandler());
410:         } catch (Exception e) {
411:             throw new SqlExecutionException(
412:                     String.format(
413:                             "Failed to suspend the refresh workflow for materialized table %s.",
414:                             tableIdentifier),
415:                     e);
416:         }
417:     }
