456:     private void resumeContinuousRefreshJob(
457:             OperationExecutor operationExecutor,
458:             OperationHandle handle,
459:             ObjectIdentifier tableIdentifier,
460:             CatalogMaterializedTable catalogMaterializedTable,
461:             Map<String, String> dynamicOptions) {
462:         ContinuousRefreshHandler refreshHandler =
463:                 deserializeContinuousHandler(
464:                         catalogMaterializedTable.getSerializedRefreshHandler());
465: 
466:         // Repeated resume continuous refresh job is not supported
467:         if (CatalogMaterializedTable.RefreshStatus.ACTIVATED
468:                 == catalogMaterializedTable.getRefreshStatus()) {
469:             JobStatus jobStatus = getJobStatus(operationExecutor, handle, refreshHandler);
470:             if (!jobStatus.isGloballyTerminalState()) {
471:                 throw new SqlExecutionException(
472:                         String.format(
473:                                 "Materialized table %s continuous refresh job has been resumed, jobId is %s.",
474:                                 tableIdentifier, refreshHandler.getJobId()));
475:             }
476:         }
477: 
478:         Optional<String> restorePath = refreshHandler.getRestorePath();
479:         try {
480:             executeContinuousRefreshJob(
481:                     operationExecutor,
482:                     handle,
483:                     catalogMaterializedTable,
484:                     tableIdentifier,
485:                     dynamicOptions,
486:                     restorePath);
487:         } catch (Exception e) {
488:             throw new SqlExecutionException(
489:                     String.format(
490:                             "Failed to resume the continuous refresh job for materialized table %s.",
491:                             tableIdentifier),
492:                     e);
493:         }
494:     }
