497:             OperationExecutor operationExecutor,
498:             OperationHandle handle,
499:             ObjectIdentifier tableIdentifier,
500:             CatalogMaterializedTable catalogMaterializedTable,
501:             Map<String, String> dynamicOptions) {
502:         // Repeated resume refresh workflow is not supported
503:         if (CatalogMaterializedTable.RefreshStatus.ACTIVATED
504:                 == catalogMaterializedTable.getRefreshStatus()) {
505:             throw new SqlExecutionException(
506:                     String.format(
507:                             "Materialized table %s refresh workflow has been resumed.",
508:                             tableIdentifier));
509:         }
510: 
511:         if (workflowScheduler == null) {
512:             throw new SqlExecutionException(
513:                     "The workflow scheduler must be configured when resuming materialized table in full refresh mode.");
514:         }
515:         try {
516:             RefreshHandlerSerializer<?> refreshHandlerSerializer =
517:                     workflowScheduler.getRefreshHandlerSerializer();
518:             RefreshHandler refreshHandler =
519:                     refreshHandlerSerializer.deserialize(
520:                             catalogMaterializedTable.getSerializedRefreshHandler(),
521:                             userCodeClassLoader);
522:             ModifyRefreshWorkflow modifyRefreshWorkflow =
523:                     new ResumeRefreshWorkflow(refreshHandler, dynamicOptions);
524:             workflowScheduler.modifyRefreshWorkflow(modifyRefreshWorkflow);
525: 
526:             updateRefreshHandler(
527:                     operationExecutor,
528:                     handle,
529:                     tableIdentifier,
530:                     catalogMaterializedTable,
531:                     CatalogMaterializedTable.RefreshStatus.ACTIVATED,
532:                     refreshHandler.asSummaryString(),
533:                     catalogMaterializedTable.getSerializedRefreshHandler());
534:         } catch (Exception e) {
535:             throw new SqlExecutionException(
536:                     String.format(
537:                             "Failed to resume the refresh workflow for materialized table %s.",
538:                             tableIdentifier),
539:                     e);
540:         }
541:     }
