543:     private void executeContinuousRefreshJob(
544:             OperationExecutor operationExecutor,
545:             OperationHandle handle,
546:             CatalogMaterializedTable catalogMaterializedTable,
547:             ObjectIdentifier materializedTableIdentifier,
548:             Map<String, String> dynamicOptions,
549:             Optional<String> restorePath) {
550:         // Set job name, runtime mode, checkpoint interval
551:         // TODO: Set minibatch related optimization options.
552:         Configuration customConfig = new Configuration();
553:         String jobName =
554:                 String.format(
555:                         "Materialized_table_%s_continuous_refresh_job",
556:                         materializedTableIdentifier.asSerializableString());
557:         customConfig.set(NAME, jobName);
558:         customConfig.set(RUNTIME_MODE, STREAMING);
559:         restorePath.ifPresent(s -> customConfig.set(SAVEPOINT_PATH, s));
560: 
561:         // Do not override the user-defined checkpoint interval
562:         if (!operationExecutor
563:                 .getSessionContext()
564:                 .getSessionConf()
565:                 .contains(CheckpointingOptions.CHECKPOINTING_INTERVAL)) {
566:             customConfig.set(
567:                     CheckpointingOptions.CHECKPOINTING_INTERVAL,
568:                     catalogMaterializedTable.getFreshness());
569:         }
570: 
571:         String insertStatement =
572:                 getInsertStatement(
573:                         materializedTableIdentifier,
574:                         catalogMaterializedTable.getDefinitionQuery(),
575:                         dynamicOptions);
576: 
577:         JobExecutionResult result =
578:                 executeRefreshJob(insertStatement, customConfig, operationExecutor, handle);
579:         ContinuousRefreshHandler continuousRefreshHandler =
580:                 new ContinuousRefreshHandler(
581:                         result.executionTarget, result.clusterId, result.jobId);
582:         byte[] serializedBytes = serializeContinuousHandler(continuousRefreshHandler);
583: 
584:         updateRefreshHandler(
585:                 operationExecutor,
586:                 handle,
587:                 materializedTableIdentifier,
588:                 catalogMaterializedTable,
589:                 CatalogMaterializedTable.RefreshStatus.ACTIVATED,
590:                 continuousRefreshHandler.asSummaryString(),
591:                 serializedBytes);
592:     }
