614:     public ResultFetcher refreshMaterializedTable(
615:             OperationExecutor operationExecutor,
616:             OperationHandle handle,
617:             ObjectIdentifier materializedTableIdentifier,
618:             Map<String, String> staticPartitions,
619:             Map<String, String> dynamicOptions,
620:             boolean isPeriodic,
621:             @Nullable String scheduleTime) {
622:         ResolvedCatalogMaterializedTable materializedTable =
623:                 getCatalogMaterializedTable(operationExecutor, materializedTableIdentifier);
624:         Map<String, String> refreshPartitions =
625:                 isPeriodic
626:                         ? getPeriodRefreshPartition(
627:                                 scheduleTime,
628:                                 materializedTable.getDefinitionFreshness(),
629:                                 materializedTableIdentifier,
630:                                 materializedTable.getOptions(),
631:                                 operationExecutor
632:                                         .getTableEnvironment()
633:                                         .getConfig()
634:                                         .getLocalTimeZone())
635:                         : staticPartitions;
636: 
637:         validatePartitionSpec(refreshPartitions, materializedTable);
638: 
639:         // Set job name, runtime mode
640:         Configuration customConfig = new Configuration();
641:         String jobName =
642:                 isPeriodic
643:                         ? String.format(
644:                                 "Materialized_table_%s_periodic_refresh_job",
645:                                 materializedTableIdentifier.asSerializableString())
646:                         : String.format(
647:                                 "Materialized_table_%s_one_time_refresh_job",
648:                                 materializedTableIdentifier.asSerializableString());
649: 
650:         customConfig.set(NAME, jobName);
651:         customConfig.set(RUNTIME_MODE, BATCH);
652: 
653:         String insertStatement =
654:                 getRefreshStatement(
655:                         materializedTableIdentifier,
656:                         materializedTable.getDefinitionQuery(),
657:                         refreshPartitions,
658:                         dynamicOptions);
659: 
660:         try {
661:             LOG.info(
662:                     "Begin to refreshing the materialized table {}, statement: {}",
663:                     materializedTableIdentifier,
664:                     insertStatement);
665:             JobExecutionResult result =
666:                     executeRefreshJob(insertStatement, customConfig, operationExecutor, handle);
667: 
668:             Map<StringData, StringData> clusterInfo = new HashMap<>();
669:             clusterInfo.put(
670:                     StringData.fromString(TARGET.key()),
671:                     StringData.fromString(result.executionTarget));
672:             Optional<String> clusterIdKeyName = getClusterIdKeyName(result.executionTarget);
673:             clusterIdKeyName.ifPresent(
674:                     s ->
675:                             clusterInfo.put(
676:                                     StringData.fromString(s),
677:                                     StringData.fromString(result.clusterId)));
678: 
679:             return ResultFetcher.fromResults(
680:                     handle,
681:                     ResolvedSchema.of(
682:                             Column.physical(JOB_ID, DataTypes.STRING()),
683:                             Column.physical(
684:                                     CLUSTER_INFO,
685:                                     DataTypes.MAP(DataTypes.STRING(), DataTypes.STRING()))),
686:                     Collections.singletonList(
687:                             GenericRowData.of(
688:                                     StringData.fromString(result.jobId),
689:                                     new GenericMapData(clusterInfo))));
690:         } catch (Exception e) {
691:             throw new SqlExecutionException(
692:                     String.format(
693:                             "Refreshing the materialized table %s occur exception.",
694:                             materializedTableIdentifier),
695:                     e);
696:         }
697:     }
