699:     @VisibleForTesting
700:     static Map<String, String> getPeriodRefreshPartition(
701:             String scheduleTime,
702:             IntervalFreshness freshness,
703:             ObjectIdentifier materializedTableIdentifier,
704:             Map<String, String> materializedTableOptions,
705:             ZoneId localZoneId) {
706:         if (scheduleTime == null) {
707:             throw new ValidationException(
708:                     String.format(
709:                             "The scheduler time must not be null during the periodic refresh of the materialized table %s.",
710:                             materializedTableIdentifier));
711:         }
712: 
713:         Set<String> partitionFields =
714:                 materializedTableOptions.keySet().stream()
715:                         .filter(k -> k.startsWith(PARTITION_FIELDS))
716:                         .collect(Collectors.toSet());
717:         Map<String, String> refreshPartitions = new HashMap<>();
718:         for (String partKey : partitionFields) {
719:             String partField =
720:                     partKey.substring(
721:                             PARTITION_FIELDS.length() + 1,
722:                             partKey.length() - (DATE_FORMATTER.length() + 1));
723:             String partFieldFormatter = materializedTableOptions.get(partKey);
724: 
725:             String partFiledValue =
726:                     formatTimestampStringWithOffset(
727:                             scheduleTime,
728:                             SCHEDULE_TIME_DATE_FORMATTER_DEFAULT,
729:                             partFieldFormatter,
730:                             TimeZone.getTimeZone(localZoneId),
731:                             -convertFreshnessToDuration(freshness).toMillis());
732:             if (partFiledValue == null) {
733:                 throw new SqlExecutionException(
734:                         String.format(
735:                                 "Failed to parse a valid partition value for the field '%s' in materialized table %s using the scheduler time '%s' based on the date format '%s'.",
736:                                 partField,
737:                                 materializedTableIdentifier.asSerializableString(),
738:                                 scheduleTime,
739:                                 SCHEDULE_TIME_DATE_FORMATTER_DEFAULT));
740:             }
741:             refreshPartitions.put(partField, partFiledValue);
742:         }
743: 
744:         return refreshPartitions;
745:     }
