747:     private void validatePartitionSpec(
748:             Map<String, String> partitionSpec, ResolvedCatalogMaterializedTable table) {
749:         ResolvedSchema schema = table.getResolvedSchema();
750:         Set<String> allPartitionKeys = new HashSet<>(table.getPartitionKeys());
751: 
752:         Set<String> unknownPartitionKeys = new HashSet<>();
753:         Set<String> nonStringPartitionKeys = new HashSet<>();
754: 
755:         for (String partitionKey : partitionSpec.keySet()) {
756:             if (!schema.getColumn(partitionKey).isPresent()) {
757:                 unknownPartitionKeys.add(partitionKey);
758:                 continue;
759:             }
760: 
761:             if (!schema.getColumn(partitionKey)
762:                     .get()
763:                     .getDataType()
764:                     .getLogicalType()
765:                     .getTypeRoot()
766:                     .getFamilies()
767:                     .contains(LogicalTypeFamily.CHARACTER_STRING)) {
768:                 nonStringPartitionKeys.add(partitionKey);
769:             }
770:         }
771: 
772:         if (!unknownPartitionKeys.isEmpty()) {
773:             throw new ValidationException(
774:                     String.format(
775:                             "The partition spec contains unknown partition keys:\n\n%s\n\nAll known partition keys are:\n\n%s",
776:                             String.join("\n", unknownPartitionKeys),
777:                             String.join("\n", allPartitionKeys)));
778:         }
779: 
780:         if (!nonStringPartitionKeys.isEmpty()) {
781:             throw new ValidationException(
782:                     String.format(
783:                             "Currently, refreshing materialized table only supports referring to char, varchar and string type"
784:                                     + " partition keys. All specified partition keys in partition specs with unsupported types are:\n\n%s",
785:                             String.join("\n", nonStringPartitionKeys)));
786:         }
787:     }
