789:     @VisibleForTesting
790:     protected static String getRefreshStatement(
791:             ObjectIdentifier tableIdentifier,
792:             String definitionQuery,
793:             Map<String, String> partitionSpec,
794:             Map<String, String> dynamicOptions) {
795:         String tableIdentifierWithDynamicOptions =
796:                 generateTableWithDynamicOptions(tableIdentifier, dynamicOptions);
797:         StringBuilder insertStatement =
798:                 new StringBuilder(
799:                         String.format(
800:                                 "INSERT OVERWRITE %s\n  SELECT * FROM (%s)",
801:                                 tableIdentifierWithDynamicOptions, definitionQuery));
802:         if (!partitionSpec.isEmpty()) {
803:             insertStatement.append("\n  WHERE ");
804:             insertStatement.append(
805:                     partitionSpec.entrySet().stream()
806:                             .map(
807:                                     entry ->
