817:     private ResultFetcher callAlterMaterializedTableAsQueryOperation(
818:             OperationExecutor operationExecutor,
819:             OperationHandle handle,
820:             AlterMaterializedTableAsQueryOperation op) {
821:         ObjectIdentifier tableIdentifier = op.getTableIdentifier();
822:         CatalogMaterializedTable oldMaterializedTable =
823:                 getCatalogMaterializedTable(operationExecutor, tableIdentifier);
824: 
825:         if (CatalogMaterializedTable.RefreshMode.FULL == oldMaterializedTable.getRefreshMode()) {
826:             // directly apply the alter operation
827:             AlterMaterializedTableChangeOperation alterMaterializedTableChangeOperation =
828:                     new AlterMaterializedTableChangeOperation(
829:                             tableIdentifier, op.getTableChanges(), op.getNewMaterializedTable());
830:             return operationExecutor.callExecutableOperation(
831:                     handle, alterMaterializedTableChangeOperation);
832:         }
833: 
834:         if (CatalogMaterializedTable.RefreshStatus.ACTIVATED
835:                 == oldMaterializedTable.getRefreshStatus()) {
836:             // 1. suspend the materialized table
837:             CatalogMaterializedTable suspendMaterializedTable =
838:                     suspendContinuousRefreshJob(
839:                             operationExecutor, handle, tableIdentifier, oldMaterializedTable);
840: 
841:             // 2. alter materialized table schema & query definition
842:             CatalogMaterializedTable updatedMaterializedTable =
843:                     op.getNewMaterializedTable()
844:                             .copy(
845:                                     suspendMaterializedTable.getRefreshStatus(),
846:                                     suspendMaterializedTable
847:                                             .getRefreshHandlerDescription()
848:                                             .orElse(null),
849:                                     suspendMaterializedTable.getSerializedRefreshHandler());
850:             AlterMaterializedTableChangeOperation alterMaterializedTableChangeOperation =
851:                     new AlterMaterializedTableChangeOperation(
852:                             tableIdentifier, op.getTableChanges(), updatedMaterializedTable);
853:             operationExecutor.callExecutableOperation(
854:                     handle, alterMaterializedTableChangeOperation);
855: 
856:             // 3. resume the materialized table
857:             try {
858:                 executeContinuousRefreshJob(
859:                         operationExecutor,
860:                         handle,
861:                         updatedMaterializedTable,
862:                         tableIdentifier,
863:                         Collections.emptyMap(),
864:                         Optional.empty());
865:             } catch (Exception e) {
866:                 // Roll back the changes to the materialized table and restore the continuous
867:                 // refresh job
868:                 LOG.warn(
869:                         "Failed to start the continuous refresh job for materialized table {} using new query {}, rollback to origin query {}.",
870:                         tableIdentifier,
871:                         op.getNewMaterializedTable().getDefinitionQuery(),
872:                         suspendMaterializedTable.getDefinitionQuery(),
873:                         e);
874: 
875:                 AlterMaterializedTableChangeOperation rollbackChangeOperation =
876:                         generateRollbackAlterMaterializedTableOperation(
877:                                 suspendMaterializedTable, alterMaterializedTableChangeOperation);
878:                 operationExecutor.callExecutableOperation(handle, rollbackChangeOperation);
879: 
880:                 ContinuousRefreshHandler continuousRefreshHandler =
881:                         deserializeContinuousHandler(
882:                                 suspendMaterializedTable.getSerializedRefreshHandler());
883:                 executeContinuousRefreshJob(
884:                         operationExecutor,
885:                         handle,
886:                         suspendMaterializedTable,
887:                         tableIdentifier,
888:                         Collections.emptyMap(),
889:                         continuousRefreshHandler.getRestorePath());
890: 
891:                 throw new SqlExecutionException(
892:                         String.format(
893:                                 "Failed to start the continuous refresh job using new query %s when altering materialized table %s select query.",
894:                                 op.getNewMaterializedTable().getDefinitionQuery(), tableIdentifier),
895:                         e);
896:             }
897:         } else if (CatalogMaterializedTable.RefreshStatus.SUSPENDED
898:                 == oldMaterializedTable.getRefreshStatus()) {
899:             // alter schema & definition query & refresh handler (reset savepoint path of refresh
900:             // handler)
901:             List<MaterializedTableChange> tableChanges = new ArrayList<>(op.getTableChanges());
902:             TableChange.ModifyRefreshHandler modifyRefreshHandler =
903:                     generateResetSavepointTableChange(
904:                             oldMaterializedTable.getSerializedRefreshHandler());
905:             tableChanges.add(modifyRefreshHandler);
906: 
907:             CatalogMaterializedTable updatedMaterializedTable =
908:                     op.getNewMaterializedTable()
909:                             .copy(
910:                                     oldMaterializedTable.getRefreshStatus(),
911:                                     modifyRefreshHandler.getRefreshHandlerDesc(),
912:                                     modifyRefreshHandler.getRefreshHandlerBytes());
913:             AlterMaterializedTableChangeOperation alterMaterializedTableChangeOperation =
914:                     new AlterMaterializedTableChangeOperation(
915:                             tableIdentifier, tableChanges, updatedMaterializedTable);
916: 
917:             operationExecutor.callExecutableOperation(
918:                     handle, alterMaterializedTableChangeOperation);
919:         } else {
920:             throw new SqlExecutionException(
921:                     String.format(
922:                             "Materialized table %s is being initialized and does not support alter operation.",
923:                             tableIdentifier));
924:         }
925: 
926:         return ResultFetcher.fromTableResult(handle, TABLE_RESULT_OK, false);
927:     }
