929:     private AlterMaterializedTableChangeOperation generateRollbackAlterMaterializedTableOperation(
930:             CatalogMaterializedTable oldMaterializedTable,
931:             AlterMaterializedTableChangeOperation op) {
932:         List<MaterializedTableChange> tableChanges = op.getTableChanges();
933:         List<MaterializedTableChange> rollbackChanges = new ArrayList<>();
934: 
935:         for (TableChange tableChange : tableChanges) {
936:             if (tableChange instanceof TableChange.AddColumn) {
937:                 TableChange.AddColumn addColumn = (TableChange.AddColumn) tableChange;
938:                 rollbackChanges.add(TableChange.dropColumn(addColumn.getColumn().getName()));
939:             } else if (tableChange instanceof TableChange.ModifyRefreshHandler) {
940:                 rollbackChanges.add(
941:                         TableChange.modifyRefreshHandler(
942:                                 oldMaterializedTable.getRefreshHandlerDescription().orElse(null),
943:                                 oldMaterializedTable.getSerializedRefreshHandler()));
944:             } else if (tableChange instanceof TableChange.ModifyDefinitionQuery) {
945:                 rollbackChanges.add(
946:                         TableChange.modifyDefinitionQuery(
947:                                 oldMaterializedTable.getDefinitionQuery()));
948:             } else {
949:                 throw new ValidationException(
950:                         String.format(
951:                                 "Failed to generate rollback changes for materialized table '%s'. "
952:                                         + "Unsupported table change detected: %s. ",
953:                                 op.getTableIdentifier(), tableChange));
954:             }
955:         }
956: 
957:         return new AlterMaterializedTableChangeOperation(
958:                 op.getTableIdentifier(), rollbackChanges, oldMaterializedTable);
959:     }
