976:     private ResultFetcher callDropMaterializedTableOperation(
977:             OperationExecutor operationExecutor,
978:             OperationHandle handle,
979:             DropMaterializedTableOperation dropMaterializedTableOperation) {
980:         ObjectIdentifier tableIdentifier = dropMaterializedTableOperation.getTableIdentifier();
981:         boolean tableExists = operationExecutor.tableExists(tableIdentifier);
982:         if (!tableExists) {
983:             if (dropMaterializedTableOperation.isIfExists()) {
984:                 LOG.info(
985:                         "Materialized table {} does not exists, skip the drop operation.",
986:                         tableIdentifier);
987:                 return ResultFetcher.fromTableResult(handle, TABLE_RESULT_OK, false);
988:             } else {
989:                 throw new ValidationException(
990:                         String.format(
991:                                 "Materialized table with identifier %s does not exist.",
992:                                 tableIdentifier));
993:             }
994:         }
995: 
996:         CatalogMaterializedTable materializedTable =
997:                 getCatalogMaterializedTable(operationExecutor, tableIdentifier);
998:         CatalogMaterializedTable.RefreshMode refreshMode = materializedTable.getRefreshMode();
999:         CatalogMaterializedTable.RefreshStatus refreshStatus = materializedTable.getRefreshStatus();
1000:         if (CatalogMaterializedTable.RefreshStatus.ACTIVATED == refreshStatus
1001:                 || CatalogMaterializedTable.RefreshStatus.SUSPENDED == refreshStatus) {
1002:             if (CatalogMaterializedTable.RefreshMode.FULL == refreshMode) {
1003:                 deleteRefreshWorkflow(tableIdentifier, materializedTable);
1004:             } else if (CatalogMaterializedTable.RefreshMode.CONTINUOUS == refreshMode
1005:                     && CatalogMaterializedTable.RefreshStatus.ACTIVATED == refreshStatus) {
1006:                 cancelContinuousRefreshJob(
1007:                         operationExecutor, handle, tableIdentifier, materializedTable);
1008:             }
1009:         } else if (CatalogMaterializedTable.RefreshStatus.INITIALIZING
1010:                 == materializedTable.getRefreshStatus()) {
1011:             throw new ValidationException(
1012:                     String.format(
1013:                             "Current refresh status of materialized table %s is initializing, skip the drop operation.",
1014:                             tableIdentifier.asSerializableString()));
1015:         }
1016: 
1017:         operationExecutor.callExecutableOperation(handle, dropMaterializedTableOperation);
1018: 
1019:         return ResultFetcher.fromTableResult(handle, TABLE_RESULT_OK, false);
1020:     }
