1022:     private void cancelContinuousRefreshJob(
1023:             OperationExecutor operationExecutor,
1024:             OperationHandle handle,
1025:             ObjectIdentifier tableIdentifier,
1026:             CatalogMaterializedTable materializedTable) {
1027:         ContinuousRefreshHandler refreshHandler =
1028:                 deserializeContinuousHandler(materializedTable.getSerializedRefreshHandler());
1029:         // get job running status
1030:         JobStatus jobStatus = getJobStatus(operationExecutor, handle, refreshHandler);
1031:         if (!jobStatus.isTerminalState()) {
1032:             try {
1033:                 cancelJob(operationExecutor, handle, refreshHandler);
1034:             } catch (Exception e) {
1035:                 jobStatus = getJobStatus(operationExecutor, handle, refreshHandler);
1036:                 if (!jobStatus.isTerminalState()) {
1037:                     throw new SqlExecutionException(
1038:                             String.format(
1039:                                     "Failed to drop the materialized table %s because the continuous refresh job %s could not be canceled."
1040:                                             + " The current status of the continuous refresh job is %s.",
1041:                                     tableIdentifier, refreshHandler.getJobId(), jobStatus),
1042:                             e);
1043:                 } else {
1044:                     LOG.warn(
1045:                             "An exception occurred while canceling the continuous refresh job {} for materialized table {},"
1046:                                     + " but since the job is in a terminal state, skip the cancel operation.",
1047:                             refreshHandler.getJobId(),
1048:                             tableIdentifier);
1049:                 }
1050:             }
1051:         } else {
1052:             LOG.info(
1053:                     "No need to cancel the continuous refresh job {} for materialized table {} as it is not currently running.",
1054:                     refreshHandler.getJobId(),
1055:                     tableIdentifier);
1056:         }
1057:     }
