1083:     /**
1084:      * Retrieves the session configuration for initializing the periodic refresh job. The function
1085:      * filters out default context configurations and removes unnecessary configurations such as
1086:      * resources download directory and workflow scheduler related configurations.
1087:      *
1088:      * @param operationExecutor The OperationExecutor instance used to access the session context.
1089:      * @return A Map containing the session configurations for initializing session for executing
1090:      *     the periodic refresh job.
1091:      */
1092:     private Map<String, String> getSessionInitializationConf(OperationExecutor operationExecutor) {
1093:         Map<String, String> sessionConf =
1094:                 operationExecutor.getSessionContext().getSessionConf().toMap();
1095: 
1096:         // we only keep the session conf that is not in the default context or the conf value is
1097:         // different from the default context.
1098:         Map<String, String> defaultContextConf =
1099:                 operationExecutor.getSessionContext().getDefaultContext().getFlinkConfig().toMap();
1100:         sessionConf
1101:                 .entrySet()
1102:                 .removeIf(
1103:                         entry -> {
1104:                             String key = entry.getKey();
1105:                             String value = entry.getValue();
1106:                             return defaultContextConf.containsKey(key)
1107:                                     && defaultContextConf.get(key).equals(value);
1108:                         });
1109: 
1110:         // remove useless conf
1111:         sessionConf.remove(TableConfigOptions.RESOURCES_DOWNLOAD_DIR.key());
1112:         sessionConf.keySet().removeIf(key -> key.startsWith(WORKFLOW_SCHEDULER_PREFIX));
1113: 
1114:         return sessionConf;
1115:     }
