1212:             OperationHandle operationHandle,
1213:             ObjectIdentifier materializedTableIdentifier,
1214:             CatalogMaterializedTable catalogMaterializedTable,
1215:             CatalogMaterializedTable.RefreshStatus refreshStatus,
