1275:             String script,
1276:             Configuration executionConfig,
1277:             OperationExecutor operationExecutor,
1278:             OperationHandle operationHandle) {
1279:         String executeTarget = operationExecutor.getSessionContext().getSessionConf().get(TARGET);
1280:         if (executeTarget == null || executeTarget.isEmpty() || "local".equals(executeTarget)) {
1281:             String errorMessage =
1282:                     String.format(
1283:                             "Unsupported execution target detected: %s."
1284:                                     + "Currently, only the following execution targets are supported: "
1285:                                     + "'remote', 'yarn-session', 'yarn-application', 'kubernetes-session', 'kubernetes-application'. ",
1286:                             executeTarget);
1287:             LOG.error(errorMessage);
1288:             throw new ValidationException(errorMessage);
1289:         }
1290: 
1291:         if (executeTarget.endsWith("application")) {
1292:             return executeApplicationJob(script, executionConfig, operationExecutor);
1293:         } else {
1294:             return executeNonApplicationJob(
1295:                     script, executionConfig, operationExecutor, operationHandle);
