1326:     private static JobExecutionResult executeApplicationJob(
1327:             String script, Configuration executionConfig, OperationExecutor operationExecutor) {
1328:         List<String> arguments = new ArrayList<>();
1329:         arguments.add("--" + SqlDriver.OPTION_SQL_SCRIPT.getLongOpt());
1330:         arguments.add(script);
1331: 
1332:         Configuration mergedConfig =
1333:                 new Configuration(operationExecutor.getSessionContext().getSessionConf());
1334:         mergedConfig.addAll(executionConfig);
1335:         JobID jobId = new JobID();
1336:         mergedConfig.set(PIPELINE_FIXED_JOB_ID, jobId.toString());
1337: 
1338:         ApplicationConfiguration applicationConfiguration =
1339:                 new ApplicationConfiguration(
1340:                         arguments.toArray(new String[0]), SqlDriver.class.getName());
1341:         try {
1342:             String clusterId =
1343:                     new ApplicationClusterDeployer(new DefaultClusterClientServiceLoader())
1344:                             .run(mergedConfig, applicationConfiguration)
1345:                             .toString();
1346: 
1347:             return new JobExecutionResult(mergedConfig.get(TARGET), clusterId, jobId.toString());
1348:         } catch (Throwable t) {
1349:             LOG.error("Failed to deploy script {} to application cluster.", script, t);
1350:             throw new SqlGatewayException("Failed to deploy script to cluster.", t);
1351:         }
1352:     }
