288:     @Test
289:     void testMetrics() throws Exception {
290:         ValidatingCheckpointHandler handler = new ValidatingCheckpointHandler(1);
291:         inputGate = createInputGate(3, handler);
292:         int bufferSize = 100;
293:         long checkpointId = 1;
294:         long sleepTime = 10;
295: 
296:         long checkpointBarrierCreation = System.currentTimeMillis();
297: 
298:         Thread.sleep(sleepTime);
299: 
300:         long alignmentStartNanos = System.nanoTime();
301: 
302:         addSequence(
303:                 inputGate,
304:                 createBuffer(0, bufferSize),
305:                 createBuffer(1, bufferSize),
306:                 createBuffer(2, bufferSize),
307:                 createBarrier(checkpointId, 1, checkpointBarrierCreation),
308:                 createBuffer(0, bufferSize),
309:                 createBuffer(1, bufferSize),
310:                 createBuffer(2, bufferSize),
311:                 createBarrier(checkpointId, 0),
312:                 createBuffer(0, bufferSize),
313:                 createBuffer(1, bufferSize),
314:                 createBuffer(2, bufferSize));
315: 
316:         long startDelay = System.currentTimeMillis() - checkpointBarrierCreation;
317:         Thread.sleep(sleepTime);
318: 
319:         addSequence(
320:                 inputGate,
321:                 createBarrier(checkpointId, 2),
322:                 createBuffer(0, bufferSize),
323:                 createBuffer(1, bufferSize),
324:                 createBuffer(2, bufferSize),
325:                 createEndOfPartition(0),
326:                 createEndOfPartition(1),
327:                 createEndOfPartition(2));
328: 
329:         long alignmentDuration = System.nanoTime() - alignmentStartNanos;
330: 
331:         assertThat(inputGate.getCheckpointBarrierHandler().getLatestCheckpointId())
332:                 .isEqualTo(checkpointId);
333:         assertThat(inputGate.getCheckpointStartDelayNanos() / 1_000_000)
334:                 .isBetween(sleepTime, startDelay);
335: 
336:         assertThat(handler.getLastAlignmentDurationNanos()).isDone();
337:         assertThat(handler.getLastAlignmentDurationNanos().get() / 1_000_000)
338:                 .isBetween(sleepTime, alignmentDuration);
339: 
340:         assertThat(handler.getLastBytesProcessedDuringAlignment())
341:                 .isCompletedWithValue(6L * bufferSize);
342:     }
