960:     static BufferOrEvent[] addSequence(
961:             CheckpointedInputGate inputGate,
962:             List<BufferOrEvent> output,
963:             int[] sequenceNumbers,
964:             BufferOrEvent... sequence)
965:             throws Exception {
966:         for (BufferOrEvent bufferOrEvent : sequence) {
967:             if (bufferOrEvent.isEvent()) {
968:                 bufferOrEvent =
969:                         new BufferOrEvent(
970:                                 EventSerializer.toBuffer(
971:                                         bufferOrEvent.getEvent(),
972:                                         bufferOrEvent.getEvent() instanceof CheckpointBarrier),
973:                                 bufferOrEvent.getChannelInfo(),
974:                                 bufferOrEvent.moreAvailable(),
975:                                 bufferOrEvent.morePriorityEvents());
976:             }
977:             ((RemoteInputChannel)
978:                             inputGate.getChannel(
979:                                     bufferOrEvent.getChannelInfo().getInputChannelIdx()))
980:                     .onBuffer(
981:                             bufferOrEvent.getBuffer(),
982:                             sequenceNumbers[bufferOrEvent.getChannelInfo().getInputChannelIdx()]++,
983:                             0,
984:                             0);
985: 
986:             while (inputGate.pollNext().map(output::add).isPresent()) {}
987:         }
988:         return sequence;
989:     }
