961:     static BufferOrEvent[] addSequence(
962:             CheckpointedInputGate inputGate,
963:             List<BufferOrEvent> output,
964:             int[] sequenceNumbers,
965:             BufferOrEvent... sequence)
966:             throws Exception {
967:         for (BufferOrEvent bufferOrEvent : sequence) {
968:             if (bufferOrEvent.isEvent()) {
969:                 bufferOrEvent =
970:                         new BufferOrEvent(
971:                                 EventSerializer.toBuffer(
972:                                         bufferOrEvent.getEvent(),
973:                                         bufferOrEvent.getEvent() instanceof CheckpointBarrier),
974:                                 bufferOrEvent.getChannelInfo(),
975:                                 bufferOrEvent.moreAvailable(),
976:                                 bufferOrEvent.morePriorityEvents());
977:             }
978:             ((RemoteInputChannel)
979:                             inputGate.getChannel(
980:                                     bufferOrEvent.getChannelInfo().getInputChannelIdx()))
981:                     .onBuffer(
982:                             bufferOrEvent.getBuffer(),
983:                             sequenceNumbers[bufferOrEvent.getChannelInfo().getInputChannelIdx()]++,
984:                             0,
985:                             0);
986: 
987:             while (inputGate.pollNext().map(output::add).isPresent()) {}
988:         }
989:         return sequence;
990:     }
