314:     // ------------------------------------------------------------------------
315:     //  Encoding / Decoding of References
316:     // ------------------------------------------------------------------------
317: 
318:     /**
319:      * Encodes the given path as a reference in bytes. The path is encoded as a UTF-8 string and
320:      * prepended as a magic number.
321:      *
322:      * @param path The path to encode.
323:      * @return The location reference.
324:      */
325:     public static CheckpointStorageLocationReference encodePathAsReference(Path path) {
326:         byte[] refBytes = path.toString().getBytes(StandardCharsets.UTF_8);
327:         byte[] bytes = new byte[REFERENCE_MAGIC_NUMBER.length + refBytes.length];
328: 
329:         System.arraycopy(REFERENCE_MAGIC_NUMBER, 0, bytes, 0, REFERENCE_MAGIC_NUMBER.length);
330:         System.arraycopy(refBytes, 0, bytes, REFERENCE_MAGIC_NUMBER.length, refBytes.length);
331: 
332:         return new CheckpointStorageLocationReference(bytes);
333:     }
334: 
335:     /**
336:      * Decodes the given reference into a path. This method validates that the reference bytes start
337:      * with the correct magic number (as written by {@link #encodePathAsReference(Path)}) and
338:      * converts the remaining bytes back to a proper path.
339:      *
340:      * @param reference The bytes representing the reference.
341:      * @return The path decoded from the reference.
342:      * @throws IllegalArgumentException Thrown, if the bytes do not represent a proper reference.
343:      */
344:     public static Path decodePathFromReference(CheckpointStorageLocationReference reference) {
345:         if (reference.isDefaultReference()) {
346:             throw new IllegalArgumentException("Cannot decode default reference");
347:         }
348: 
349:         final byte[] bytes = reference.getReferenceBytes();
350:         final int headerLen = REFERENCE_MAGIC_NUMBER.length;
351: 
352:         if (bytes.length > headerLen) {
353:             // compare magic number
354:             for (int i = 0; i < headerLen; i++) {
355:                 if (bytes[i] != REFERENCE_MAGIC_NUMBER[i]) {
356:                     throw new IllegalArgumentException(
357:                             "Reference starts with the wrong magic number");
358:                 }
359:             }
360: 
361:             // covert to string and path
362:             try {
363:                 return new Path(
364:                         new String(
365:                                 bytes,
366:                                 headerLen,
367:                                 bytes.length - headerLen,
368:                                 StandardCharsets.UTF_8));
369:             } catch (Exception e) {
370:                 throw new IllegalArgumentException("Reference cannot be decoded to a path", e);
371:             }
372:         } else {
373:             throw new IllegalArgumentException("Reference too short.");
374:         }
375:     }
376: }
