245: 
246:         public FsCheckpointStateOutputStream(
247:                 Path basePath,
248:                 FileSystem fs,
249:                 int bufferSize,
250:                 int localStateThreshold,
251:                 boolean allowRelativePaths) {
252: 
253:             if (bufferSize < localStateThreshold) {
254:                 throw new IllegalArgumentException();
255:             }
256: 
257:             this.basePath = basePath;
258:             this.fs = fs;
