263: 
264:         @Override
265:         public void write(int b) throws IOException {
266:             if (pos >= writeBuffer.length) {
267:                 flushToFile();
268:             }
269:             writeBuffer[pos++] = (byte) b;
270:         }
271: 
272:         @Override
273:         public void write(byte[] b, int off, int len) throws IOException {
274:             if (len < writeBuffer.length) {
275:                 // copy it into our write buffer first
276:                 final int remaining = writeBuffer.length - pos;
277:                 if (len > remaining) {
278:                     // copy as much as fits
279:                     System.arraycopy(b, off, writeBuffer, pos, remaining);
280:                     off += remaining;
281:                     len -= remaining;
282:                     pos += remaining;
283: 
284:                     // flushToFile the write buffer to make it clear again
285:                     flushToFile();
286:                 }
287: 
288:                 // copy what is in the buffer
289:                 System.arraycopy(b, off, writeBuffer, pos, len);
290:                 pos += len;
291:             } else {
292:                 // acquire lock only when we manipulate outStream to avoid the
293:                 // additional overhead for the hot path write method
294:                 synchronized (this) {
295:                     // flushToFile the current buffer
296:                     flushToFile();
