357:                 // make sure write requests need to go to 'flushToFile()' where they recognized
358:                 // that the stream is closed
359:                 pos = writeBuffer.length;
360: 
361:                 if (outStream != null) {
362:                     try {
363:                         outStream.close();
364:                     } catch (Throwable throwable) {
365:                         LOG.warn("Could not close the state stream for {}.", statePath, throwable);
366:                     } finally {
367:                         try {
368:                             fs.delete(statePath, false);
369:                         } catch (Exception e) {
