380:         @Nullable
381:         @Override
382:         public synchronized StreamStateHandle closeAndGetHandle() throws IOException {
383:             // check if there was nothing ever written
384:             if (outStream == null && pos == 0) {
385:                 return null;
386:             }
387: 
388:             if (!closed) {
389:                 if (outStream == null && pos <= localStateThreshold) {
390:                     closed = true;
391:                     byte[] bytes = Arrays.copyOf(writeBuffer, pos);
392:                     pos = writeBuffer.length;
393:                     return new ByteStreamStateHandle(createStatePath().toString(), bytes);
394:                 } else {
395:                     try {
396:                         flushToFile();
397: 
398:                         pos = writeBuffer.length;
399: 
400:                         long size = -1L;
401: 
402:                         // make a best effort attempt to figure out the size
403:                         try {
404:                             size = outStream.getPos();
405:                         } catch (Exception ignored) {
406:                         }
407: 
408:                         sync();
409:                         outStream.close();
410: 
411:                         return allowRelativePaths
412:                                 ? new RelativeFileStateHandle(statePath, relativeStatePath, size)
413:                                 : new FileStateHandle(statePath, size);
414:                     } catch (Exception exception) {
415:                         try {
416:                             if (statePath != null) {
417:                                 fs.delete(statePath, false);
418:                             }
419: 
420:                         } catch (Exception deleteException) {
