427:                         throw new IOException(
428:                                 "Could not flush to file and close the file system "
429:                                         + "output stream to "
430:                                         + statePath
431:                                         + " in order to obtain the "
432:                                         + "stream state handle",
433:                                 exception);
434:                     } finally {
435:                         closed = true;
436:                     }
437:                 }
438:             } else {
439:                 throw new IOException("Stream has already been closed and discarded.");
440:             }
441:         }
442: 
443:         private Path createStatePath() {
444:             final String fileName = UUID.randomUUID().toString();
445:             relativeStatePath = fileName;
446:             return new Path(basePath, fileName);
447:         }
448: 
449:         private void createStream() throws IOException {
450:             Exception latestException = null;
451:             for (int attempt = 0; attempt < 10; attempt++) {
452:                 try {
453:                     OutputStreamAndPath streamAndPath =
454:                             EntropyInjector.createEntropyAware(
