447:     static SupplierWithException<BufferPool, IOException> createBufferPoolFactory(
448:             BufferPoolFactory bufferPoolFactory,
449:             int expectedBuffersPerGate,
450:             int minBuffersPerGate,
451:             int maxBuffersPerGate) {
452:         return () ->
453:                 bufferPoolFactory.createBufferPool(
454:                         expectedBuffersPerGate, minBuffersPerGate, maxBuffersPerGate);
455:     }
