168:         }
169:         final Transformation<RowData> inputTransform = inputTransforms.get(0);
170: 
171:         final List<Ord<StaticArgument>> providedInputArgs =
172:                 StreamPhysicalProcessTableFunction.getProvidedInputArgs(invocation);
173:         final List<RexNode> operands = invocation.getOperands();
174:         final Set<String> onTimeFields = deriveOnTimeFields(operands);
175:         final List<RuntimeTableSemantics> runtimeTableSemantics =
176:                 providedInputArgs.stream()
177:                         .map(
178:                                 providedInputArg -> {
179:                                     final RexTableArgCall tableArgCall =
180:                                             (RexTableArgCall) operands.get(providedInputArg.i);
181:                                     final StaticArgument tabledArg = providedInputArg.e;
182:                                     return createRuntimeTableSemantics(
183:                                             tabledArg, tableArgCall, onTimeFields);
184:                                 })
185:                         .collect(Collectors.toList());
186:         final List<Integer> timeColumns =
187:                 runtimeTableSemantics.stream()
188:                         .map(RuntimeTableSemantics::timeColumn)
189:                         .collect(Collectors.toList());
190: 
191:         final CodeGeneratorContext ctx =
192:                 new CodeGeneratorContext(config, planner.getFlinkContext().getClassLoader());
193: 
194:         final GeneratedRunnerResult generated =
195:                 ProcessTableRunnerGenerator.generate(
196:                         ctx, invocation, timeColumns, inputChangelogModes);
197:         final GeneratedProcessTableRunner generatedRunner = generated.runner();
198:         final LinkedHashMap<String, StateInfo> stateInfos = generated.stateInfos();
199: 
200:         final List<RuntimeStateInfo> runtimeStateInfos =
201:                 stateInfos.entrySet().stream()
202:                         .map(
203:                                 stateInfo ->
204:                                         createRuntimeStateInfo(
205:                                                 stateInfo.getKey(), stateInfo.getValue(), config))
206:                         .collect(Collectors.toList());
207:         final GeneratedHashFunction[] stateHashCode =
208:                 runtimeStateInfos.stream()
209:                         .map(RuntimeStateInfo::getDataType)
210:                         .map(DataType::getLogicalType)
211:                         .map(
212:                                 t ->
213:                                         HashCodeGenerator.generateRowHash(
214:                                                 ctx,
215:                                                 t,
216:                                                 "StateHashCode",
217:                                                 IntStream.range(0, getFieldCount(t)).toArray()))
218:                         .toArray(GeneratedHashFunction[]::new);
219:         final GeneratedRecordEqualiser[] stateEquals =
220:                 runtimeStateInfos.stream()
221:                         .map(RuntimeStateInfo::getDataType)
222:                         .map(DataType::getLogicalType)
223:                         .map(t -> EqualiserCodeGenerator.generateRowEquals(ctx, t, "StateEquals"))
224:                         .toArray(GeneratedRecordEqualiser[]::new);
225: 
226:         final RuntimeTableSemantics singleTableSemantics;
227:         if (runtimeTableSemantics.isEmpty()) {
228:             // For constant function calls
229:             singleTableSemantics = null;
230:         } else {
231:             singleTableSemantics = runtimeTableSemantics.get(0);
232:         }
233: 
234:         final ProcessTableOperatorFactory operatorFactory =
235:                 new ProcessTableOperatorFactory(
236:                         singleTableSemantics,
237:                         runtimeStateInfos,
238:                         generatedRunner,
239:                         stateHashCode,
240:                         stateEquals);
241: 
242:         final String effectiveUid =
243:                 uid != null ? uid : createTransformationUid(PROCESS_TRANSFORMATION, config);
244: 
245:         final TransformationMetadata metadata =
246:                 new TransformationMetadata(
247:                         effectiveUid,
248:                         createTransformationName(config),
249:                         createTransformationDescription(config));
250: 
251:         final OneInputTransformation<RowData, RowData> transform =
252:                 ExecNodeUtil.createOneInputTransformation(
253:                         inputTransform,
254:                         metadata,
255:                         operatorFactory,
256:                         InternalTypeInfo.of(getOutputType()),
257:                         inputTransform.getParallelism(),
258:                         false);
259: 
260:         // For one input (but non-constant) functions with set semantics
261:         if (singleTableSemantics != null && singleTableSemantics.hasSetSemantics()) {
262:             final RowDataKeySelector selector =
263:                     KeySelectorUtil.getRowDataSelector(
264:                             planner.getFlinkContext().getClassLoader(),
265:                             singleTableSemantics.partitionByColumns(),
266:                             (InternalTypeInfo<RowData>) inputTransform.getOutputType());
267:             transform.setStateKeySelector(selector);
268:             transform.setStateKeyType(selector.getProducedType());
269:         }
270: 
271:         if (inputsContainSingleton()) {
272:             transform.setParallelism(1);
273:             transform.setMaxParallelism(1);
274:         }
275: 
276:         return transform;
277:     }
