279:     private RuntimeTableSemantics createRuntimeTableSemantics(
280:             StaticArgument tableArg, RexTableArgCall tableArgCall, Set<String> onTimeFields) {
281:         final RowKind[] kinds =
282:                 inputChangelogModes
283:                         .get(tableArgCall.getInputIndex())
284:                         .getContainedKinds()
285:                         .toArray(RowKind[]::new);
286:         final byte[] expectedChanges = new byte[kinds.length];
287:         IntStream.range(0, kinds.length).forEach(i -> expectedChanges[i] = kinds[i].toByteValue());
288:         final DataType dataType;
289:         if (tableArg.getDataType().isPresent()) {
290:             dataType = tableArg.getDataType().get();
291:         } else {
292:             dataType = DataTypes.of(FlinkTypeFactory.toLogicalRowType(tableArgCall.type));
293:         }
294: 
295:         final int timeColumn =
296:                 onTimeFields.stream()
297:                         .map(
298:                                 onTimeField ->
299:                                         tableArgCall.getType().getField(onTimeField, true, false))
300:                         .filter(Objects::nonNull)
301:                         .map(RelDataTypeField::getIndex)
302:                         .findFirst()
303:                         .orElse(-1);
304: 
305:         return new RuntimeTableSemantics(
306:                 tableArg.getName(),
307:                 tableArgCall.getInputIndex(),
308:                 dataType,
309:                 tableArgCall.getPartitionKeys(),
310:                 expectedChanges,
311:                 tableArg.is(StaticArgumentTrait.PASS_COLUMNS_THROUGH),
312:                 tableArg.is(StaticArgumentTrait.TABLE_AS_SET),
313:                 timeColumn);
314:     }
315: 
316:     private static RuntimeStateInfo createRuntimeStateInfo(
317:             String name, StateInfo stateInfo, ExecNodeConfig config) {
318:         return new RuntimeStateInfo(
319:                 name,
320:                 stateInfo.getDataType(),
321:                 deriveStateTimeToLive(
322:                         stateInfo.getTimeToLive().orElse(null), config.getStateRetentionTime()));
323:     }
324: 
325:     private static long deriveStateTimeToLive(
326:             @Nullable Duration declaration, long globalRetentionTime) {
327:         // User declaration take precedence. Including a potential 0.
328:         if (declaration != null) {
329:             return declaration.toMillis();
330:         }
331:         // This prepares the state layout of every PTF. It makes enabling state TTL at a later
332:         // point in time possible. The past has shown that users often don't consider ever-growing
333:         // state initially and would like to enable it later - without breaking the savepoint.
334:         // Setting it to Long.MAX_VALUE is a better default than 0. It comes with overhead which is
335:         // why a 0 declaration can override this for efficiency.
336:         if (globalRetentionTime == 0) {
337:             return Long.MAX_VALUE;
338:         }
339:         return globalRetentionTime;
340:     }
341: }
