164:     @Override
165:     public void initializeState(StateInitializationContext context) throws Exception {
166:         super.initializeState(context);
167:         WriterInitContext initContext = createInitContext(context.getRestoredCheckpointId());
168:         if (context.isRestored()) {
169:             if (committableSerializer != null) {
170:                 final ListState<List<CommT>> legacyCommitterState =
171:                         new SimpleVersionedListState<>(
172:                                 context.getOperatorStateStore()
173:                                         .getListState(STREAMING_COMMITTER_RAW_STATES_DESC),
174:                                 new SinkV1WriterCommittableSerializer<>(committableSerializer));
175:                 legacyCommitterState.get().forEach(legacyCommittables::addAll);
176:                 // FLINK-33437: clear legacy state
177:                 legacyCommitterState.clear();
178:             }
179:         }
180: 
181:         sinkWriter = writerStateHandler.createWriter(initContext, context);
182: 
183:         if (emitDownstream) {
184:             // Figure out if we have seen end of input before and if we can suppress creating
185:             // transactions and sending them downstream to the CommitterOperator. We have the
186:             // following
187:             // cases:
188:             // 1. state is empty:
189:             //   - First time initialization
190:             //   - Restoring from a previous version of Flink that didn't handle EOI
191:             //   - Upscaled from a final or regular checkpoint
192:             // In all cases, we regularly handle EOI, potentially resulting in duplicate summaries
193:             // that the CommitterOperator needs to handle.
194:             // 2. state is not empty:
195:             //   - This implies Flink restores from a version that handles EOI.
196:             //   - If there is one entry, no rescaling happened (for this subtask), so if it's true,
197:             //     we recover from a final checkpoint (for this subtask) and can ignore another EOI
198:             //     else we have a regular checkpoint.
199:             //   - If there are multiple entries, Flink downscaled, and we need to check if all are
200:             //     true and do the same as above. As soon as one entry is false, we regularly start
201:             //     the writer and potentially emit duplicate summaries if we indeed recovered from a
202:             //     final checkpoint.
203:             endOfInputState = context.getOperatorStateStore().getListState(END_OF_INPUT_STATE_DESC);
204:             ArrayList<Boolean> previousState = Lists.newArrayList(endOfInputState.get());
205:             endOfInput = !previousState.isEmpty() && !previousState.contains(false);
206:         }
207:     }
