227:     public void prepareSnapshotPreBarrier(long checkpointId) throws Exception {
228:         super.prepareSnapshotPreBarrier(checkpointId);
229:         if (!endOfInput) {
230:             sinkWriter.flush(false);
231:             emitCommittables(checkpointId);
232:         }
233:         // no records are expected to emit after endOfInput
234:     }
