256:     private void emitCommittables(long checkpointId) throws IOException, InterruptedException {
257:         if (!emitDownstream) {
258:             // To support SinkV1 topologies with only a writer we have to call prepareCommit
259:             // although no committables are forwarded
260:             if (sinkWriter instanceof CommittingSinkWriter) {
261:                 ((CommittingSinkWriter<?, ?>) sinkWriter).prepareCommit();
262:             }
263:             return;
264:         }
265:         Collection<CommT> committables =
266:                 ((CommittingSinkWriter<?, CommT>) sinkWriter).prepareCommit();
267:         StreamingRuntimeContext runtimeContext = getRuntimeContext();
268:         final int indexOfThisSubtask = runtimeContext.getTaskInfo().getIndexOfThisSubtask();
269:         final int numberOfParallelSubtasks =
270:                 runtimeContext.getTaskInfo().getNumberOfParallelSubtasks();
271: 
272:         // Emit only committable summary if there are legacy committables
273:         if (!legacyCommittables.isEmpty()) {
274:             checkState(checkpointId > WriterInitContext.INITIAL_CHECKPOINT_ID);
275:             emit(
276:                     indexOfThisSubtask,
277:                     numberOfParallelSubtasks,
278:                     WriterInitContext.INITIAL_CHECKPOINT_ID,
279:                     legacyCommittables);
280:             legacyCommittables.clear();
281:         }
282:         emit(indexOfThisSubtask, numberOfParallelSubtasks, checkpointId, committables);
283:     }
