71: /**
72:  * An operator that processes records to be written into a {@link
73:  * org.apache.flink.api.connector.sink2.Sink}. It also has a way to process committables with the
74:  * same parallelism or send them downstream to a {@link CommitterOperator} with a different
75:  * parallelism.
76:  *
77:  * <p>The operator is always part of a sink pipeline and is the first operator.
78:  *
79:  * @param <InputT> the type of the committable
80:  * @param <CommT> the type of the committable (to send to downstream operators)
81:  */
82: class SinkWriterOperator<InputT, CommT> extends AbstractStreamOperator<CommittableMessage<CommT>>
83:         implements OneInputStreamOperator<InputT, CommittableMessage<CommT>>, BoundedOneInput {
84: 
85:     /**
86:      * To support state migrations from 1.14 where the sinkWriter and committer where part of the
87:      * same operator.
88:      */
89:     private static final ListStateDescriptor<byte[]> STREAMING_COMMITTER_RAW_STATES_DESC =
90:             new ListStateDescriptor<>(
91:                     "streaming_committer_raw_states", BytePrimitiveArraySerializer.INSTANCE);
92: 
93:     @Nullable private final SimpleVersionedSerializer<CommT> committableSerializer;
94:     private final List<CommT> legacyCommittables = new ArrayList<>();
95: 
96:     /**
97:      * Used to remember that EOI has already happened so that we don't emit the last committables of
98:      * the final checkpoints twice.
99:      */
100:     private static final ListStateDescriptor<Boolean> END_OF_INPUT_STATE_DESC =
101:             new ListStateDescriptor<>("end_of_input_state", BooleanSerializer.INSTANCE);
102: 
103:     /** The runtime information of the input element. */
104:     private final Context<InputT> context;
105: 
106:     private final boolean emitDownstream;
107: 
108:     // ------------------------------- runtime fields ---------------------------------------
109: 
110:     /** We listen to this ourselves because we don't have an {@link InternalTimerService}. */
111:     private Long currentWatermark = Long.MIN_VALUE;
112: 
113:     private Writer<InputT> writer;
114: 
115:     private final SinkWriterStateHandler<InputT> writerStateHandler;
116: 
117:     private final MailboxExecutor mailboxExecutor;
118: 
119:     private boolean endOfInput = false;
120: 
121:     /**
122:      * Remembers the endOfInput state for (final) checkpoints iff the operator emits committables.
123:      */
124:     @Nullable private ListState<Boolean> endOfInputState;
125: 
126:     SinkWriterOperator(
127:             StreamOperatorParameters<CommittableMessage<CommT>> parameters,
128:             Sink<InputT> sink,
129:             ProcessingTimeService processingTimeService,
130:             MailboxExecutor mailboxExecutor) {
131:         super(parameters);
132:         this.processingTimeService = checkNotNull(processingTimeService);
133:         this.mailboxExecutor = checkNotNull(mailboxExecutor);
134:         this.context = new Context<>();
135:         this.emitDownstream = sink instanceof SupportsCommitter;
136: 
137:         if (sink instanceof SupportsWriterState) {
138:             writerStateHandler =
139:                     new StatefulSinkWriterStateHandler<>((SupportsWriterState<InputT, ?>) sink);
140:         } else {
141:             writerStateHandler = new StatelessSinkWriterStateHandler<>(sink);
142:         }
143: 
144:         if (sink instanceof SupportsCommitter) {
145:             committableSerializer = ((SupportsCommitter<CommT>) sink).getCommittableSerializer();
146:         } else {
147:             committableSerializer = null;
148:         }
149:     }
150: 
151:     @Override
152:     protected void setup(
153:             StreamTask<?, ?> containingTask,
154:             StreamConfig config,
155:             Output<StreamRecord<CommittableMessage<CommT>>> output) {
156:         super.setup(containingTask, config, output);
157:         // Metric "numRecordsOut" & "numBytesOut" is defined as the total number of records/bytes
158:         // written to the external system in FLIP-33, reuse them for task to account for traffic
159:         // with external system
160:         this.metrics.getIOMetricGroup().reuseOutputMetricsForTask();
161:         this.metrics.getIOMetricGroup().reuseBytesOutputMetricsForTask();
162:     }
163: 
164:     @Override
165:     public void initializeState(StateInitializationContext context) throws Exception {
166:         super.initializeState(context);
167:         WriterInitContext initContext = createInitContext(context.getRestoredCheckpointId());
168:         if (context.isRestored()) {
169:             if (committableSerializer != null) {
170:                 final ListState<List<CommT>> legacyCommitterState =
171:                         new SimpleVersionedListState<>(
172:                                 context.getOperatorStateStore()
173:                                         .getListState(STREAMING_COMMITTER_RAW_STATES_DESC),
174:                                 new SinkV1WriterCommittableSerializer<>(committableSerializer));
175:                 legacyCommitterState.get().forEach(legacyCommittables::addAll);
176:                 // FLINK-33437: clear legacy state
177:                 legacyCommitterState.clear();
178:             }
179:         }
180: 
181:         writer = writerStateHandler.createWriter(initContext, context);
182: 
183:         if (emitDownstream) {
184:             // Figure out if we have seen end of input before and if we can suppress creating
185:             // transactions and sending them downstream to the CommitterOperator. We have the
186:             // following
187:             // cases:
188:             // 1. state is empty:
189:             //   - First time initialization
190:             //   - Restoring from a previous version of Flink that didn't handle EOI
191:             //   - Upscaled from a final or regular checkpoint
192:             // In all cases, we regularly handle EOI, potentially resulting in duplicate summaries
193:             // that the CommitterOperator needs to handle.
194:             // 2. state is not empty:
195:             //   - This implies Flink restores from a version that handles EOI.
196:             //   - If there is one entry, no rescaling happened (for this subtask), so if it's true,
197:             //     we recover from a final checkpoint (for this subtask) and can ignore another EOI
198:             //     else we have a regular checkpoint.
199:             //   - If there are multiple entries, Flink downscaled, and we need to check if all are
200:             //     true and do the same as above. As soon as one entry is false, we regularly start
201:             //     the writer and potentially emit duplicate summaries if we indeed recovered from a
202:             //     final checkpoint.
203:             endOfInputState = context.getOperatorStateStore().getListState(END_OF_INPUT_STATE_DESC);
204:             ArrayList<Boolean> previousState = Lists.newArrayList(endOfInputState.get());
205:             endOfInput = !previousState.isEmpty() && !previousState.contains(false);
206:         }
207:     }
208: 
209:     @Override
210:     public void snapshotState(StateSnapshotContext context) throws Exception {
211:         super.snapshotState(context);
212:         writerStateHandler.snapshotState(context.getCheckpointId());
213:         if (endOfInputState != null) {
214:             endOfInputState.clear();
215:             endOfInputState.add(this.endOfInput);
216:         }
217:     }
218: 
219:     @Override
220:     public void processElement(StreamRecord<InputT> element) throws Exception {
221:         checkState(!endOfInput, "Received element after endOfInput: %s", element);
222:         context.element = element;
223:         writer.write(element.getValue(), context);
224:     }
225: 
226:     @Override
227:     public void prepareSnapshotPreBarrier(long checkpointId) throws Exception {
228:         super.prepareSnapshotPreBarrier(checkpointId);
229:         if (!endOfInput) {
230:             writer.flush(false);
231:             emitCommittables(checkpointId);
232:         }
233:         // no records are expected to emit after endOfInput
234:     }
235: 
236:     @Override
237:     public void processWatermark(Watermark mark) throws Exception {
238:         super.processWatermark(mark);
239:         this.currentWatermark = mark.getTimestamp();
240:         writer.writeWatermark(
241:                 new org.apache.flink.api.common.eventtime.Watermark(mark.getTimestamp()));
242:     }
243: 
244:     @Override
245:     public void endInput() throws Exception {
246:         if (!endOfInput) {
247:             endOfInput = true;
248:             if (endOfInputState != null) {
249:                 endOfInputState.add(true);
250:             }
251:             writer.flush(true);
252:             emitCommittables(CommittableMessage.EOI);
253:         }
254:     }
255: 
256:     private void emitCommittables(long checkpointId) throws IOException, InterruptedException {
257:         if (!emitDownstream) {
258:             // To support SinkV1 topologies with only a writer we have to call prepareCommit
259:             // although no committables are forwarded
260:             if (writer instanceof CommittingSinkWriter) {
261:                 ((CommittingSinkWriter<?, ?>) writer).prepareCommit();
262:             }
263:             return;
264:         }
265:         Collection<CommT> committables =
266:                 ((CommittingSinkWriter<?, CommT>) writer).prepareCommit();
267:         StreamingRuntimeContext runtimeContext = getRuntimeContext();
268:         final int indexOfThisSubtask = runtimeContext.getTaskInfo().getIndexOfThisSubtask();
269:         final int numberOfParallelSubtasks =
270:                 runtimeContext.getTaskInfo().getNumberOfParallelSubtasks();
271: 
272:         // Emit only committable summary if there are legacy committables
273:         if (!legacyCommittables.isEmpty()) {
274:             checkState(checkpointId > WriterInitContext.INITIAL_CHECKPOINT_ID);
275:             emit(
276:                     indexOfThisSubtask,
277:                     numberOfParallelSubtasks,
278:                     WriterInitContext.INITIAL_CHECKPOINT_ID,
279:                     legacyCommittables);
280:             legacyCommittables.clear();
281:         }
282:         emit(indexOfThisSubtask, numberOfParallelSubtasks, checkpointId, committables);
283:     }
284: 
285:     @Override
286:     public void close() throws Exception {
287:         closeAll(writer, super::close);
288:     }
289: 
290:     private void emit(
291:             int indexOfThisSubtask,
292:             int numberOfParallelSubtasks,
293:             long checkpointId,
294:             Collection<CommT> committables) {
295:         emit(
296:                 new StreamRecord<>(
297:                         new CommittableSummary<>(
298:                                 indexOfThisSubtask,
299:                                 numberOfParallelSubtasks,
300:                                 checkpointId,
301:                                 committables.size(),
302:                                 committables.size(),
303:                                 0)));
304:         for (CommT committable : committables) {
305:             emit(
306:                     new StreamRecord<>(
307:                             new CommittableWithLineage<>(
308:                                     committable, checkpointId, indexOfThisSubtask)));
309:         }
310:     }
311: 
312:     private void emit(StreamRecord<CommittableMessage<CommT>> message) {
313:         LOG.debug("Sending message to committer: {}", message);
314:         output.collect(message);
315:     }
