33: /**
34:  * Default {@link ReporterFilter} implementation that filters metrics based on {@link
35:  * MetricOptions#REPORTER_INCLUDES}/{@link MetricOptions#REPORTER_EXCLUDES}.
36:  */
37: public class DefaultMetricFilter implements ReporterFilter {
38: 
39:     private static final EnumSet<MetricType> ALL_METRIC_TYPES = EnumSet.allOf(MetricType.class);
40:     @VisibleForTesting static final String LIST_DELIMITER = ",";
41: 
42:     private final List<FilterSpec> includes;
43:     private final List<FilterSpec> excludes;
44: 
45:     private DefaultMetricFilter(List<FilterSpec> includes, List<FilterSpec> excludes) {
46:         this.includes = includes;
47:         this.excludes = excludes;
48:     }
49: 
50:     @Override
51:     public boolean filter(Metric metric, String name, String logicalScope) {
52:         for (FilterSpec exclude : excludes) {
53:             if (exclude.namePattern.matcher(name).matches()
54:                     && exclude.scopePattern.matcher(logicalScope).matches()
55:                     && exclude.types.contains(metric.getMetricType())) {
56:                 return false;
57:             }
58:         }
59:         for (FilterSpec include : includes) {
60:             if (include.namePattern.matcher(name).matches()
61:                     && include.scopePattern.matcher(logicalScope).matches()
62:                     && include.types.contains(metric.getMetricType())) {
63:                 return true;
64:             }
65:         }
66:         return false;
67:     }
68: 
69:     public static ReporterFilter fromConfiguration(Configuration configuration) {
70:         final List<String> includes = configuration.get(MetricOptions.REPORTER_INCLUDES);
71:         final List<String> excludes = configuration.get(MetricOptions.REPORTER_EXCLUDES);
72: 
73:         final List<FilterSpec> includeFilters =
74:                 includes.stream().map(i -> parse(i)).collect(Collectors.toList());
75:         final List<FilterSpec> excludeFilters =
76:                 excludes.stream().map(e -> parse(e)).collect(Collectors.toList());
77: 
78:         return new DefaultMetricFilter(includeFilters, excludeFilters);
79:     }
80: 
81:     private static FilterSpec parse(String filter) {
82:         final String[] split = filter.split(":");
83:         final Pattern scope = convertToPattern(split[0]);
84:         final Pattern name = split.length > 1 ? convertToPattern(split[1]) : convertToPattern("*");
85:         final EnumSet<MetricType> type =
86:                 split.length > 2 ? parseMetricTypes(split[2]) : ALL_METRIC_TYPES;
87: 
88:         return new FilterSpec(scope, name, type);
89:     }
90: 
91:     @VisibleForTesting
92:     static Pattern convertToPattern(String scopeOrNameComponent) {
93:         final String[] split = scopeOrNameComponent.split(LIST_DELIMITER);
94: 
95:         final String rawPattern =
96:                 Arrays.stream(split)
97:                         .map(s -> s.replaceAll("\\.", "\\."))
98:                         .map(s -> s.replaceAll("\\*", ".*"))
99:                         .collect(Collectors.joining("|", "(", ")"));
100: 
101:         return Pattern.compile(rawPattern);
102:     }
103: 
104:     @VisibleForTesting
105:     static EnumSet<MetricType> parseMetricTypes(String typeComponent) {
106:         final String[] split = typeComponent.split(LIST_DELIMITER);
107: 
108:         if (split.length == 1 && split[0].equals("*")) {
109:             return ALL_METRIC_TYPES;
110:         }
111: 
112:         return EnumSet.copyOf(
113:                 Arrays.stream(split)
114:                         .map(s -> ConfigurationUtils.convertToEnum(s, MetricType.class))
115:                         .collect(Collectors.toSet()));
116:     }
117: 
118:     private static class FilterSpec {
119:         private final Pattern scopePattern;
120:         private final Pattern namePattern;
121:         private final EnumSet<MetricType> types;
122: 
123:         private FilterSpec(Pattern scopePattern, Pattern namePattern, EnumSet<MetricType> types) {
124:             this.scopePattern = scopePattern;
125:             this.namePattern = namePattern;
126:             this.types = types;
127:         }
128:     }
129: }
