131: /**
132:  * Converter from Flink's specific relational representation: {@link QueryOperation} to Calcite's
133:  * specific relational representation: {@link RelNode}.
134:  */
135: @Internal
136: public class QueryOperationConverter extends QueryOperationDefaultVisitor<RelNode> {
137: 
138:     private final FlinkRelBuilder relBuilder;
139:     private final SingleRelVisitor singleRelVisitor = new SingleRelVisitor();
140:     private final ExpressionConverter expressionConverter;
141:     private final AggregateVisitor aggregateVisitor = new AggregateVisitor();
142:     private final TableAggregateVisitor tableAggregateVisitor = new TableAggregateVisitor();
143:     private final JoinExpressionVisitor joinExpressionVisitor = new JoinExpressionVisitor();
144:     private final boolean isBatchMode;
145: 
146:     public QueryOperationConverter(FlinkRelBuilder relBuilder, boolean isBatchMode) {
147:         this.relBuilder = relBuilder;
148:         this.expressionConverter = new ExpressionConverter(relBuilder);
149:         this.isBatchMode = isBatchMode;
150:     }
151: 
152:     @Override
153:     public RelNode defaultMethod(QueryOperation other) {
154:         other.getChildren().forEach(child -> relBuilder.push(child.accept(this)));
155:         return other.accept(singleRelVisitor);
156:     }
157: 
158:     private class SingleRelVisitor implements QueryOperationVisitor<RelNode> {
159: 
160:         @Override
161:         public RelNode visit(ProjectQueryOperation projection) {
162:             List<RexNode> rexNodes = convertToRexNodes(projection.getProjectList());
163: 
164:             return relBuilder
165:                     .project(rexNodes, projection.getResolvedSchema().getColumnNames(), true)
166:                     .build();
167:         }
168: 
169:         @Override
170:         public RelNode visit(AggregateQueryOperation aggregate) {
171:             List<AggCall> aggregations =
172:                     aggregate.getAggregateExpressions().stream()
173:                             .map(this::getAggCall)
174:                             .collect(toList());
175: 
176:             List<RexNode> groupings = convertToRexNodes(aggregate.getGroupingExpressions());
177:             GroupKey groupKey = relBuilder.groupKey(groupings);
178:             return relBuilder.aggregate(groupKey, aggregations).build();
179:         }
180: 
181:         @Override
182:         public RelNode visit(WindowAggregateQueryOperation windowAggregate) {
183:             List<AggCall> aggregations =
184:                     windowAggregate.getAggregateExpressions().stream()
185:                             .map(this::getAggCall)
186:                             .collect(toList());
187: 
188:             List<RexNode> groupings = convertToRexNodes(windowAggregate.getGroupingExpressions());
189:             LogicalWindow logicalWindow = toLogicalWindow(windowAggregate.getGroupWindow());
190:             WindowReference windowReference = logicalWindow.aliasAttribute();
191:             List<NamedWindowProperty> windowProperties =
192:                     windowAggregate.getWindowPropertiesExpressions().stream()
193:                             .map(expr -> convertToWindowProperty(expr, windowReference))
194:                             .collect(toList());
195:             GroupKey groupKey = relBuilder.groupKey(groupings);
196:             return relBuilder
197:                     .windowAggregate(logicalWindow, groupKey, windowProperties, aggregations)
198:                     .build();
199:         }
200: 
201:         private NamedWindowProperty convertToWindowProperty(
202:                 Expression expression, WindowReference windowReference) {
203:             Preconditions.checkArgument(
204:                     expression instanceof CallExpression, "This should never happened");
205:             CallExpression aliasExpr = (CallExpression) expression;
206:             Preconditions.checkArgument(
207:                     BuiltInFunctionDefinitions.AS == aliasExpr.getFunctionDefinition(),
208:                     "This should never happened");
209:             String name =
210:                     ((ValueLiteralExpression) aliasExpr.getChildren().get(1))
211:                             .getValueAs(String.class)
212:                             .orElseThrow(() -> new TableException("Invalid literal."));
213:             Expression windowPropertyExpr = aliasExpr.getChildren().get(0);
214:             Preconditions.checkArgument(
215:                     windowPropertyExpr instanceof CallExpression, "This should never happened");
216:             CallExpression windowPropertyCallExpr = (CallExpression) windowPropertyExpr;
217:             FunctionDefinition fd = windowPropertyCallExpr.getFunctionDefinition();
218:             if (BuiltInFunctionDefinitions.WINDOW_START == fd) {
219:                 return new NamedWindowProperty(name, new WindowStart(windowReference));
220:             } else if (BuiltInFunctionDefinitions.WINDOW_END == fd) {
221:                 return new NamedWindowProperty(name, new WindowEnd(windowReference));
222:             } else if (BuiltInFunctionDefinitions.PROCTIME == fd) {
223:                 return new NamedWindowProperty(name, new ProctimeAttribute(windowReference));
224:             } else if (BuiltInFunctionDefinitions.ROWTIME == fd) {
225:                 return new NamedWindowProperty(name, new RowtimeAttribute(windowReference));
226:             } else {
227:                 throw new TableException("Invalid literal.");
228:             }
229:         }
230: 
231:         /** Get the {@link AggCall} correspond to the aggregate or table aggregate expression. */
232:         private AggCall getAggCall(Expression aggregateExpression) {
233:             if (isFunctionOfKind(aggregateExpression, TABLE_AGGREGATE)) {
234:                 return aggregateExpression.accept(tableAggregateVisitor);
235:             } else {
236:                 return aggregateExpression.accept(aggregateVisitor);
237:             }
238:         }
239: 
240:         @Override
241:         public RelNode visit(JoinQueryOperation join) {
242:             final Set<CorrelationId> corSet;
243:             if (join.isCorrelated()) {
244:                 corSet = Collections.singleton(relBuilder.peek().getCluster().createCorrel());
245:             } else {
246:                 corSet = Collections.emptySet();
247:             }
248: 
249:             return relBuilder
250:                     .join(
251:                             convertJoinType(join.getJoinType()),
252:                             join.getCondition().accept(joinExpressionVisitor),
253:                             corSet)
254:                     .build();
255:         }
256: 
257:         @Override
258:         public RelNode visit(SetQueryOperation setOperation) {
259:             switch (setOperation.getType()) {
260:                 case INTERSECT:
261:                     relBuilder.intersect(setOperation.isAll());
262:                     break;
263:                 case MINUS:
264:                     relBuilder.minus(setOperation.isAll());
265:                     break;
266:                 case UNION:
267:                     relBuilder.union(setOperation.isAll());
268:                     break;
269:             }
270:             return relBuilder.build();
271:         }
272: 
273:         @Override
274:         public RelNode visit(FilterQueryOperation filter) {
275:             RexNode rexNode = convertExprToRexNode(filter.getCondition());
276:             return relBuilder.filter(rexNode).build();
277:         }
278: 
279:         @Override
280:         public RelNode visit(DistinctQueryOperation distinct) {
281:             return relBuilder.distinct().build();
282:         }
283: 
284:         @Override
285:         public RelNode visit(SortQueryOperation sort) {
286:             List<RexNode> rexNodes = convertToRexNodes(sort.getOrder());
287:             return relBuilder.sortLimit(sort.getOffset(), sort.getFetch(), rexNodes).build();
288:         }
289: 
290:         @Override
291:         public RelNode visit(CorrelatedFunctionQueryOperation calculatedTable) {
292:             final ContextResolvedFunction resolvedFunction = calculatedTable.getResolvedFunction();
293:             final List<RexNode> parameters = convertToRexNodes(calculatedTable.getArguments());
294: 
295:             final FunctionDefinition functionDefinition = resolvedFunction.getDefinition();
296:             if (functionDefinition instanceof TableFunctionDefinition) {
297:                 final FlinkTypeFactory typeFactory = relBuilder.getTypeFactory();
298:                 return convertLegacyTableFunction(
299:                         calculatedTable,
300:                         (TableFunctionDefinition) functionDefinition,
301:                         parameters,
302:                         typeFactory);
303:             }
304: 
305:             final BridgingSqlFunction sqlFunction =
306:                     BridgingSqlFunction.of(relBuilder.getCluster(), resolvedFunction);
307: 
308:             FlinkRelBuilder.pushFunctionScan(
309:                     relBuilder,
310:                     sqlFunction,
311:                     0,
312:                     parameters,
313:                     calculatedTable.getResolvedSchema().getColumnNames());
314: 
315:             return relBuilder.build();
316:         }
317: 
318:         private RelNode convertLegacyTableFunction(
319:                 CorrelatedFunctionQueryOperation calculatedTable,
320:                 TableFunctionDefinition functionDefinition,
321:                 List<RexNode> parameters,
322:                 FlinkTypeFactory typeFactory) {
323:             List<String> fieldNames = calculatedTable.getResolvedSchema().getColumnNames();
324: 
325:             TableFunction<?> tableFunction = functionDefinition.getTableFunction();
326:             DataType resultType = fromLegacyInfoToDataType(functionDefinition.getResultType());
327:             TypedFlinkTableFunction function =
328:                     new TypedFlinkTableFunction(
329:                             tableFunction, fieldNames.toArray(new String[0]), resultType);
330: 
331:             final TableSqlFunction sqlFunction =
332:                     new TableSqlFunction(
333:                             calculatedTable.getResolvedFunction().getIdentifier().orElse(null),
334:                             tableFunction.toString(),
335:                             tableFunction,
336:                             resultType,
337:                             typeFactory,
338:                             function,
339:                             scala.Option.empty());
340:             return LogicalTableFunctionScan.create(
341:                     relBuilder.peek().getCluster(),
342:                     Collections.emptyList(),
343:                     relBuilder
344:                             .getRexBuilder()
345:                             .makeCall(function.getRowType(typeFactory), sqlFunction, parameters),
346:                     function.getElementType(null),
347:                     function.getRowType(typeFactory),
348:                     null);
349:         }
350: 
351:         @Override
352:         public RelNode visit(SourceQueryOperation queryOperation) {
353:             ContextResolvedTable contextResolvedTable = queryOperation.getContextResolvedTable();
354:             if (contextResolvedTable.isAnonymous()) {
355:                 return CatalogSourceTable.createAnonymous(
356:                                 relBuilder, contextResolvedTable, isBatchMode)
357:                         .toRel(ViewExpanders.simpleContext(relBuilder.getCluster()));
358:             }
359:             return relBuilder
360:                     .scan(queryOperation.getContextResolvedTable().getIdentifier().toList())
361:                     .build();
362:         }
363: 
364:         @Override
365:         public RelNode visit(ValuesQueryOperation values) {
366:             RelDataType rowType =
367:                     relBuilder
368:                             .getTypeFactory()
369:                             .buildRelNodeRowType(
370:                                     TableSchema.fromResolvedSchema(values.getResolvedSchema()));
371:             if (values.getValues().isEmpty()) {
372:                 relBuilder.values(rowType);
373:                 return relBuilder.build();
374:             }
375: 
376:             List<List<RexLiteral>> rexLiterals = new ArrayList<>();
377:             List<List<RexNode>> rexProjections = new ArrayList<>();
378: 
379:             splitToProjectionsAndLiterals(values, rexLiterals, rexProjections);
380: 
381:             int inputs = 0;
382:             if (rexLiterals.size() != 0) {
383:                 inputs += 1;
384:                 relBuilder.values(rexLiterals, rowType);
385:             }
386: 
387:             if (rexProjections.size() != 0) {
388:                 inputs += rexProjections.size();
389:                 applyProjections(values, rexProjections);
390:             }
391: 
392:             if (inputs > 1) {
393:                 relBuilder.union(true, inputs);
394:             }
395:             return relBuilder.build();
396:         }
397: 
398:         private void applyProjections(
399:                 ValuesQueryOperation values, List<List<RexNode>> rexProjections) {
400:             List<RelNode> relNodes =
401:                     rexProjections.stream()
402:                             .map(
403:                                     exprs -> {
404:                                         relBuilder.push(
405:                                                 LogicalValues.createOneRow(
406:                                                         relBuilder.getCluster()));
407:                                         relBuilder.project(
408:                                                 exprs, values.getResolvedSchema().getColumnNames());
409:                                         return relBuilder.build();
410:                                     })
411:                             .collect(toList());
412:             relBuilder.pushAll(relNodes);
413:         }
414: 
415:         private void splitToProjectionsAndLiterals(
416:                 ValuesQueryOperation values,
417:                 List<List<RexLiteral>> rexValues,
418:                 List<List<RexNode>> rexProjections) {
419:             values.getValues().stream()
420:                     .map(this::convertToRexNodes)
421:                     .forEach(
422:                             row -> {
423:                                 boolean allLiterals =
424:                                         row.stream().allMatch(expr -> expr instanceof RexLiteral);
425:                                 if (allLiterals) {
426:                                     rexValues.add(
427:                                             row.stream()
428:                                                     .map(expr -> (RexLiteral) expr)
429:                                                     .collect(toList()));
430:                                 } else {
431:                                     rexProjections.add(row);
432:                                 }
433:                             });
434:         }
