436:         @Override
437:         public RelNode visit(QueryOperation other) {
438:             if (other instanceof PlannerQueryOperation) {
439:                 return ((PlannerQueryOperation) other).getCalciteTree();
440:             } else if (other instanceof PlannerExternalQueryOperation) {
441:                 return ((PlannerExternalQueryOperation) other).getCalciteTree();
442:             } else if (other instanceof InternalDataStreamQueryOperation) {
443:                 return convertToDataStreamScan((InternalDataStreamQueryOperation<?>) other);
444:             } else if (other instanceof ExternalQueryOperation) {
445:                 final ExternalQueryOperation<?> externalQueryOperation =
446:                         (ExternalQueryOperation<?>) other;
447:                 return convertToExternalScan(
448:                         externalQueryOperation.getContextResolvedTable(),
449:                         externalQueryOperation.getDataStream(),
450:                         externalQueryOperation.getPhysicalDataType(),
451:                         externalQueryOperation.isTopLevelRecord(),
452:                         externalQueryOperation.getChangelogMode());
453:             }
454:             // legacy
455:             else if (other instanceof DataStreamQueryOperation) {
456:                 DataStreamQueryOperation<?> dataStreamQueryOperation =
457:                         (DataStreamQueryOperation<?>) other;
458:                 return convertToDataStreamScan(
459:                         dataStreamQueryOperation.getDataStream(),
460:                         dataStreamQueryOperation.getFieldIndices(),
461:                         dataStreamQueryOperation.getResolvedSchema(),
462:                         dataStreamQueryOperation.getIdentifier());
463:             }
464: 
465:             throw new TableException("Unknown table operation: " + other);
466:         }
467: 
468:         @Override
469:         public <U> RelNode visit(TableSourceQueryOperation<U> tableSourceOperation) {
470:             TableSource<?> tableSource = tableSourceOperation.getTableSource();
471:             boolean isBatch;
472:             if (tableSource instanceof LookupableTableSource) {
473:                 isBatch = tableSourceOperation.isBatch();
474:             } else if (tableSource instanceof StreamTableSource) {
475:                 isBatch = ((StreamTableSource<?>) tableSource).isBounded();
476:             } else {
477:                 throw new TableException(
478:                         String.format(
479:                                 "%s is not supported.", tableSource.getClass().getSimpleName()));
480:             }
481: 
482:             FlinkStatistic statistic;
483:             ObjectIdentifier tableIdentifier;
484:             if (tableSourceOperation instanceof RichTableSourceQueryOperation
485:                     && ((RichTableSourceQueryOperation<U>) tableSourceOperation).getIdentifier()
486:                             != null) {
487:                 tableIdentifier =
488:                         ((RichTableSourceQueryOperation<U>) tableSourceOperation).getIdentifier();
489:                 statistic =
490:                         ((RichTableSourceQueryOperation<U>) tableSourceOperation).getStatistic();
491:             } else {
492:                 statistic = FlinkStatistic.UNKNOWN();
493:                 // TableSourceScan requires a unique name of a Table for computing a digest.
494:                 // We are using the identity hash of the TableSource object.
495:                 String refId = "Unregistered_TableSource_" + System.identityHashCode(tableSource);
496:                 CatalogManager catalogManager =
497:                         relBuilder
498:                                 .getCluster()
499:                                 .getPlanner()
500:                                 .getContext()
501:                                 .unwrap(FlinkContext.class)
502:                                 .getCatalogManager();
503:                 tableIdentifier = catalogManager.qualifyIdentifier(UnresolvedIdentifier.of(refId));
504:             }
505: 
506:             RelDataType rowType =
507:                     TableSourceUtil.getSourceRowTypeFromSource(
508:                             relBuilder.getTypeFactory(), tableSource, !isBatch);
509:             LegacyTableSourceTable<?> tableSourceTable =
510:                     new LegacyTableSourceTable<>(
511:                             relBuilder.getRelOptSchema(),
512:                             tableIdentifier,
513:                             rowType,
514:                             statistic,
515:                             tableSource,
516:                             !isBatch,
517:                             ConnectorCatalogTable.source(tableSource, isBatch));
518:             return LogicalTableScan.create(
519:                     relBuilder.getCluster(), tableSourceTable, Collections.emptyList());
520:         }
