522:         private RelNode convertToExternalScan(
523:                 ContextResolvedTable contextResolvedTable,
524:                 DataStream<?> dataStream,
525:                 DataType physicalDataType,
526:                 boolean isTopLevelRecord,
527:                 ChangelogMode changelogMode) {
528:             final FlinkContext flinkContext = ShortcutUtils.unwrapContext(relBuilder);
529:             return DynamicSourceUtils.convertDataStreamToRel(
530:                     flinkContext.isBatchMode(),
531:                     flinkContext.getTableConfig(),
532:                     relBuilder,
533:                     contextResolvedTable,
534:                     dataStream,
535:                     physicalDataType,
536:                     isTopLevelRecord,
537:                     changelogMode);
538:         }
