540:         private RelNode convertToDataStreamScan(InternalDataStreamQueryOperation<?> operation) {
541:             List<String> names;
542:             ObjectIdentifier identifier = operation.getIdentifier();
543:             if (identifier != null) {
544:                 names =
545:                         Arrays.asList(
546:                                 identifier.getCatalogName(),
547:                                 identifier.getDatabaseName(),
548:                                 identifier.getObjectName());
549:             } else {
550:                 String refId =
551:                         String.format(
552:                                 "Unregistered_DataStream_%s", operation.getDataStream().getId());
553:                 names = Collections.singletonList(refId);
554:             }
555: 
556:             final RelDataType rowType =
557:                     DataStreamTable$.MODULE$.getRowType(
558:                             relBuilder.getTypeFactory(),
559:                             operation.getDataStream(),
560:                             operation.getResolvedSchema().getColumnNames().toArray(new String[0]),
561:                             operation.getFieldIndices(),
562:                             scala.Option.apply(operation.getFieldNullables()));
563:             DataStreamTable<?> dataStreamTable =
564:                     new DataStreamTable<>(
565:                             relBuilder.getRelOptSchema(),
566:                             names,
567:                             rowType,
568:                             operation.getDataStream(),
569:                             operation.getFieldIndices(),
570:                             operation.getResolvedSchema().getColumnNames().toArray(new String[0]),
571:                             operation.getStatistic(),
572:                             scala.Option.apply(operation.getFieldNullables()));
573:             return LogicalTableScan.create(
574:                     relBuilder.getCluster(), dataStreamTable, Collections.emptyList());
575:         }
