577:         private RelNode convertToDataStreamScan(
578:                 DataStream<?> dataStream,
579:                 int[] fieldIndices,
580:                 ResolvedSchema resolvedSchema,
581:                 Optional<ObjectIdentifier> identifier) {
582:             List<String> names;
583:             if (identifier.isPresent()) {
584:                 names =
585:                         Arrays.asList(
586:                                 identifier.get().getCatalogName(),
587:                                 identifier.get().getDatabaseName(),
588:                                 identifier.get().getObjectName());
589:             } else {
590:                 String refId = String.format("Unregistered_DataStream_%s", dataStream.getId());
591:                 names = Collections.singletonList(refId);
592:             }
593:             final RelDataType rowType =
594:                     DataStreamTable$.MODULE$.getRowType(
595:                             relBuilder.getTypeFactory(),
596:                             dataStream,
597:                             resolvedSchema.getColumnNames().toArray(new String[0]),
598:                             fieldIndices,
599:                             scala.Option.empty());
600:             DataStreamTable<?> dataStreamTable =
601:                     new DataStreamTable<>(
602:                             relBuilder.getRelOptSchema(),
603:                             names,
604:                             rowType,
605:                             dataStream,
606:                             fieldIndices,
607:                             resolvedSchema.getColumnNames().toArray(new String[0]),
608:                             FlinkStatistic.UNKNOWN(),
609:                             scala.Option.empty());
610:             return LogicalTableScan.create(
611:                     relBuilder.getCluster(), dataStreamTable, Collections.emptyList());
612:         }
