620:         private LogicalWindow toLogicalWindow(ResolvedGroupWindow window) {
621:             DataType windowType = window.getTimeAttribute().getOutputDataType();
622:             WindowReference windowReference =
623:                     new WindowReference(window.getAlias(), fromDataToLogicalType(windowType));
624:             switch (window.getType()) {
625:                 case SLIDE:
626:                     return new SlidingGroupWindow(
627:                             windowReference,
628:                             window.getTimeAttribute(),
629:                             window.getSize()
630:                                     .orElseThrow(
631:                                             () -> new TableException("missed size parameters!")),
632:                             window.getSlide()
633:                                     .orElseThrow(
634:                                             () -> new TableException("missed slide parameters!")));
635:                 case SESSION:
636:                     return new SessionGroupWindow(
637:                             windowReference,
638:                             window.getTimeAttribute(),
639:                             window.getGap()
640:                                     .orElseThrow(
641:                                             () -> new TableException("missed gap parameters!")));
642:                 case TUMBLE:
643:                     return new TumblingGroupWindow(
644:                             windowReference,
645:                             window.getTimeAttribute(),
646:                             window.getSize()
647:                                     .orElseThrow(
648:                                             () -> new TableException("missed size parameters!")));
649:                 default:
650:                     throw new TableException("Unknown window type");
651:             }
652:         }
653: 
654:         private JoinRelType convertJoinType(JoinType joinType) {
655:             switch (joinType) {
656:                 case INNER:
657:                     return JoinRelType.INNER;
658:                 case LEFT_OUTER:
659:                     return JoinRelType.LEFT;
660:                 case RIGHT_OUTER:
661:                     return JoinRelType.RIGHT;
662:                 case FULL_OUTER:
663:                     return JoinRelType.FULL;
664:                 default:
665:                     throw new TableException("Unknown join type: " + joinType);
666:             }
667:         }
668:     }
