670:     private class JoinExpressionVisitor extends ExpressionDefaultVisitor<RexNode> {
671: 
672:         private static final int numberOfJoinInputs = 2;
673: 
674:         @Override
675:         public RexNode visit(CallExpression callExpression) {
676:             final List<ResolvedExpression> newChildren =
677:                     callExpression.getChildren().stream()
678:                             .map(
679:                                     expr -> {
680:                                         RexNode convertedNode = expr.accept(this);
681:                                         return new RexNodeExpression(
682:                                                 convertedNode,
683:                                                 ((ResolvedExpression) expr).getOutputDataType(),
684:                                                 null,
685:                                                 null);
686:                                     })
687:                             .collect(Collectors.toList());
688: 
689:             final CallExpression newCall =
690:                     callExpression.replaceArgs(newChildren, callExpression.getOutputDataType());
691:             return convertExprToRexNode(newCall);
692:         }
693: 
694:         @Override
695:         public RexNode visit(FieldReferenceExpression fieldReference) {
696:             return relBuilder.field(
697:                     numberOfJoinInputs,
698:                     fieldReference.getInputIndex(),
699:                     fieldReference.getFieldIndex());
700:         }
701: 
702:         @Override
703:         protected RexNode defaultMethod(Expression expression) {
704:             return convertExprToRexNode(expression);
705:         }
706:     }
