708:     private class AggregateVisitor extends ExpressionDefaultVisitor<AggCall> {
709: 
710:         @Override
711:         public AggCall visit(CallExpression unresolvedCall) {
712:             if (unresolvedCall.getFunctionDefinition() == AS) {
713:                 String aggregateName =
714:                         extractValue(unresolvedCall.getChildren().get(1), String.class)
715:                                 .orElseThrow(() -> new TableException("Unexpected name."));
716: 
717:                 Expression aggregate = unresolvedCall.getChildren().get(0);
718:                 if (isFunctionOfKind(aggregate, AGGREGATE)) {
719:                     return aggregate.accept(
720:                             new AggCallVisitor(
721:                                     relBuilder, expressionConverter, aggregateName, false));
722:                 }
723:             }
724:             throw new TableException("Expected named aggregate. Got: " + unresolvedCall);
725:         }
726: 
727:         @Override
728:         protected AggCall defaultMethod(Expression expression) {
729:             throw new TableException("Unexpected expression: " + expression);
730:         }
