732:         private class AggCallVisitor extends ExpressionDefaultVisitor<RelBuilder.AggCall> {
733: 
734:             private final RelBuilder relBuilder;
735:             private final SqlAggFunctionVisitor sqlAggFunctionVisitor;
736:             private final ExpressionConverter expressionConverter;
737:             private final String name;
738:             private final boolean isDistinct;
739: 
740:             public AggCallVisitor(
741:                     RelBuilder relBuilder,
742:                     ExpressionConverter expressionConverter,
743:                     String name,
744:                     boolean isDistinct) {
745:                 this.relBuilder = relBuilder;
746:                 this.sqlAggFunctionVisitor = new SqlAggFunctionVisitor(relBuilder);
747:                 this.expressionConverter = expressionConverter;
748:                 this.name = name;
749:                 this.isDistinct = isDistinct;
750:             }
751: 
752:             @Override
