393:             dos.writeInt(handle.getKeyGroupRange().getStartKeyGroup());
394:             dos.writeInt(handle.getKeyGroupRange().getNumberOfKeyGroups());
395:             dos.writeLong(handle.getFrom());
396:             dos.writeLong(handle.getTo());
397:             dos.writeInt(handle.getChanges().size());
398:             for (StateChange change : handle.getChanges()) {
399:                 dos.writeInt(change.getKeyGroup());
