88: /**
89:  * Base (De)serializer for checkpoint metadata format version 2 and 3.
90:  *
91:  * <p>The difference between versions 2 and 3 is minor. Version 3 includes operator coordinator
92:  * state for each operator, and drops some minor unused fields.
93:  *
94:  * <p>Basic checkpoint metadata layout:
95:  *
96:  * <pre>
97:  *  +--------------+---------------+-----------------+
98:  *  | checkpointID | master states | operator states |
99:  *  +--------------+---------------+-----------------+
100:  *
101:  *  Master state:
102:  *  +--------------+---------------------+---------+------+---------------+
103:  *  | magic number | num remaining bytes | version | name | payload bytes |
104:  *  +--------------+---------------------+---------+------+---------------+
105:  * </pre>
106:  */
107: @Internal
108: public abstract class MetadataV2V3SerializerBase {
109:     private static final Logger LOG = LoggerFactory.getLogger(MetadataV2V3SerializerBase.class);
110: 
111:     /** Random magic number for consistency checks. */
112:     private static final int MASTER_STATE_MAGIC_NUMBER = 0xc96b1696;
113: 
114:     private static final byte NULL_HANDLE = 0;
115:     private static final byte BYTE_STREAM_STATE_HANDLE = 1;
116:     private static final byte FILE_STREAM_STATE_HANDLE = 2;
117:     private static final byte KEY_GROUPS_HANDLE = 3;
118:     private static final byte PARTITIONABLE_OPERATOR_STATE_HANDLE = 4;
119:     private static final byte INCREMENTAL_KEY_GROUPS_HANDLE = 5;
120:     private static final byte RELATIVE_STREAM_STATE_HANDLE = 6;
121:     private static final byte SAVEPOINT_KEY_GROUPS_HANDLE = 7;
122:     private static final byte CHANGELOG_HANDLE = 8;
123:     private static final byte CHANGELOG_BYTE_INCREMENT_HANDLE = 9;
124:     private static final byte CHANGELOG_FILE_INCREMENT_HANDLE = 10;
125:     // INCREMENTAL_KEY_GROUPS_HANDLE_V2 is introduced to add field of checkpointedSize and
126:     // stateHandleId.
127:     private static final byte INCREMENTAL_KEY_GROUPS_HANDLE_V2 = 11;
128:     // KEY_GROUPS_HANDLE_V2 is introduced to add new field of stateHandleId.
129:     private static final byte KEY_GROUPS_HANDLE_V2 = 12;
130:     // CHANGELOG_FILE_INCREMENT_HANDLE_V2 is introduced to add new field of storageIdentifier.
131:     private static final byte CHANGELOG_FILE_INCREMENT_HANDLE_V2 = 13;
132:     // CHANGELOG_HANDLE_V2 is introduced to add new field of checkpointId.
133:     private static final byte CHANGELOG_HANDLE_V2 = 14;
134: 
135:     // SEGMENT_FILE_HANDLE is introduced to support file merging.
136:     private static final byte SEGMENT_FILE_HANDLE = 15;
137: 
138:     // EMPTY_SEGMENT_FILE_HANDLE is introduced as a placeholder for file merging.
139:     private static final byte EMPTY_SEGMENT_FILE_HANDLE = 16;
140: 
141:     // SEGMENT_PARTITIONABLE_OPERATOR_STATE_HANDLE is introduced for file merging of operator state.
142:     private static final byte SEGMENT_PARTITIONABLE_OPERATOR_STATE_HANDLE = 17;
143: 
144:     // ------------------------------------------------------------------------
145:     //  (De)serialization entry points
146:     // ------------------------------------------------------------------------
147: 
148:     protected void serializeMetadata(CheckpointMetadata checkpointMetadata, DataOutputStream dos)
149:             throws IOException {
150:         // first: checkpoint ID
151:         dos.writeLong(checkpointMetadata.getCheckpointId());
152: 
153:         // second: master state
154:         final Collection<MasterState> masterStates = checkpointMetadata.getMasterStates();
155:         dos.writeInt(masterStates.size());
156:         for (MasterState ms : masterStates) {
157:             serializeMasterState(ms, dos);
158:         }
159: 
160:         // third: operator states
161:         Collection<OperatorState> operatorStates = checkpointMetadata.getOperatorStates();
162:         dos.writeInt(operatorStates.size());
163: 
164:         for (OperatorState operatorState : operatorStates) {
165:             serializeOperatorState(operatorState, dos);
166:         }
167:     }
168: 
169:     protected CheckpointMetadata deserializeMetadata(
170:             DataInputStream dis, @Nullable String externalPointer) throws IOException {
171: 
172:         final DeserializationContext context =
173:                 externalPointer == null ? null : new DeserializationContext(externalPointer);
174: 
175:         // first: checkpoint ID
176:         final long checkpointId = dis.readLong();
177:         if (checkpointId < 0) {
178:             throw new IOException("invalid checkpoint ID: " + checkpointId);
179:         }
180: 
181:         // second: master state
182:         final List<MasterState> masterStates;
183:         final int numMasterStates = dis.readInt();
184: 
185:         if (numMasterStates == 0) {
186:             masterStates = Collections.emptyList();
187:         } else if (numMasterStates > 0) {
188:             masterStates = new ArrayList<>(numMasterStates);
189:             for (int i = 0; i < numMasterStates; i++) {
190:                 masterStates.add(deserializeMasterState(dis));
191:             }
192:         } else {
193:             throw new IOException("invalid number of master states: " + numMasterStates);
194:         }
195: 
196:         // third: operator states
197:         final int numTaskStates = dis.readInt();
198:         final List<OperatorState> operatorStates = new ArrayList<>(numTaskStates);
199: 
200:         for (int i = 0; i < numTaskStates; i++) {
201:             operatorStates.add(deserializeOperatorState(dis, context));
202:         }
203: 
204:         return new CheckpointMetadata(checkpointId, operatorStates, masterStates);
205:     }
206: 
207:     // ------------------------------------------------------------------------
208:     //  master state (de)serialization methods
209:     // ------------------------------------------------------------------------
210: 
211:     protected void serializeMasterState(MasterState state, DataOutputStream dos)
212:             throws IOException {
213:         // magic number for error detection
214:         dos.writeInt(MASTER_STATE_MAGIC_NUMBER);
215: 
216:         // for safety, we serialize first into an array and then write the array and its
217:         // length into the checkpoint
218:         final ByteArrayOutputStream baos = new ByteArrayOutputStream();
219:         final DataOutputStream out = new DataOutputStream(baos);
220: 
221:         out.writeInt(state.version());
222:         out.writeUTF(state.name());
223: 
224:         final byte[] bytes = state.bytes();
225:         out.writeInt(bytes.length);
226:         out.write(bytes, 0, bytes.length);
227: 
228:         out.close();
229:         byte[] data = baos.toByteArray();
230: 
231:         dos.writeInt(data.length);
232:         dos.write(data, 0, data.length);
233:     }
234: 
235:     protected MasterState deserializeMasterState(DataInputStream dis) throws IOException {
236:         final int magicNumber = dis.readInt();
237:         if (magicNumber != MASTER_STATE_MAGIC_NUMBER) {
238:             throw new IOException("incorrect magic number in master styte byte sequence");
239:         }
240: 
241:         final int numBytes = dis.readInt();
242:         if (numBytes <= 0) {
243:             throw new IOException("found zero or negative length for master state bytes");
244:         }
245: 
246:         final byte[] data = new byte[numBytes];
247:         dis.readFully(data);
248: 
249:         final DataInputStream in = new DataInputStream(new ByteArrayInputStream(data));
250: 
251:         final int version = in.readInt();
252:         final String name = in.readUTF();
253: 
254:         final byte[] bytes = new byte[in.readInt()];
255:         in.readFully(bytes);
256: 
257:         // check that the data is not corrupt
258:         if (in.read() != -1) {
259:             throw new IOException("found trailing bytes in master state");
260:         }
261: 
262:         return new MasterState(name, bytes, version);
263:     }
