325:     @VisibleForTesting
326:     static void serializeKeyedStateHandle(KeyedStateHandle stateHandle, DataOutputStream dos)
327:             throws IOException {
328:         if (stateHandle == null) {
329:             dos.writeByte(NULL_HANDLE);
330:         } else if (stateHandle instanceof KeyGroupsStateHandle) {
331:             KeyGroupsStateHandle keyGroupsStateHandle = (KeyGroupsStateHandle) stateHandle;
332: 
333:             if (stateHandle instanceof KeyGroupsSavepointStateHandle) {
334:                 dos.writeByte(SAVEPOINT_KEY_GROUPS_HANDLE);
335:             } else {
336:                 dos.writeByte(KEY_GROUPS_HANDLE_V2);
337:             }
338:             dos.writeInt(keyGroupsStateHandle.getKeyGroupRange().getStartKeyGroup());
339:             dos.writeInt(keyGroupsStateHandle.getKeyGroupRange().getNumberOfKeyGroups());
340:             for (int keyGroup : keyGroupsStateHandle.getKeyGroupRange()) {
341:                 dos.writeLong(keyGroupsStateHandle.getOffsetForKeyGroup(keyGroup));
342:             }
343:             serializeStreamStateHandle(keyGroupsStateHandle.getDelegateStateHandle(), dos);
344: 
345:             // savepoint state handle would not need to persist state handle id out.
346:             if (!(stateHandle instanceof KeyGroupsSavepointStateHandle)) {
347:                 writeStateHandleId(stateHandle, dos);
348:             }
349:         } else if (stateHandle instanceof IncrementalRemoteKeyedStateHandle) {
350:             IncrementalRemoteKeyedStateHandle incrementalKeyedStateHandle =
351:                     (IncrementalRemoteKeyedStateHandle) stateHandle;
352: 
353:             dos.writeByte(INCREMENTAL_KEY_GROUPS_HANDLE_V2);
354: 
355:             dos.writeLong(incrementalKeyedStateHandle.getCheckpointId());
356:             dos.writeUTF(String.valueOf(incrementalKeyedStateHandle.getBackendIdentifier()));
357:             dos.writeInt(incrementalKeyedStateHandle.getKeyGroupRange().getStartKeyGroup());
358:             dos.writeInt(incrementalKeyedStateHandle.getKeyGroupRange().getNumberOfKeyGroups());
359:             dos.writeLong(incrementalKeyedStateHandle.getCheckpointedSize());
360: 
361:             serializeStreamStateHandle(incrementalKeyedStateHandle.getMetaDataStateHandle(), dos);
362: 
363:             serializeHandleAndLocalPathList(incrementalKeyedStateHandle.getSharedState(), dos);
364:             serializeHandleAndLocalPathList(incrementalKeyedStateHandle.getPrivateState(), dos);
365: 
366:             writeStateHandleId(incrementalKeyedStateHandle, dos);
367:         } else if (stateHandle instanceof ChangelogStateBackendHandle) {
368:             ChangelogStateBackendHandle handle = (ChangelogStateBackendHandle) stateHandle;
369: 
370:             dos.writeByte(CHANGELOG_HANDLE_V2);
371:             dos.writeInt(handle.getKeyGroupRange().getStartKeyGroup());
372:             dos.writeInt(handle.getKeyGroupRange().getNumberOfKeyGroups());
373: 
374:             dos.writeLong(handle.getCheckpointedSize());
375: 
376:             dos.writeInt(handle.getMaterializedStateHandles().size());
377:             for (KeyedStateHandle keyedStateHandle : handle.getMaterializedStateHandles()) {
378:                 serializeKeyedStateHandle(keyedStateHandle, dos);
379:             }
380: 
381:             dos.writeInt(handle.getNonMaterializedStateHandles().size());
382:             for (KeyedStateHandle k : handle.getNonMaterializedStateHandles()) {
383:                 serializeKeyedStateHandle(k, dos);
384:             }
385: 
386:             dos.writeLong(handle.getMaterializationID());
387:             dos.writeLong(handle.getCheckpointId());
388:             writeStateHandleId(handle, dos);
389: 
390:         } else if (stateHandle instanceof InMemoryChangelogStateHandle) {
391:             InMemoryChangelogStateHandle handle = (InMemoryChangelogStateHandle) stateHandle;
392:             dos.writeByte(CHANGELOG_BYTE_INCREMENT_HANDLE);
393:             dos.writeInt(handle.getKeyGroupRange().getStartKeyGroup());
394:             dos.writeInt(handle.getKeyGroupRange().getNumberOfKeyGroups());
395:             dos.writeLong(handle.getFrom());
396:             dos.writeLong(handle.getTo());
397:             dos.writeInt(handle.getChanges().size());
398:             for (StateChange change : handle.getChanges()) {
399:                 dos.writeInt(change.getKeyGroup());
400:                 dos.writeInt(change.getChange().length);
401:                 dos.write(change.getChange());
402:             }
403:             writeStateHandleId(handle, dos);
404:         } else if (stateHandle instanceof ChangelogStateHandleStreamImpl) {
405:             ChangelogStateHandleStreamImpl handle = (ChangelogStateHandleStreamImpl) stateHandle;
406:             dos.writeByte(CHANGELOG_FILE_INCREMENT_HANDLE_V2);
407:             dos.writeInt(handle.getKeyGroupRange().getStartKeyGroup());
408:             dos.writeInt(handle.getKeyGroupRange().getNumberOfKeyGroups());
409:             dos.writeInt(handle.getHandlesAndOffsets().size());
410:             for (Tuple2<StreamStateHandle, Long> streamHandleAndOffset :
411:                     handle.getHandlesAndOffsets()) {
412:                 dos.writeLong(streamHandleAndOffset.f1);
413:                 serializeStreamStateHandle(streamHandleAndOffset.f0, dos);
414:             }
415:             dos.writeLong(handle.getStateSize());
416:             dos.writeLong(handle.getCheckpointedSize());
417:             writeStateHandleId(handle, dos);
418:             dos.writeUTF(handle.getStorageIdentifier());
419:         } else {
420:             throw new IllegalStateException(
421:                     "Unknown KeyedStateHandle type: " + stateHandle.getClass());
422:         }
423:     }
424: 
425:     private static void writeStateHandleId(KeyedStateHandle keyedStateHandle, DataOutputStream dos)
426:             throws IOException {
427:         dos.writeUTF(keyedStateHandle.getStateHandleId().getKeyString());
428:     }
429: 
430:     @VisibleForTesting
431:     @Nullable
432:     static KeyedStateHandle deserializeKeyedStateHandle(
433:             DataInputStream dis, @Nullable DeserializationContext context) throws IOException {
434: 
435:         final int type = dis.readByte();
436:         if (NULL_HANDLE == type) {
437: 
438:             return null;
439:         } else if (KEY_GROUPS_HANDLE == type
440:                 || KEY_GROUPS_HANDLE_V2 == type
441:                 || SAVEPOINT_KEY_GROUPS_HANDLE == type) {
442:             int startKeyGroup = dis.readInt();
443:             int numKeyGroups = dis.readInt();
444:             KeyGroupRange keyGroupRange =
445:                     KeyGroupRange.of(startKeyGroup, startKeyGroup + numKeyGroups - 1);
446:             long[] offsets = new long[numKeyGroups];
447:             for (int i = 0; i < numKeyGroups; ++i) {
448:                 offsets[i] = dis.readLong();
449:             }
450:             KeyGroupRangeOffsets keyGroupRangeOffsets =
451:                     new KeyGroupRangeOffsets(keyGroupRange, offsets);
452:             StreamStateHandle stateHandle = deserializeStreamStateHandle(dis, context);
453:             if (SAVEPOINT_KEY_GROUPS_HANDLE == type) {
454:                 return new KeyGroupsSavepointStateHandle(keyGroupRangeOffsets, stateHandle);
455:             } else {
456:                 StateHandleID stateHandleID =
457:                         KEY_GROUPS_HANDLE_V2 == type
458:                                 ? new StateHandleID(dis.readUTF())
459:                                 : StateHandleID.randomStateHandleId();
460:                 return KeyGroupsStateHandle.restore(
461:                         keyGroupRangeOffsets, stateHandle, stateHandleID);
462:             }
463:         } else if (INCREMENTAL_KEY_GROUPS_HANDLE == type
464:                 || INCREMENTAL_KEY_GROUPS_HANDLE_V2 == type) {
465:             return deserializeIncrementalStateHandle(dis, context, type);
466:         } else if (CHANGELOG_HANDLE == type || CHANGELOG_HANDLE_V2 == type) {
467: 
468:             int startKeyGroup = dis.readInt();
469:             int numKeyGroups = dis.readInt();
470:             KeyGroupRange keyGroupRange =
471:                     KeyGroupRange.of(startKeyGroup, startKeyGroup + numKeyGroups - 1);
472:             long checkpointedSize = dis.readLong();
473: 
474:             int baseSize = dis.readInt();
475:             List<KeyedStateHandle> base = new ArrayList<>(baseSize);
476:             for (int i = 0; i < baseSize; i++) {
477:                 KeyedStateHandle handle = deserializeKeyedStateHandle(dis, context);
478:                 if (handle != null) {
479:                     base.add(handle);
480:                 } else {
481:                     LOG.warn(
482:                             "Unexpected null keyed state handle of materialized part when deserializing changelog state-backend handle");
483:                 }
484:             }
485:             int deltaSize = dis.readInt();
486:             List<ChangelogStateHandle> delta = new ArrayList<>(deltaSize);
487:             for (int i = 0; i < deltaSize; i++) {
488:                 delta.add((ChangelogStateHandle) deserializeKeyedStateHandle(dis, context));
489:             }
490: 
491:             long materializationID = dis.readLong();
492:             long checkpointId = CHANGELOG_HANDLE_V2 == type ? dis.readLong() : materializationID;
493:             StateHandleID stateHandleId = new StateHandleID(dis.readUTF());
494:             return ChangelogStateBackendHandleImpl.restore(
495:                     base,
496:                     delta,
497:                     keyGroupRange,
498:                     checkpointId,
499:                     materializationID,
500:                     checkpointedSize,
501:                     stateHandleId);
502: 
503:         } else if (CHANGELOG_BYTE_INCREMENT_HANDLE == type) {
504:             int start = dis.readInt();
505:             int numKeyGroups = dis.readInt();
506:             KeyGroupRange keyGroupRange = KeyGroupRange.of(start, start + numKeyGroups - 1);
507:             long from = dis.readLong();
508:             long to = dis.readLong();
509:             int size = dis.readInt();
510:             List<StateChange> changes = new ArrayList<>(size);
511:             for (int i = 0; i < size; i++) {
512:                 int keyGroup = dis.readInt();
513:                 int bytesSize = dis.readInt();
514:                 byte[] bytes = new byte[bytesSize];
515:                 IOUtils.readFully(dis, bytes, 0, bytesSize);
516:                 StateChange stateChange =
517:                         keyGroup == META_KEY_GROUP
518:                                 ? StateChange.ofMetadataChange(bytes)
519:                                 : StateChange.ofDataChange(keyGroup, bytes);
520:                 changes.add(stateChange);
521:             }
522:             StateHandleID stateHandleId = new StateHandleID(dis.readUTF());
523:             return InMemoryChangelogStateHandle.restore(
524:                     changes,
525:                     SequenceNumber.of(from),
526:                     SequenceNumber.of(to),
527:                     keyGroupRange,
528:                     stateHandleId);
529: 
530:         } else if (CHANGELOG_FILE_INCREMENT_HANDLE == type
531:                 || CHANGELOG_FILE_INCREMENT_HANDLE_V2 == type) {
532:             int start = dis.readInt();
533:             int numKeyGroups = dis.readInt();
534:             KeyGroupRange keyGroupRange = KeyGroupRange.of(start, start + numKeyGroups - 1);
535:             int numHandles = dis.readInt();
536:             List<Tuple2<StreamStateHandle, Long>> streamHandleAndOffset =
537:                     new ArrayList<>(numHandles);
538:             for (int i = 0; i < numHandles; i++) {
539:                 long o = dis.readLong();
540:                 StreamStateHandle h = deserializeStreamStateHandle(dis, context);
541:                 streamHandleAndOffset.add(Tuple2.of(h, o));
542:             }
543:             long size = dis.readLong();
544:             long checkpointedSize = dis.readLong();
545:             StateHandleID stateHandleId = new StateHandleID(dis.readUTF());
546:             String storageIdentifier =
547:                     CHANGELOG_FILE_INCREMENT_HANDLE_V2 == type ? dis.readUTF() : "filesystem";
548:             return ChangelogStateHandleStreamImpl.restore(
549:                     streamHandleAndOffset,
550:                     keyGroupRange,
551:                     size,
552:                     checkpointedSize,
553:                     storageIdentifier,
554:                     stateHandleId);
555:         } else {
556:             throw new IllegalStateException("Reading invalid KeyedStateHandle, type: " + type);
557:         }
558:     }
559: 
560:     private static IncrementalRemoteKeyedStateHandle deserializeIncrementalStateHandle(
561:             DataInputStream dis, @Nullable DeserializationContext context, int stateHandleType)
562:             throws IOException {
563:         boolean isV2Format = INCREMENTAL_KEY_GROUPS_HANDLE_V2 == stateHandleType;
564:         long checkpointId = dis.readLong();
565:         String backendId = dis.readUTF();
566:         int startKeyGroup = dis.readInt();
567:         int numKeyGroups = dis.readInt();
568:         long checkpointedSize = isV2Format ? dis.readLong() : UNKNOWN_CHECKPOINTED_SIZE;
569: 
570:         KeyGroupRange keyGroupRange =
571:                 KeyGroupRange.of(startKeyGroup, startKeyGroup + numKeyGroups - 1);
572: 
573:         StreamStateHandle metaDataStateHandle = deserializeStreamStateHandle(dis, context);
574:         List<HandleAndLocalPath> sharedStates = deserializeHandleAndLocalPathList(dis, context);
575:         List<HandleAndLocalPath> privateStates = deserializeHandleAndLocalPathList(dis, context);
576: 
577:         UUID uuid;
578: 
579:         try {
580:             uuid = UUID.fromString(backendId);
581:         } catch (Exception ex) {
582:             // compatibility with old format pre FLINK-6964:
583:             uuid = UUID.nameUUIDFromBytes(backendId.getBytes(StandardCharsets.UTF_8));
584:         }
585: 
586:         StateHandleID stateHandleId =
587:                 isV2Format ? new StateHandleID(dis.readUTF()) : StateHandleID.randomStateHandleId();
588:         return IncrementalRemoteKeyedStateHandle.restore(
589:                 uuid,
590:                 keyGroupRange,
591:                 checkpointId,
592:                 sharedStates,
593:                 privateStates,
594:                 metaDataStateHandle,
595:                 checkpointedSize,
596:                 stateHandleId);
597:     }
