771:     @Nullable
772:     static StreamStateHandle deserializeStreamStateHandle(
773:             DataInputStream dis, @Nullable DeserializationContext context) throws IOException {
774: 
775:         final int type = dis.read();
776:         if (NULL_HANDLE == type) {
777:             return null;
778:         } else if (FILE_STREAM_STATE_HANDLE == type) {
779:             long size = dis.readLong();
780:             String pathString = dis.readUTF();
781:             return new FileStateHandle(new Path(pathString), size);
782:         } else if (BYTE_STREAM_STATE_HANDLE == type) {
783:             String handleName = dis.readUTF();
784:             int numBytes = dis.readInt();
785:             byte[] data = new byte[numBytes];
786:             dis.readFully(data);
787:             return new ByteStreamStateHandle(handleName, data);
788:         } else if (RELATIVE_STREAM_STATE_HANDLE == type) {
789:             if (context == null) {
790:                 throw new IOException(
791:                         "Cannot deserialize a RelativeFileStateHandle without a context to make it relative to.");
792:             }
793:             String relativePath = dis.readUTF();
794:             long size = dis.readLong();
795:             Path statePath = new Path(context.getExclusiveDirPath(), relativePath);
796:             return new RelativeFileStateHandle(statePath, relativePath, size);
797:         } else if (KEY_GROUPS_HANDLE == type) {
798: 
799:             int startKeyGroup = dis.readInt();
800:             int numKeyGroups = dis.readInt();
801:             KeyGroupRange keyGroupRange =
802:                     KeyGroupRange.of(startKeyGroup, startKeyGroup + numKeyGroups - 1);
803:             long[] offsets = new long[numKeyGroups];
804:             for (int i = 0; i < numKeyGroups; ++i) {
805:                 offsets[i] = dis.readLong();
806:             }
807:             KeyGroupRangeOffsets keyGroupRangeOffsets =
808:                     new KeyGroupRangeOffsets(keyGroupRange, offsets);
809:             StreamStateHandle stateHandle = deserializeStreamStateHandle(dis, context);
810:             return new KeyGroupsStateHandle(keyGroupRangeOffsets, stateHandle);
811:         } else if (SEGMENT_FILE_HANDLE == type) {
812:             long startPos = dis.readLong();
813:             long stateSize = dis.readLong();
814:             CheckpointedStateScope scope = CheckpointedStateScope.values()[dis.readInt()];
815:             Path physicalFilePath = new Path(dis.readUTF());
816:             LogicalFile.LogicalFileId logicalFileId = new LogicalFile.LogicalFileId(dis.readUTF());
817:             return new SegmentFileStateHandle(
818:                     physicalFilePath, startPos, stateSize, scope, logicalFileId);
819:         } else if (EMPTY_SEGMENT_FILE_HANDLE == type) {
820:             return EmptySegmentFileStateHandle.INSTANCE;
821:         } else {
822:             throw new IOException("Unknown implementation of StreamStateHandle, code: " + type);
823:         }
824:     }
