875:             throws IOException {
876: 
877:         int size = dis.readInt();
878:         List<T> result = new ArrayList<>();
879:         for (int i = 0; i < size; i++) {
880:             result.add(s.apply(dis, context));
881:         }
882:         return new StateObjectCollection<>(result);
