129:     private static final byte KEY_GROUPS_HANDLE_V2 = 12;
130:     // CHANGELOG_FILE_INCREMENT_HANDLE_V2 is introduced to add new field of storageIdentifier.
131:     private static final byte CHANGELOG_FILE_INCREMENT_HANDLE_V2 = 13;
132:     // CHANGELOG_HANDLE_V2 is introduced to add new field of checkpointId.
133:     private static final byte CHANGELOG_HANDLE_V2 = 14;
134: 
135:     // SEGMENT_FILE_HANDLE is introduced to support file merging.
136:     private static final byte SEGMENT_FILE_HANDLE = 15;
137: 
138:     // EMPTY_SEGMENT_FILE_HANDLE is introduced as a placeholder for file merging.
139:     private static final byte EMPTY_SEGMENT_FILE_HANDLE = 16;
140: 
141:     // SEGMENT_PARTITIONABLE_OPERATOR_STATE_HANDLE is introduced for file merging of operator state.
142:     private static final byte SEGMENT_PARTITIONABLE_OPERATOR_STATE_HANDLE = 17;
