560:     private static IncrementalRemoteKeyedStateHandle deserializeIncrementalStateHandle(
561:             DataInputStream dis, @Nullable DeserializationContext context, int stateHandleType)
562:             throws IOException {
563:         boolean isV2Format = INCREMENTAL_KEY_GROUPS_HANDLE_V2 == stateHandleType;
564:         long checkpointId = dis.readLong();
565:         String backendId = dis.readUTF();
566:         int startKeyGroup = dis.readInt();
567:         int numKeyGroups = dis.readInt();
568:         long checkpointedSize = isV2Format ? dis.readLong() : UNKNOWN_CHECKPOINTED_SIZE;
569: 
570:         KeyGroupRange keyGroupRange =
571:                 KeyGroupRange.of(startKeyGroup, startKeyGroup + numKeyGroups - 1);
572: 
573:         StreamStateHandle metaDataStateHandle = deserializeStreamStateHandle(dis, context);
574:         List<HandleAndLocalPath> sharedStates = deserializeHandleAndLocalPathList(dis, context);
575:         List<HandleAndLocalPath> privateStates = deserializeHandleAndLocalPathList(dis, context);
576: 
577:         UUID uuid;
578: 
579:         try {
580:             uuid = UUID.fromString(backendId);
581:         } catch (Exception ex) {
582:             // compatibility with old format pre FLINK-6964:
583:             uuid = UUID.nameUUIDFromBytes(backendId.getBytes(StandardCharsets.UTF_8));
584:         }
585: 
586:         StateHandleID stateHandleId =
587:                 isV2Format ? new StateHandleID(dis.readUTF()) : StateHandleID.randomStateHandleId();
588:         return IncrementalRemoteKeyedStateHandle.restore(
589:                 uuid,
590:                 keyGroupRange,
591:                 checkpointId,
592:                 sharedStates,
593:                 privateStates,
594:                 metaDataStateHandle,
595:                 checkpointedSize,
596:                 stateHandleId);
597:     }
