211:     protected void serializeMasterState(MasterState state, DataOutputStream dos)
212:             throws IOException {
213:         // magic number for error detection
214:         dos.writeInt(MASTER_STATE_MAGIC_NUMBER);
215: 
216:         // for safety, we serialize first into an array and then write the array and its
217:         // length into the checkpoint
218:         final ByteArrayOutputStream baos = new ByteArrayOutputStream();
219:         final DataOutputStream out = new DataOutputStream(baos);
220: 
221:         out.writeInt(state.version());
222:         out.writeUTF(state.name());
223: 
224:         final byte[] bytes = state.bytes();
225:         out.writeInt(bytes.length);
226:         out.write(bytes, 0, bytes.length);
227: 
228:         out.close();
229:         byte[] data = baos.toByteArray();
230: 
231:         dos.writeInt(data.length);
232:         dos.write(data, 0, data.length);
