38: /** State which describes a job which is currently being restarted. */
39: class Restarting extends StateWithExecutionGraph {
40: 
41:     private final Context context;
42: 
43:     private final Duration backoffTime;
44: 
45:     @Nullable private ScheduledFuture<?> goToSubsequentStateFuture;
46: 
47:     private final boolean forcedRestart;
48: 
49:     Restarting(
50:             Context context,
51:             ExecutionGraph executionGraph,
52:             ExecutionGraphHandler executionGraphHandler,
53:             OperatorCoordinatorHandler operatorCoordinatorHandler,
54:             Logger logger,
55:             Duration backoffTime,
56:             boolean forcedRestart,
57:             ClassLoader userCodeClassLoader,
58:             List<ExceptionHistoryEntry> failureCollection) {
59:         super(
60:                 context,
61:                 executionGraph,
62:                 executionGraphHandler,
63:                 operatorCoordinatorHandler,
64:                 logger,
65:                 userCodeClassLoader,
66:                 failureCollection);
67:         this.context = context;
68:         this.backoffTime = backoffTime;
69:         this.forcedRestart = forcedRestart;
70: 
71:         getExecutionGraph().cancel();
72:     }
73: 
74:     @Override
75:     public void onLeave(Class<? extends State> newState) {
76:         if (goToSubsequentStateFuture != null) {
77:             goToSubsequentStateFuture.cancel(false);
78:         }
79: 
80:         super.onLeave(newState);
81:     }
82: 
83:     @Override
84:     public JobStatus getJobStatus() {
85:         return JobStatus.RESTARTING;
86:     }
87: 
88:     @Override
89:     public void suspend(Throwable cause) {
90:         suspend(cause, JobStatus.SUSPENDED);
91:     }
92: 
93:     @Override
94:     public void cancel() {
95:         context.goToCanceling(
96:                 getExecutionGraph(),
97:                 getExecutionGraphHandler(),
98:                 getOperatorCoordinatorHandler(),
99:                 getFailures());
100:     }
101: 
102:     @Override
103:     void onFailure(Throwable failure, CompletableFuture<Map<String, String>> failureLabels) {
104:         // We've already cancelled the execution graph, so there is noting else we can do.
105:     }
106: 
107:     @Override
108:     void onGloballyTerminalState(JobStatus globallyTerminalState) {
109:         Preconditions.checkArgument(globallyTerminalState == JobStatus.CANCELED);
110:         goToSubsequentStateFuture =
111:                 context.runIfState(this, this::goToSubsequentState, backoffTime);
112:     }
113: 
114:     private void goToSubsequentState() {
115:         if (forcedRestart) {
116:             context.goToCreatingExecutionGraph(getExecutionGraph());
117:         } else {
118:             context.goToWaitingForResources(getExecutionGraph());
119:         }
120:     }
