122:     /** Context of the {@link Restarting} state. */
123:     interface Context
124:             extends StateWithExecutionGraph.Context,
125:                     StateTransitions.ToCancelling,
126:                     StateTransitions.ToWaitingForResources,
127:                     StateTransitions.ToCreatingExecutionGraph {
128: 
129:         /**
