88:             return -1;
89:         }
90:         // if dst already exist, not allow
91:         if (mappingTable.containsKey(dst)) {
92:             return -1;
93:         }
94:         MappingEntry sourceEntry = mappingTable.get(src);
95:         Preconditions.checkNotNull(sourceEntry);
96:         sourceEntry.retain();
97:         mappingTable.putIfAbsent(dst, sourceEntry);
98:         LOG.trace("link: {} -> {}", dst, src);
