135:         MappingEntry srcEntry = mappingTable.get(src);
136:         if (srcEntry != null) { // rename file
137:             if (mappingTable.containsKey(dst)) {
138:                 MappingEntry dstEntry = mappingTable.remove(dst);
139:                 dstEntry.release();
