146:             List<String> toRename = listByPrefix(src);
147:             for (String key : toRename) {
148:                 MappingEntry sourceEntry = mappingTable.get(key);
149:                 sourceEntry.retain();
150:                 String renamedDst = key.replace(src, dst);
151:                 LOG.trace("rename: {} -> {}", key, renamedDst);
