170:      * @param recursive whether to delete recursively
171:      * @return true if the file or directory is deleted successfully, false otherwise.
172:      * @throws IOException if an error occurs during deletion
173:      */
174:     public boolean deleteFile(Path file, boolean recursive) throws IOException {
175:         String fileStr = file.toString();
176:         MappingEntry entry = mappingTable.getOrDefault(fileStr, null);
177:         LOG.trace("delete: {}, source:{}", file, entry == null ? "null" : entry.sourcePath);
178:         // case 1: delete file
179:         if (entry != null) {
180:             mappingTable.remove(fileStr);
181:             entry.release();
182:             return true;
183:         }
184: 
185:         // case 2: delete directory
186:         if (!recursive) {
