190: 
191:         // step 2.1: find all matched entries, mark delete dir as parent dir
192:         for (Map.Entry<String, MappingEntry> currentEntry : mappingTable.entrySet()) {
193:             if (!isParentDir(currentEntry.getValue().sourcePath, fileStr)) {
194:                 continue;
