517:      * sink cases) when generating job graph.
518:      */
519:     @Test
520:     void testResourcesForChainedSourceSink() throws Exception {
521:         ResourceSpec resource1 = ResourceSpec.newBuilder(0.1, 100).build();
522:         ResourceSpec resource2 = ResourceSpec.newBuilder(0.2, 200).build();
523:         ResourceSpec resource3 = ResourceSpec.newBuilder(0.3, 300).build();
524:         ResourceSpec resource4 = ResourceSpec.newBuilder(0.4, 400).build();
525:         ResourceSpec resource5 = ResourceSpec.newBuilder(0.5, 500).build();
526: 
527:         Method opMethod = getSetResourcesMethodAndSetAccessible(SingleOutputStreamOperator.class);
528:         Method sinkMethod = getSetResourcesMethodAndSetAccessible(DataStreamSink.class);
529: 
530:         StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();
531: 
532:         DataStream<Tuple2<Integer, Integer>> source =
533:                 env.addSource(
534:                         new ParallelSourceFunction<Tuple2<Integer, Integer>>() {
535:                             @Override
536:                             public void run(SourceContext<Tuple2<Integer, Integer>> ctx)
537:                                     throws Exception {}
538: 
539:                             @Override
540:                             public void cancel() {}
541:                         });
542:         opMethod.invoke(source, resource1);
543: 
544:         DataStream<Tuple2<Integer, Integer>> map =
545:                 source.map(
546:                         new MapFunction<Tuple2<Integer, Integer>, Tuple2<Integer, Integer>>() {
547:                             @Override
548:                             public Tuple2<Integer, Integer> map(Tuple2<Integer, Integer> value)
549:                                     throws Exception {
550:                                 return value;
551:                             }
552:                         });
553:         opMethod.invoke(map, resource2);
554: 
555:         // CHAIN(Source -> Map -> Filter)
556:         DataStream<Tuple2<Integer, Integer>> filter =
557:                 map.filter(
558:                         new FilterFunction<Tuple2<Integer, Integer>>() {
559:                             @Override
560:                             public boolean filter(Tuple2<Integer, Integer> value) throws Exception {
561:                                 return false;
562:                             }
563:                         });
564:         opMethod.invoke(filter, resource3);
565: 
566:         DataStream<Tuple2<Integer, Integer>> reduce =
567:                 filter.keyBy(x -> x.f0)
568:                         .reduce(
569:                                 new ReduceFunction<Tuple2<Integer, Integer>>() {
570:                                     @Override
571:                                     public Tuple2<Integer, Integer> reduce(
572:                                             Tuple2<Integer, Integer> value1,
573:                                             Tuple2<Integer, Integer> value2)
574:                                             throws Exception {
575:                                         return new Tuple2<>(value1.f0, value1.f1 + value2.f1);
576:                                     }
577:                                 });
578:         opMethod.invoke(reduce, resource4);
579: 
580:         DataStreamSink<Tuple2<Integer, Integer>> sink =
581:                 reduce.addSink(
582:                         new SinkFunction<Tuple2<Integer, Integer>>() {
583:                             @Override
584:                             public void invoke(Tuple2<Integer, Integer> value) throws Exception {}
585:                         });
586:         sinkMethod.invoke(sink, resource5);
587: 
588:         JobGraph jobGraph = createJobGraph(env.getStreamGraph());
589: 
590:         JobVertex sourceMapFilterVertex =
591:                 jobGraph.getVerticesSortedTopologicallyFromSources().get(0);
592:         JobVertex reduceSinkVertex = jobGraph.getVerticesSortedTopologicallyFromSources().get(1);
593: 
594:         assertThat(sourceMapFilterVertex.getMinResources())
595:                 .isEqualTo(resource3.merge(resource2).merge(resource1));
