1186:     private JobGraph getUnionJobGraph(StreamExecutionEnvironment env) {
1187: 
1188:         createSource(env, 1)
1189:                 .union(createSource(env, 2))
1190:                 .union(createSource(env, 3))
1191:                 .union(createSource(env, 4))
1192:                 .sinkTo(new DiscardingSink<>());
1193: 
1194:         return createJobGraph(env.getStreamGraph());
1195:     }
