1290:     public static StreamGraph createStreamGraphForManagedMemoryFractionTest(
1291:             final List<ResourceSpec> resourceSpecs,
1292:             final List<Map<ManagedMemoryUseCase, Integer>> operatorScopeUseCaseWeights,
1293:             final List<Set<ManagedMemoryUseCase>> slotScopeUseCases)
1294:             throws Exception {
1295: 
1296:         final Method opMethod =
1297:                 getSetResourcesMethodAndSetAccessible(SingleOutputStreamOperator.class);
1298: 
1299:         final StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();
1300: 
1301:         final DataStream<Integer> source =
1302:                 env.addSource(
1303:                         new ParallelSourceFunction<Integer>() {
1304:                             @Override
1305:                             public void run(SourceContext<Integer> ctx) {}
1306: 
1307:                             @Override
1308:                             public void cancel() {}
1309:                         });
1310:         opMethod.invoke(source, resourceSpecs.get(0));
1311: 
1312:         // CHAIN(source -> map1) in default slot sharing group
1313:         final DataStream<Integer> map1 = source.map((MapFunction<Integer, Integer>) value -> value);
1314:         opMethod.invoke(map1, resourceSpecs.get(1));
1315: 
1316:         // CHAIN(map2) in default slot sharing group
1317:         final DataStream<Integer> map2 =
1318:                 map1.rebalance().map((MapFunction<Integer, Integer>) value -> value);
1319:         opMethod.invoke(map2, resourceSpecs.get(2));
1320: 
1321:         // CHAIN(map3) in test slot sharing group
1322:         final DataStream<Integer> map3 =
1323:                 map2.rebalance().map(value -> value).slotSharingGroup("test");
1324:         opMethod.invoke(map3, resourceSpecs.get(3));
1325: 
1326:         declareManagedMemoryUseCaseForTranformation(
1327:                 source.getTransformation(),
1328:                 operatorScopeUseCaseWeights.get(0),
1329:                 slotScopeUseCases.get(0));
1330:         declareManagedMemoryUseCaseForTranformation(
1331:                 map1.getTransformation(),
1332:                 operatorScopeUseCaseWeights.get(1),
1333:                 slotScopeUseCases.get(1));
1334:         declareManagedMemoryUseCaseForTranformation(
1335:                 map2.getTransformation(),
1336:                 operatorScopeUseCaseWeights.get(2),
1337:                 slotScopeUseCases.get(2));
1338:         declareManagedMemoryUseCaseForTranformation(
1339:                 map3.getTransformation(),
1340:                 operatorScopeUseCaseWeights.get(3),
1341:                 slotScopeUseCases.get(3));
1342: 
1343:         return env.getStreamGraph();
1344:     }
1345: 
1346:     private static void declareManagedMemoryUseCaseForTranformation(
1347:             Transformation<?> transformation,
1348:             Map<ManagedMemoryUseCase, Integer> operatorScopeUseCaseWeights,
1349:             Set<ManagedMemoryUseCase> slotScopeUseCases) {
1350:         for (Map.Entry<ManagedMemoryUseCase, Integer> entry :
1351:                 operatorScopeUseCaseWeights.entrySet()) {
1352:             transformation.declareManagedMemoryUseCaseAtOperatorScope(
1353:                     entry.getKey(), entry.getValue());
1354:         }
1355:         for (ManagedMemoryUseCase useCase : slotScopeUseCases) {
1356:             transformation.declareManagedMemoryUseCaseAtSlotScope(useCase);
1357:         }
1358:     }
