1616:     public JobGraph createGraphWithMultipleInputs(
1617:             boolean chain, String sinkName, String... inputNames) {
1618:         StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();
1619:         MultipleInputTransformation<Long> transform =
1620:                 new MultipleInputTransformation<>(
1621:                         "mit", new UnusedOperatorFactory(), Types.LONG, env.getParallelism());
1622:         Arrays.stream(inputNames)
1623:                 .map(
1624:                         name ->
1625:                                 env.fromSource(
1626:                                                 new NumberSequenceSource(1, 2),
1627:                                                 WatermarkStrategy.noWatermarks(),
1628:                                                 name)
1629:                                         .getTransformation())
1630:                 .forEach(transform::addInput);
1631:         transform.setChainingStrategy(
1632:                 chain ? ChainingStrategy.HEAD_WITH_SOURCES : ChainingStrategy.NEVER);
1633: 
1634:         DataStream<Long> dataStream = new DataStream<>(env, transform);
1635:         // do not chain with sink operator.
1636:         dataStream.rebalance().sinkTo(new DiscardingSink<>()).name(sinkName);
1637: 
1638:         env.addOperator(transform);
1639: 
1640:         return createJobGraph(env.getStreamGraph());
1641:     }
