1941:         source.broadcast().sinkTo(new DiscardingSink<>()).setParallelism(2);
1942: 
1943:         // these two vertices can not reuse the same intermediate dataset because of the pipelined
1944:         // edge
1945:         source.forward().sinkTo(new DiscardingSink<>()).setParallelism(1).disableChaining();
1946:         source.forward().sinkTo(new DiscardingSink<>()).setParallelism(1).disableChaining();
1947: 
1948:         DataStream<Integer> mapStream = source.forward().map(value -> value).setParallelism(1);
1949: 
