211:         if (scheduler != null) {
212:             final CompletableFuture<Void> closeFuture = new CompletableFuture<>();
213:             executor.execute(
214:                     () -> {
215:                         try {
216:                             scheduler.cancel();
217: 
218:                             FutureUtils.forward(scheduler.closeAsync(), closeFuture);
219:                         } catch (Throwable t) {
220:                             closeFuture.completeExceptionally(t);
221:                         }
222:                     });
223: 
224:             // we have to wait for the job termination outside the main thread because the
225:             // cancellation tasks are scheduled on the main thread as well.
226:             scheduler
227:                     .getJobTerminationFuture()
228:                     .whenCompleteAsync(
229:                             (jobStatus, error) -> {
230:                                 assertThat(scheduler.getState().getClass())
231:                                         .isEqualTo(Finished.class);
232: 
233:                                 if (error != null) {
234:                                     closeFuture.completeExceptionally(error);
235:                                 } else {
236:                                     try {
237:                                         FutureUtils.forward(scheduler.closeAsync(), closeFuture);
238:                                     } catch (Throwable t) {
239:                                         closeFuture.completeExceptionally(t);
240:                                     }
241:                                 }
242:                             },
243:                             executor);
244:             assertThatFuture(closeFuture).eventuallySucceeds();
245:         }
246:     }
