1068:     void testConsistentMaxParallelism() throws Exception {
1069:         final int parallelism = 240;
1070:         final int expectedMaxParallelism =
1071:                 KeyGroupRangeAssignment.computeDefaultMaxParallelism(parallelism);
1072:         final JobVertex vertex = createNoOpVertex(parallelism);
1073:         final JobGraph jobGraph = streamingJobGraph(vertex);
1074: 
1075:         final DefaultDeclarativeSlotPool declarativeSlotPool =
1076:                 createDeclarativeSlotPool(jobGraph.getJobID(), singleThreadMainThreadExecutor);
