1080:                                 jobGraph,
1081:                                 singleThreadMainThreadExecutor,
1082:                                 EXECUTOR_RESOURCE.getExecutor())
1083:                         .setDeclarativeSlotPool(declarativeSlotPool)
1084:                         .setJobMasterConfiguration(createConfigurationWithNoTimeouts())
1085:                         .build();
1086: 
1087:         final SubmissionBufferingTaskManagerGateway taskManagerGateway =
1088:                 new SubmissionBufferingTaskManagerGateway(1 + parallelism);
1089:         taskManagerGateway.setCancelConsumer(createCancelConsumer(scheduler));
1090: 
1091:         // offer just enough resources to run at the lowest possible parallelism
1092:         singleThreadMainThreadExecutor.execute(
1093:                 () -> {
1094:                     scheduler.startScheduling();
1095:                     offerSlots(
1096:                             declarativeSlotPool,
1097:                             createSlotOffersForResourceRequirements(
1098:                                     ResourceCounter.withResource(ResourceProfile.UNKNOWN, 1)),
1099:                             taskManagerGateway);
1100:                 });
1101: 
1102:         // Wait for task to be submitted
1103:         taskManagerGateway.waitForSubmissions(1);
1104: 
1105:         ArchivedExecutionGraph executionGraph =
1106:                 getArchivedExecutionGraphForRunningJob(scheduler).get();
1107:         ArchivedExecutionJobVertex archivedVertex = executionGraph.getJobVertex(vertex.getID());
1108: 
1109:         // ensure that the parallelism was submitted based on what is available
1110:         assertThat(archivedVertex.getParallelism()).isOne();
1111:         // and that the max parallelism was submitted based on what was configured
1112:         assertThat(archivedVertex.getMaxParallelism()).isEqualTo(expectedMaxParallelism);
1113: 
1114:         // offer the resources to run at full parallelism
1115:         singleThreadMainThreadExecutor.execute(
1116:                 () -> {
1117:                     offerSlots(
1118:                             declarativeSlotPool,
1119:                             createSlotOffersForResourceRequirements(
1120:                                     ResourceCounter.withResource(
1121:                                             ResourceProfile.UNKNOWN, parallelism)),
1122:                             taskManagerGateway);
1123:                 });
1124: 
1125:         // wait for the job to be re-submitted
1126:         taskManagerGateway.waitForSubmissions(parallelism);
1127: 
1128:         ArchivedExecutionGraph resubmittedExecutionGraph =
1129:                 getArchivedExecutionGraphForRunningJob(scheduler).get();
1130:         ArchivedExecutionJobVertex resubmittedArchivedVertex =
1131:                 resubmittedExecutionGraph.getJobVertex(vertex.getID());
1132: 
1133:         // ensure that the parallelism was submitted based on what is available
1134:         assertThat(resubmittedArchivedVertex.getParallelism()).isEqualTo(parallelism);
1135:         // and that the max parallelism was submitted based on what was configured
1136:         assertThat(resubmittedArchivedVertex.getMaxParallelism()).isEqualTo(expectedMaxParallelism);
1137:     }
