1401:     private SubmissionBufferingTaskManagerGateway createSubmissionBufferingTaskManagerGateway(
1402:             int parallelism, SchedulerNG scheduler) {
1403:         SubmissionBufferingTaskManagerGateway taskManagerGateway =
1404:                 new SubmissionBufferingTaskManagerGateway(parallelism);
1405:         taskManagerGateway.setCancelConsumer(
1406:                 executionAttemptID ->
1407:                         singleThreadMainThreadExecutor.execute(
1408:                                 () ->
1409:                                         scheduler.updateTaskExecutionState(
1410:                                                 new TaskExecutionState(
1411:                                                         executionAttemptID,
1412:                                                         ExecutionState.CANCELED))));
1413:         return taskManagerGateway;
1414:     }
