1416:     private void startJobWithSlotsMatchingParallelism(
1417:             SchedulerNG scheduler,
1418:             DeclarativeSlotPool declarativeSlotPool,
1419:             TaskManagerGateway taskManagerGateway,
1420:             int parallelism) {
1421:         singleThreadMainThreadExecutor.execute(
1422:                 () -> {
1423:                     scheduler.startScheduling();
1424:                     offerSlots(
1425:                             declarativeSlotPool,
1426:                             createSlotOffersForResourceRequirements(
1427:                                     ResourceCounter.withResource(
1428:                                             ResourceProfile.UNKNOWN, parallelism)),
1429:                             taskManagerGateway);
1430:                 });
1431:     }
