1433:     private void awaitJobReachingParallelism(
1434:             SubmissionBufferingTaskManagerGateway taskManagerGateway,
1435:             SchedulerNG scheduler,
1436:             int parallelism)
1437:             throws Exception {
1438:         // Wait for all tasks to be submitted
1439:         taskManagerGateway.waitForSubmissions(parallelism);
1440: 
1441:         final ArchivedExecutionGraph executionGraph =
1442:                 CompletableFuture.supplyAsync(
1443:                                 () -> scheduler.requestJob().getArchivedExecutionGraph(),
1444:                                 singleThreadMainThreadExecutor)
1445:                         .get();
1446: 
1447:         assertThat(executionGraph.getJobVertex(JOB_VERTEX.getID()).getParallelism())
1448:                 .isEqualTo(parallelism);
1449:     }
