1460:     private static JobResourceRequirements createRequirementsWithLowerAndUpperParallelism(
1461:             int lowerParallelism, int upperParallelism) {
1462:         return new JobResourceRequirements(
1463:                 Collections.singletonMap(
1464:                         JOB_VERTEX.getID(),
1465:                         new JobVertexResourceRequirements(
1466:                                 new JobVertexResourceRequirements.Parallelism(
1467:                                         lowerParallelism, upperParallelism))));
1468:     }
