2061:     void testIdleSlotsAreReleasedAfterDownScalingTriggeredByLoweredResourceRequirements()
2062:             throws Exception {
2063:         final JobGraph jobGraph = createJobGraph();
2064:         final Duration slotIdleTimeout = Duration.ofMillis(10);
2065: 
2066:         final Configuration configuration = createConfigurationWithNoTimeouts();
2067:         configuration.set(JobManagerOptions.SLOT_IDLE_TIMEOUT, slotIdleTimeout);
2068: 
2069:         final DeclarativeSlotPool declarativeSlotPool =
2070:                 createDeclarativeSlotPool(
2071:                         jobGraph.getJobID(), singleThreadMainThreadExecutor, slotIdleTimeout);
2072:         scheduler =
2073:                 new AdaptiveSchedulerBuilder(
2074:                                 jobGraph,
2075:                                 singleThreadMainThreadExecutor,
2076:                                 EXECUTOR_RESOURCE.getExecutor())
2077:                         .setDeclarativeSlotPool(declarativeSlotPool)
2078:                         .setJobMasterConfiguration(configuration)
2079:                         .build();
2080: 
2081:         final int numInitialSlots = 4;
2082:         final int numSlotsAfterDownscaling = 2;
2083: 
2084:         final SubmissionBufferingTaskManagerGateway taskManagerGateway =
2085:                 new SubmissionBufferingTaskManagerGateway(numInitialSlots);
2086: 
2087:         taskManagerGateway.setCancelConsumer(createCancelConsumer(scheduler));
2088: 
2089:         singleThreadMainThreadExecutor.execute(
2090:                 () -> {
2091:                     scheduler.startScheduling();
2092:                     offerSlots(
2093:                             declarativeSlotPool,
2094:                             createSlotOffersForResourceRequirements(
2095:                                     ResourceCounter.withResource(
2096:                                             ResourceProfile.UNKNOWN, numInitialSlots)),
2097:                             taskManagerGateway);
2098:                 });
2099: 
2100:         // wait for all tasks to be submitted
2101:         taskManagerGateway.waitForSubmissions(numInitialSlots);
2102: 
2103:         // lower the resource requirements
2104:         singleThreadMainThreadExecutor.execute(
2105:                 () ->
2106:                         scheduler.updateJobResourceRequirements(
2107:                                 JobResourceRequirements.newBuilder()
2108:                                         .setParallelismForJobVertex(
2109:                                                 JOB_VERTEX.getID(), 1, numSlotsAfterDownscaling)
2110:                                         .build()));
2111: 
2112:         // job should be resubmitted with lower parallelism
2113:         taskManagerGateway.waitForSubmissions(numSlotsAfterDownscaling);
2114: 
2115:         // and excessive slots should be freed
2116:         taskManagerGateway.waitForFreedSlots(numInitialSlots - numSlotsAfterDownscaling);
2117: 
2118:         final CompletableFuture<JobStatus> jobStatusFuture = new CompletableFuture<>();
2119:         singleThreadMainThreadExecutor.execute(
2120:                 () -> jobStatusFuture.complete(scheduler.getState().getJobStatus()));
2121:         assertThatFuture(jobStatusFuture).eventuallySucceeds().isEqualTo(JobStatus.RUNNING);
2122: 
2123:         // make sure we haven't freed up any more slots
2124:         assertThat(taskManagerGateway.freedSlots).isEmpty();
2125:     }
