2248:     private void testCheckpointStatsEventBeingExecutedInTheMainThread(
2249:             Consumer<CheckpointStatsListener> eventCallback,
2250:             int eventRepetitions,
2251:             int triggerOnFailedCheckpointCount)
2252:             throws Exception {
2253: 
2254:         final CompletableFuture<CheckpointStatsListener> statsListenerInstantiatedFuture =
2255:                 new CompletableFuture<>();
2256:         final BlockingQueue<Integer> eventQueue = new ArrayBlockingQueue<>(1);
2257: 
2258:         scheduler =
2259:                 createSchedulerThatReachesExecutingState(
2260:                         PARALLELISM,
2261:                         triggerOnFailedCheckpointCount,
2262:                         eventQueue,
2263:                         statsListenerInstantiatedFuture);
2264: 
2265:         // start scheduling to reach Executing state
2266:         singleThreadMainThreadExecutor.execute(scheduler::startScheduling);
2267: 
2268:         final CheckpointStatsListener statsListener = statsListenerInstantiatedFuture.get();
2269:         assertThat(statsListener)
2270:                 .as("The CheckpointStatsListener should have been instantiated.")
2271:                 .isNotNull();
2272: 
2273:         // the first trigger happens in the Executing initialization - let's wait for that event
2274:         // to pass
2275:         assertThat(eventQueue.take())
2276:                 .as(
2277:                         "The first event should have been appeared during Executing state initialization and should be ignored.")
2278:                 .isEqualTo(0);
2279: 
2280:         // counting the failed checkpoints only starts on a change event
2281:         scheduler.updateJobResourceRequirements(
2282:                 JobResourceRequirements.newBuilder()
2283:                         .setParallelismForJobVertex(JOB_VERTEX.getID(), 1, PARALLELISM - 1)
2284:                         .build());
2285: 
2286:         for (int i = 0; i < eventRepetitions; i++) {
2287:             assertThatNoException()
2288:                     .as(
2289:                             "Triggering the event from outside the main thread should not have caused an error.")
2290:                     .isThrownBy(() -> eventCallback.accept(statsListener));
2291:         }
2292: 
2293:         assertThat(eventQueue.take()).as("Only one event should have been observed.").isEqualTo(1);
2294:     }
