2573:     /**
2574:      * A {@link SimpleAckingTaskManagerGateway} that buffers all the task submissions into a
2575:      * blocking queue, allowing one to wait for an arbitrary number of submissions.
2576:      */
2577:     public static class SubmissionBufferingTaskManagerGateway
2578:             extends SimpleAckingTaskManagerGateway {
2579:         final BlockingQueue<TaskDeploymentDescriptor> submittedTasks;
2580:         final BlockingQueue<AllocationID> freedSlots;
2581: 
2582:         public SubmissionBufferingTaskManagerGateway(int capacity) {
2583:             submittedTasks = new ArrayBlockingQueue<>(capacity);
2584:             freedSlots = new ArrayBlockingQueue<>(capacity);
2585:             initializeFunctions();
2586:         }
2587: 
2588:         @Override
2589:         public void setSubmitConsumer(Consumer<TaskDeploymentDescriptor> submitConsumer) {
2590:             super.setSubmitConsumer(
2591:                     taskDeploymentDescriptor -> {
2592:                         Preconditions.checkState(submittedTasks.offer(taskDeploymentDescriptor));
2593:                         submitConsumer.accept(taskDeploymentDescriptor);
2594:                     });
2595:         }
2596: 
2597:         @Override
2598:         public void setFreeSlotFunction(
2599:                 BiFunction<AllocationID, Throwable, CompletableFuture<Acknowledge>>
2600:                         freeSlotFunction) {
2601:             super.setFreeSlotFunction(
2602:                     (allocationID, throwable) -> {
2603:                         Preconditions.checkState(freedSlots.offer(allocationID));
2604:                         return freeSlotFunction.apply(allocationID, throwable);
2605:                     });
2606:         }
2607: 
2608:         /**
2609:          * Block until an arbitrary number of submissions have been received.
2610:          *
2611:          * @param numSubmissions The number of submissions to wait for
2612:          * @return the list of the waited-for submissions
2613:          * @throws InterruptedException if a timeout is exceeded waiting for a submission
2614:          */
2615:         public List<TaskDeploymentDescriptor> waitForSubmissions(int numSubmissions)
2616:                 throws InterruptedException {
2617:             List<TaskDeploymentDescriptor> descriptors = new ArrayList<>();
2618:             for (int i = 0; i < numSubmissions; i++) {
2619:                 descriptors.add(submittedTasks.take());
2620:             }
2621:             return descriptors;
2622:         }
2623: 
2624:         public List<AllocationID> waitForFreedSlots(int numFreedSlots) throws InterruptedException {
2625:             final List<AllocationID> allocationIds = new ArrayList<>();
2626:             for (int i = 0; i < numFreedSlots; i++) {
2627:                 allocationIds.add(freedSlots.take());
2628:             }
2629:             return allocationIds;
2630:         }
2631: 
2632:         private void initializeFunctions() {
2633:             setSubmitConsumer(ignored -> {});
2634:             setFreeSlotFunction(
2635:                     (allocationId, throwable) ->
2636:                             CompletableFuture.completedFuture(Acknowledge.get()));
2637:         }
2638:     }
