124: /** The StreamingJobGraphGenerator converts a {@link StreamGraph} into a {@link JobGraph}. */
125: @Internal
126: public class StreamingJobGraphGenerator {
127: 
128:     private static final Logger LOG = LoggerFactory.getLogger(StreamingJobGraphGenerator.class);
129: 
130:     // ------------------------------------------------------------------------
131: 
132:     @VisibleForTesting
133:     public static JobGraph createStreamGraph(StreamGraph streamGraph) {
134:         return new StreamingJobGraphGenerator(
135:                         Thread.currentThread().getContextClassLoader(),
136:                         streamGraph,
137:                         streamGraph.getJobID(),
138:                         Runnable::run)
139:                 .createJobGraph();
140:     }
141: 
142:     public static JobGraph createJobGraph(
143:             ClassLoader userClassLoader, StreamGraph streamGraph, @Nullable JobID jobID) {
144:         // TODO Currently, we construct a new thread pool for the compilation of each job. In the
145:         // future, we may refactor the job submission framework and make it reusable across jobs.
146:         final ExecutorService serializationExecutor =
147:                 Executors.newFixedThreadPool(
148:                         Math.max(
149:                                 1,
150:                                 Math.min(
151:                                         Hardware.getNumberCPUCores(),
152:                                         streamGraph.getExecutionConfig().getParallelism())),
153:                         new ExecutorThreadFactory("flink-operator-serialization-io"));
154:         try {
155:             return new StreamingJobGraphGenerator(
156:                             userClassLoader, streamGraph, jobID, serializationExecutor)
157:                     .createJobGraph();
158:         } finally {
159:             serializationExecutor.shutdown();
160:         }
161:     }
