164: 
165:     private final ClassLoader userClassloader;
166:     private final StreamGraph streamGraph;
167: 
168:     private final JobGraph jobGraph;
169: 
170:     private final StreamGraphHasher defaultStreamGraphHasher;
171:     private final List<StreamGraphHasher> legacyStreamGraphHashers;
172: 
173:     private final Executor serializationExecutor;
174: 
175:     // We save all the context needed to create the JobVertex in this structure.
176:     private final JobVertexBuildContext jobVertexBuildContext;
177: 
178:     private StreamingJobGraphGenerator(
179:             ClassLoader userClassloader,
180:             StreamGraph streamGraph,
181:             @Nullable JobID jobID,
182:             Executor serializationExecutor) {
183:         this.userClassloader = userClassloader;
184:         this.streamGraph = streamGraph;
185:         this.defaultStreamGraphHasher = new StreamGraphHasherV2();
186:         this.legacyStreamGraphHashers = Arrays.asList(new StreamGraphUserHashHasher());
187:         this.serializationExecutor = Preconditions.checkNotNull(serializationExecutor);
188:         jobGraph = createAndInitializeJobGraph(streamGraph, jobID);
189: 
190:         // Generate deterministic hashes for the nodes in order to identify them across
191:         // submission iff they didn't change.
192:         final Map<Integer, byte[]> hashes =
193:                 defaultStreamGraphHasher.traverseStreamGraphAndGenerateHashes(streamGraph);
194: 
195:         // Generate legacy version hashes for backwards compatibility
196:         final List<Map<Integer, byte[]>> legacyHashes =
197:                 new ArrayList<>(legacyStreamGraphHashers.size());
198:         for (StreamGraphHasher hasher : legacyStreamGraphHashers) {
199:             legacyHashes.add(hasher.traverseStreamGraphAndGenerateHashes(streamGraph));
200:         }
201: 
202:         this.jobVertexBuildContext =
203:                 new JobVertexBuildContext(
204:                         jobGraph,
205:                         streamGraph,
206:                         new AtomicBoolean(false),
207:                         hashes,
208:                         legacyHashes,
209:                         new SlotSharingGroup());
210:     }
