212:     private JobGraph createJobGraph() {
213:         preValidate(streamGraph, userClassloader);
214: 
215:         setChaining();
216: 
217:         if (jobGraph.isDynamic()) {
218:             setVertexParallelismsForDynamicGraphIfNecessary();
219:         }
220: 
221:         // Note that we set all the non-chainable outputs configuration here because the
222:         // "setVertexParallelismsForDynamicGraphIfNecessary" may affect the parallelism of job
223:         // vertices and partition-reuse
224:         final Map<Integer, Map<StreamEdge, NonChainedOutput>> opIntermediateOutputs =
225:                 new HashMap<>();
226:         setAllOperatorNonChainedOutputsConfigs(opIntermediateOutputs, jobVertexBuildContext);
227:         setAllVertexNonChainedOutputsConfigs(opIntermediateOutputs);
228: 
229:         setPhysicalEdges(jobVertexBuildContext);
230: 
231:         markSupportingConcurrentExecutionAttempts(jobVertexBuildContext);
232: 
233:         validateHybridShuffleExecuteInBatchMode(jobVertexBuildContext);
234: 
235:         setSlotSharingAndCoLocation(jobVertexBuildContext);
236: 
237:         setManagedMemoryFraction(jobVertexBuildContext);
238: 
239:         addVertexIndexPrefixInVertexName(jobVertexBuildContext, new AtomicInteger(0));
240: 
241:         setVertexDescription(jobVertexBuildContext);
242: 
243:         // Wait for the serialization of operator coordinators and stream config.
244:         serializeOperatorCoordinatorsAndStreamConfig(serializationExecutor, jobVertexBuildContext);
245: 
246:         return jobGraph;
247:     }
248: 
249:     public static void serializeOperatorCoordinatorsAndStreamConfig(
250:             Executor serializationExecutor, JobVertexBuildContext jobVertexBuildContext) {
251:         try {
252:             FutureUtils.combineAll(
253:                             jobVertexBuildContext.getChainInfosInOrder().values().stream()
254:                                     .flatMap(
255:                                             chainInfo ->
256:                                                     serializationOperatorConfigs(
257:                                                             chainInfo, serializationExecutor))
258:                                     .collect(Collectors.toList()))
259:                     .get();
260: 
261:             waitForSerializationFuturesAndUpdateJobVertices(jobVertexBuildContext);
262:         } catch (Exception e) {
263:             throw new FlinkRuntimeException("Error in serialization.", e);
264:         }
265:     }
266: 
267:     private static Stream<CompletableFuture<StreamConfig>> serializationOperatorConfigs(
268:             OperatorChainInfo chainInfo, Executor serializationExecutor) {
269:         return chainInfo.getOperatorInfos().values().stream()
270:                 .map(
271:                         operatorInfo ->
272:                                 operatorInfo
273:                                         .getVertexConfig()
274:                                         .triggerSerializationAndReturnFuture(
275:                                                 serializationExecutor));
276:     }
