282:      * @param operatorUid the unique identifier of the operator, used to generate the hash
283:      * @return a new {@link OperatorID} instance generated from the specified operator UID
284:      */
285:     public static OperatorID generateOperatorID(String operatorUid) {
286:         return new OperatorID(StreamGraphHasherV2.generateUserSpecifiedHash(operatorUid));
287:     }
