289:     private static void waitForSerializationFuturesAndUpdateJobVertices(
290:             JobVertexBuildContext jobVertexBuildContext)
291:             throws ExecutionException, InterruptedException {
292:         for (Map.Entry<
293:                         JobVertexID,
294:                         List<CompletableFuture<SerializedValue<OperatorCoordinator.Provider>>>>
295:                 futuresPerJobVertex :
296:                         jobVertexBuildContext
297:                                 .getCoordinatorSerializationFuturesPerJobVertex()
298:                                 .entrySet()) {
299:             final JobVertexID jobVertexId = futuresPerJobVertex.getKey();
300:             final JobVertex jobVertex =
301:                     jobVertexBuildContext.getJobGraph().findVertexByID(jobVertexId);
302: 
303:             Preconditions.checkState(
304:                     jobVertex != null,
305:                     "OperatorCoordinator providers were registered for JobVertexID '%s' but no corresponding JobVertex can be found.",
306:                     jobVertexId);
307:             FutureUtils.combineAll(futuresPerJobVertex.getValue())
308:                     .get()
309:                     .forEach(jobVertex::addOperatorCoordinator);
310:         }
311:     }
