339:     public static void setVertexDescription(JobVertexBuildContext jobVertexBuildContext) {
340:         final Map<Integer, JobVertex> jobVertices = jobVertexBuildContext.getJobVerticesInOrder();
341:         final StreamGraph streamGraph = jobVertexBuildContext.getStreamGraph();
342:         for (Map.Entry<Integer, JobVertex> headOpAndJobVertex : jobVertices.entrySet()) {
343:             Integer headOpId = headOpAndJobVertex.getKey();
344:             JobVertex vertex = headOpAndJobVertex.getValue();
345:             StringBuilder builder = new StringBuilder();
346:             switch (streamGraph.getVertexDescriptionMode()) {
347:                 case CASCADING:
348:                     buildCascadingDescription(builder, headOpId, headOpId, jobVertexBuildContext);
349:                     break;
350:                 case TREE:
351:                     buildTreeDescription(
352:                             builder, headOpId, headOpId, "", true, jobVertexBuildContext);
353:                     break;
354:                 default:
355:                     throw new IllegalArgumentException(
356:                             String.format(
357:                                     "Description mode %s not supported",
358:                                     streamGraph.getVertexDescriptionMode()));
359:             }
360:             vertex.setOperatorPrettyName(builder.toString());
361:         }
362:     }
363: 
364:     private static void buildCascadingDescription(
365:             StringBuilder builder,
366:             int headOpId,
367:             int currentOpId,
368:             JobVertexBuildContext jobVertexBuildContext) {
369:         StreamNode node = jobVertexBuildContext.getStreamGraph().getStreamNode(currentOpId);
370:         builder.append(getDescriptionWithChainedSourcesInfo(node, jobVertexBuildContext));
371: 
372:         LinkedList<Integer> chainedOutput =
373:                 getChainedOutputNodes(headOpId, node, jobVertexBuildContext);
374:         if (chainedOutput.isEmpty()) {
375:             return;
376:         }
377:         builder.append(" -> ");
378: 
379:         boolean multiOutput = chainedOutput.size() > 1;
380:         if (multiOutput) {
381:             builder.append("(");
382:         }
383:         while (true) {
384:             Integer outputId = chainedOutput.pollFirst();
385:             buildCascadingDescription(builder, headOpId, outputId, jobVertexBuildContext);
386:             if (chainedOutput.isEmpty()) {
387:                 break;
388:             }
389:             builder.append(" , ");
390:         }
391:         if (multiOutput) {
392:             builder.append(")");
393:         }
394:     }
395: 
396:     private static LinkedList<Integer> getChainedOutputNodes(
397:             int headOpId, StreamNode node, JobVertexBuildContext jobVertexBuildContext) {
398:         LinkedList<Integer> chainedOutput = new LinkedList<>();
399:         Map<Integer, Map<Integer, StreamConfig>> chainedConfigs =
400:                 jobVertexBuildContext.getChainedConfigs();
401:         if (chainedConfigs.containsKey(headOpId)) {
402:             for (StreamEdge edge : node.getOutEdges()) {
403:                 int targetId = edge.getTargetId();
404:                 if (chainedConfigs.get(headOpId).containsKey(targetId)) {
405:                     chainedOutput.add(targetId);
406:                 }
407:             }
408:         }
409:         return chainedOutput;
410:     }
