412:     private static void buildTreeDescription(
413:             StringBuilder builder,
414:             int headOpId,
415:             int currentOpId,
416:             String prefix,
417:             boolean isLast,
418:             JobVertexBuildContext jobVertexBuildContext) {
419:         // Replace the '-' in prefix of current node with ' ', keep ':'
420:         // HeadNode
421:         // :- Node1
422:         // :  :- Child1
423:         // :  +- Child2
424:         // +- Node2
425:         //    :- Child3
426:         //    +- Child4
427:         String currentNodePrefix = "";
428:         String childPrefix = "";
429:         if (currentOpId != headOpId) {
430:             if (isLast) {
431:                 currentNodePrefix = prefix + "+- ";
432:                 childPrefix = prefix + "   ";
433:             } else {
434:                 currentNodePrefix = prefix + ":- ";
435:                 childPrefix = prefix + ":  ";
436:             }
437:         }
438: 
439:         StreamNode node = jobVertexBuildContext.getStreamGraph().getStreamNode(currentOpId);
440:         builder.append(currentNodePrefix);
441:         builder.append(getDescriptionWithChainedSourcesInfo(node, jobVertexBuildContext));
442:         builder.append("\n");
443: 
444:         LinkedList<Integer> chainedOutput =
445:                 getChainedOutputNodes(headOpId, node, jobVertexBuildContext);
446:         while (!chainedOutput.isEmpty()) {
447:             Integer outputId = chainedOutput.pollFirst();
448:             buildTreeDescription(
449:                     builder,
450:                     headOpId,
451:                     outputId,
452:                     childPrefix,
453:                     chainedOutput.isEmpty(),
454:                     jobVertexBuildContext);
455:         }
456:     }
