458:     private static String getDescriptionWithChainedSourcesInfo(
459:             StreamNode node, JobVertexBuildContext jobVertexBuildContext) {
460: 
461:         List<StreamNode> chainedSources;
462:         final Map<Integer, Map<Integer, StreamConfig>> chainedConfigs =
463:                 jobVertexBuildContext.getChainedConfigs();
464:         final StreamGraph streamGraph = jobVertexBuildContext.getStreamGraph();
465: 
466:         if (!chainedConfigs.containsKey(node.getId())) {
467:             // node is not head operator of a vertex
468:             chainedSources = Collections.emptyList();
469:         } else {
470:             chainedSources =
471:                     node.getInEdges().stream()
472:                             .map(StreamEdge::getSourceId)
473:                             .filter(
474:                                     id ->
475:                                             streamGraph.getSourceIDs().contains(id)
476:                                                     && chainedConfigs
477:                                                             .get(node.getId())
478:                                                             .containsKey(id))
479:                             .map(streamGraph::getStreamNode)
480:                             .collect(Collectors.toList());
481:         }
482:         return chainedSources.isEmpty()
483:                 ? node.getOperatorDescription()
484:                 : String.format(
485:                         "%s [%s]",
486:                         node.getOperatorDescription(),
487:                         chainedSources.stream()
488:                                 .map(StreamNode::getOperatorDescription)
489:                                 .collect(Collectors.joining(", ")));
490:     }
