543:     public static void setPhysicalEdges(JobVertexBuildContext jobVertexBuildContext) {
544:         Map<Integer, List<StreamEdge>> physicalInEdgesInOrder =
545:                 new HashMap<Integer, List<StreamEdge>>();
546: 
547:         for (StreamEdge edge : jobVertexBuildContext.getPhysicalEdgesInOrder()) {
548:             int target = edge.getTargetId();
549: 
550:             List<StreamEdge> inEdges =
551:                     physicalInEdgesInOrder.computeIfAbsent(target, k -> new ArrayList<>());
552: 
553:             inEdges.add(edge);
554:         }
555: 
556:         for (Map.Entry<Integer, List<StreamEdge>> inEdges : physicalInEdgesInOrder.entrySet()) {
557:             int vertex = inEdges.getKey();
558:             List<StreamEdge> edgeList = inEdges.getValue();
559: 
560:             jobVertexBuildContext
561:                     .getChainInfo(vertex)
562:                     .getOperatorInfo(vertex)
563:                     .getVertexConfig()
564:                     .setInPhysicalEdges(edgeList);
565:         }
566:     }
