583:     /**
584:      * Sets up task chains from the source {@link StreamNode} instances.
585:      *
586:      * <p>This will recursively create all {@link JobVertex} instances.
587:      */
588:     private void setChaining() {
589:         // we separate out the sources that run as inputs to another operator (chained inputs)
590:         // from the sources that needs to run as the main (head) operator.
591:         final Map<Integer, OperatorChainInfo> chainEntryPoints =
592:                 buildChainedInputsAndGetHeadInputs();
593:         final Collection<OperatorChainInfo> initialEntryPoints =
594:                 chainEntryPoints.entrySet().stream()
595:                         .sorted(Comparator.comparing(Map.Entry::getKey))
596:                         .map(Map.Entry::getValue)
597:                         .collect(Collectors.toList());
598: 
599:         // iterate over a copy of the values, because this map gets concurrently modified
600:         for (OperatorChainInfo info : initialEntryPoints) {
601:             createChain(
602:                     info.getStartNodeId(),
603:                     1, // operators start at position 1 because 0 is for chained source inputs
604:                     info,
605:                     chainEntryPoints,
606:                     true,
607:                     serializationExecutor,
608:                     jobVertexBuildContext,
609:                     null);
610:         }
611:     }
612: 
613:     public static List<StreamEdge> createChain(
614:             final Integer currentNodeId,
615:             final int chainIndex,
616:             final OperatorChainInfo chainInfo,
617:             final Map<Integer, OperatorChainInfo> chainEntryPoints,
618:             final boolean canCreateNewChain,
619:             final Executor serializationExecutor,
620:             final JobVertexBuildContext jobVertexBuildContext,
621:             final @Nullable Consumer<Integer> visitedStreamNodeConsumer) {
622: 
623:         Integer startNodeId = chainInfo.getStartNodeId();
624:         if (!jobVertexBuildContext.getJobVerticesInOrder().containsKey(startNodeId)) {
625:             StreamGraph streamGraph = jobVertexBuildContext.getStreamGraph();
626: 
627:             // Adaptive graph generator needs to subscribe the visited stream node id to
628:             // generate hashes for it.
629:             if (visitedStreamNodeConsumer != null) {
630:                 visitedStreamNodeConsumer.accept(currentNodeId);
631:             }
632: 
633:             List<StreamEdge> transitiveOutEdges = new ArrayList<StreamEdge>();
634: 
635:             List<StreamEdge> chainableOutputs = new ArrayList<StreamEdge>();
636:             List<StreamEdge> nonChainableOutputs = new ArrayList<StreamEdge>();
637: 
638:             StreamNode currentNode = streamGraph.getStreamNode(currentNodeId);
639:             Attribute currentNodeAttribute = currentNode.getAttribute();
640:             boolean isNoOutputUntilEndOfInput =
641:                     currentNode.isOutputOnlyAfterEndOfStream()
642:                             || currentNodeAttribute.isNoOutputUntilEndOfInput();
643:             if (isNoOutputUntilEndOfInput) {
644:                 currentNodeAttribute.setNoOutputUntilEndOfInput(true);
645:             }
646: 
647:             for (StreamEdge outEdge : currentNode.getOutEdges()) {
648:                 if (isChainable(outEdge, streamGraph)) {
649:                     chainableOutputs.add(outEdge);
650:                 } else {
651:                     nonChainableOutputs.add(outEdge);
652:                 }
653:             }
654: 
655:             for (StreamEdge chainable : chainableOutputs) {
656:                 StreamNode targetNode = streamGraph.getStreamNode(chainable.getTargetId());
657:                 Attribute targetNodeAttribute = targetNode.getAttribute();
658:                 if (isNoOutputUntilEndOfInput) {
659:                     if (targetNodeAttribute != null) {
660:                         targetNodeAttribute.setNoOutputUntilEndOfInput(true);
661:                     }
662:                 }
663:                 transitiveOutEdges.addAll(
664:                         createChain(
665:                                 chainable.getTargetId(),
666:                                 chainIndex + 1,
667:                                 chainInfo,
668:                                 chainEntryPoints,
669:                                 canCreateNewChain,
670:                                 serializationExecutor,
671:                                 jobVertexBuildContext,
672:                                 visitedStreamNodeConsumer));
673:                 // Mark upstream nodes in the same chain as outputBlocking
674:                 if (targetNodeAttribute != null
675:                         && targetNodeAttribute.isNoOutputUntilEndOfInput()) {
676:                     currentNodeAttribute.setNoOutputUntilEndOfInput(true);
677:                 }
678:             }
679: 
680:             for (StreamEdge nonChainable : nonChainableOutputs) {
681:                 transitiveOutEdges.add(nonChainable);
682:                 // Used to control whether a new chain can be created, this value is true in the
683:                 // full graph generation algorithm and false in the progressive generation
684:                 // algorithm. In the future, this variable can be a boolean type function to adapt
685:                 // to more adaptive scenarios.
686:                 if (canCreateNewChain) {
687:                     createChain(
688:                             nonChainable.getTargetId(),
689:                             1, // operators start at position 1 because 0 is for chained source
690:                             // inputs
691:                             chainEntryPoints.computeIfAbsent(
692:                                     nonChainable.getTargetId(),
693:                                     (k) -> chainInfo.newChain(nonChainable.getTargetId())),
694:                             chainEntryPoints,
695:                             canCreateNewChain,
696:                             serializationExecutor,
697:                             jobVertexBuildContext,
698:                             visitedStreamNodeConsumer);
699:                 }
700:             }
701: 
702:             chainInfo.addChainedName(
703:                     currentNodeId,
704:                     createChainedName(
705:                             currentNodeId,
706:                             chainableOutputs,
707:                             Optional.ofNullable(chainEntryPoints.get(currentNodeId)),
708:                             chainInfo.getChainedNames(),
709:                             jobVertexBuildContext));
710: 
711:             chainInfo.addChainedMinResources(
712:                     currentNodeId,
713:                     createChainedMinResources(
714:                             currentNodeId, chainableOutputs, chainInfo, jobVertexBuildContext));
715: 
716:             chainInfo.addChainedPreferredResources(
717:                     currentNodeId,
718:                     createChainedPreferredResources(
719:                             currentNodeId, chainableOutputs, chainInfo, jobVertexBuildContext));
720: 
721:             OperatorID currentOperatorId =
722:                     chainInfo.addNodeToChain(
723:                             currentNodeId,
724:                             streamGraph.getStreamNode(currentNodeId).getOperatorName(),
725:                             jobVertexBuildContext);
726: 
727:             if (currentNode.getInputFormat() != null) {
728:                 chainInfo
729:                         .getOrCreateFormatContainer()
730:                         .addInputFormat(currentOperatorId, currentNode.getInputFormat());
731:             }
732: 
733:             if (currentNode.getOutputFormat() != null) {
734:                 chainInfo
735:                         .getOrCreateFormatContainer()
736:                         .addOutputFormat(currentOperatorId, currentNode.getOutputFormat());
737:             }
738:             OperatorInfo operatorInfo =
739:                     chainInfo.createAndGetOperatorInfo(currentNodeId, currentOperatorId);
740: 
741:             StreamConfig config;
742:             if (currentNodeId.equals(startNodeId)) {
743:                 JobVertex jobVertex = jobVertexBuildContext.getJobVertex(startNodeId);
744:                 if (jobVertex == null) {
745:                     jobVertex =
746:                             createJobVertex(
747:                                     chainInfo, serializationExecutor, jobVertexBuildContext);
748:                 }
749:                 config = new StreamConfig(jobVertex.getConfiguration());
750:             } else {
751:                 config = new StreamConfig(new Configuration());
752:             }
753: 
754:             tryConvertPartitionerForDynamicGraph(
755:                     chainableOutputs, nonChainableOutputs, jobVertexBuildContext);
756:             config.setAttribute(currentNodeAttribute);
757:             setOperatorConfig(currentNodeId, config, chainInfo, jobVertexBuildContext);
758: 
759:             setOperatorChainedOutputsConfig(config, chainableOutputs, jobVertexBuildContext);
760:             // we cache the non-chainable outputs here, and set the non-chained config later
761:             operatorInfo.addNonChainableOutputs(nonChainableOutputs);
762: 
763:             if (currentNodeId.equals(startNodeId)) {
764:                 chainInfo.setTransitiveOutEdges(transitiveOutEdges);
765:                 jobVertexBuildContext.addChainInfo(startNodeId, chainInfo);
766: 
767:                 config.setChainStart();
768:                 config.setChainIndex(chainIndex);
769:                 config.setOperatorName(streamGraph.getStreamNode(currentNodeId).getOperatorName());
770:                 config.setTransitiveChainedTaskConfigs(
771:                         jobVertexBuildContext.getChainedConfigs().get(startNodeId));
772:             } else {
773:                 config.setChainIndex(chainIndex);
774:                 StreamNode node = streamGraph.getStreamNode(currentNodeId);
775:                 config.setOperatorName(node.getOperatorName());
776:                 jobVertexBuildContext
777:                         .getOrCreateChainedConfig(startNodeId)
778:                         .put(currentNodeId, config);
779:             }
780: 
781:             config.setOperatorID(currentOperatorId);
782: 
783:             if (chainableOutputs.isEmpty()) {
784:                 config.setChainEnd();
785:             }
786:             return transitiveOutEdges;
787: 
788:         } else {
789:             return new ArrayList<>();
790:         }
791:     }
