971:     private static void checkAndReplaceReusableHybridPartitionType(
972:             NonChainedOutput reusableOutput) {
973:         if (reusableOutput.getPartitionType() == ResultPartitionType.HYBRID_SELECTIVE) {
974:             // for can be reused hybrid output, it can be optimized to always use full
975:             // spilling strategy to significantly reduce shuffle data writing cost.
976:             reusableOutput.setPartitionType(ResultPartitionType.HYBRID_FULL);
977:             LOG.info(
978:                     "{} result partition has been replaced by {} result partition to support partition reuse,"
979:                             + " which will reduce shuffle data writing cost.",
980:                     reusableOutput.getPartitionType().name(),
981:                     ResultPartitionType.HYBRID_FULL.name());
982:         }
983:     }
