1535:     public static void tryConvertPartitionerForDynamicGraph(
1536:             List<StreamEdge> chainableOutputs,
1537:             List<StreamEdge> nonChainableOutputs,
1538:             JobVertexBuildContext jobVertexBuildContext) {
1539:         StreamGraph streamGraph = jobVertexBuildContext.getStreamGraph();
1540:         for (StreamEdge edge : chainableOutputs) {
1541:             StreamPartitioner<?> partitioner = edge.getPartitioner();
1542:             if (partitioner instanceof ForwardForConsecutiveHashPartitioner
1543:                     || partitioner instanceof ForwardForUnspecifiedPartitioner) {
1544:                 checkState(
1545:                         streamGraph.isDynamic(),
1546:                         String.format(
1547:                                 "%s should only be used in dynamic graph.",
1548:                                 partitioner.getClass().getSimpleName()));
1549:                 edge.setPartitioner(new ForwardPartitioner<>());
1550:             }
1551:         }
1552:         for (StreamEdge edge : nonChainableOutputs) {
1553:             StreamPartitioner<?> partitioner = edge.getPartitioner();
1554:             if (partitioner instanceof ForwardForConsecutiveHashPartitioner) {
1555:                 checkState(
1556:                         streamGraph.isDynamic(),
1557:                         "ForwardForConsecutiveHashPartitioner should only be used in dynamic graph.");
1558:                 edge.setPartitioner(
1559:                         ((ForwardForConsecutiveHashPartitioner<?>) partitioner)
1560:                                 .getHashPartitioner());
1561:             } else if (partitioner instanceof ForwardForUnspecifiedPartitioner) {
1562:                 checkState(
1563:                         streamGraph.isDynamic(),
1564:                         "ForwardForUnspecifiedPartitioner should only be used in dynamic graph.");
1565:                 edge.setPartitioner(new RescalePartitioner<>());
1566:             }
1567:         }
1568:     }
