1764:     @VisibleForTesting
1765:     static boolean arePartitionerAndExchangeModeChainable(
1766:             StreamPartitioner<?> partitioner,
1767:             StreamExchangeMode exchangeMode,
1768:             boolean isDynamicGraph) {
1769:         if (partitioner instanceof ForwardForConsecutiveHashPartitioner) {
1770:             checkState(isDynamicGraph);
1771:             return true;
1772:         } else if ((partitioner instanceof ForwardPartitioner)
1773:                 && exchangeMode != StreamExchangeMode.BATCH) {
1774:             return true;
1775:         } else {
1776:             return false;
1777:         }
1778:     }
