2083:     private static void setManagedMemoryFractionForSlotSharingGroup(
2084:             final SlotSharingGroup slotSharingGroup,
2085:             final Map<JobVertexID, Integer> vertexHeadOperators,
2086:             final Map<JobVertexID, Set<Integer>> vertexOperators,
2087:             final JobVertexBuildContext jobVertexBuildContext) {
2088:         final StreamGraph streamGraph = jobVertexBuildContext.getStreamGraph();
2089:         final Map<Integer, Map<Integer, StreamConfig>> vertexChainedConfigs =
2090:                 jobVertexBuildContext.getChainedConfigs();
2091:         // In the progressive job graph generation algorithm, if the user specified the
2092:         // SlotSharingGroupResource or the AllVerticesInSameSlotSharingGroupByDefault is set to
2093:         // true, job vertices generated in different phase may be assigned to the same
2094:         // slotSharingGroup. Therefore, we need to filter out the job vertices that belong to the
2095:         // current phase.
2096:         final Set<JobVertexID> jobVertexIds =
2097:                 slotSharingGroup.getJobVertexIds().stream()
2098:                         .filter(vertexOperators::containsKey)
2099:                         .collect(Collectors.toSet());
2100:         final Set<Integer> groupOperatorIds =
2101:                 jobVertexIds.stream()
2102:                         .flatMap((vid) -> vertexOperators.get(vid).stream())
2103:                         .collect(Collectors.toSet());
2104: 
2105:         final Map<ManagedMemoryUseCase, Integer> groupOperatorScopeUseCaseWeights =
2106:                 groupOperatorIds.stream()
2107:                         .flatMap(
2108:                                 (oid) ->
2109:                                         streamGraph
2110:                                                 .getStreamNode(oid)
2111:                                                 .getManagedMemoryOperatorScopeUseCaseWeights()
2112:                                                 .entrySet()
2113:                                                 .stream())
2114:                         .collect(
2115:                                 Collectors.groupingBy(
2116:                                         Map.Entry::getKey,
2117:                                         Collectors.summingInt(Map.Entry::getValue)));
2118: 
2119:         final Set<ManagedMemoryUseCase> groupSlotScopeUseCases =
2120:                 groupOperatorIds.stream()
2121:                         .flatMap(
2122:                                 (oid) ->
2123:                                         streamGraph
2124:                                                 .getStreamNode(oid)
2125:                                                 .getManagedMemorySlotScopeUseCases()
2126:                                                 .stream())
2127:                         .collect(Collectors.toSet());
2128: 
2129:         for (JobVertexID jobVertexID : jobVertexIds) {
2130:             final int headOperatorNodeId = vertexHeadOperators.get(jobVertexID);
2131:             for (int operatorNodeId : vertexOperators.get(jobVertexID)) {
2132:                 final StreamConfig operatorConfig =
2133:                         jobVertexBuildContext
2134:                                 .getChainInfo(headOperatorNodeId)
2135:                                 .getOperatorInfo(operatorNodeId)
2136:                                 .getVertexConfig();
2137:                 final Map<ManagedMemoryUseCase, Integer> operatorScopeUseCaseWeights =
2138:                         streamGraph
2139:                                 .getStreamNode(operatorNodeId)
2140:                                 .getManagedMemoryOperatorScopeUseCaseWeights();
2141:                 final Set<ManagedMemoryUseCase> slotScopeUseCases =
2142:                         streamGraph
2143:                                 .getStreamNode(operatorNodeId)
2144:                                 .getManagedMemorySlotScopeUseCases();
2145:                 setManagedMemoryFractionForOperator(
2146:                         operatorScopeUseCaseWeights,
2147:                         slotScopeUseCases,
2148:                         groupOperatorScopeUseCaseWeights,
2149:                         groupSlotScopeUseCases,
2150:                         operatorConfig);
2151:             }
2152: 
2153:             // need to refresh the chained task configs because they are serialized
2154:             final StreamConfig vertexConfig =
2155:                     jobVertexBuildContext
2156:                             .getChainInfo(headOperatorNodeId)
2157:                             .getOperatorInfo(headOperatorNodeId)
2158:                             .getVertexConfig();
2159:             vertexConfig.setTransitiveChainedTaskConfigs(
2160:                     vertexChainedConfigs.get(headOperatorNodeId));
2161:         }
2162:     }
