2164:     private static void setManagedMemoryFractionForOperator(
2165:             final Map<ManagedMemoryUseCase, Integer> operatorScopeUseCaseWeights,
2166:             final Set<ManagedMemoryUseCase> slotScopeUseCases,
2167:             final Map<ManagedMemoryUseCase, Integer> groupManagedMemoryWeights,
2168:             final Set<ManagedMemoryUseCase> groupSlotScopeUseCases,
2169:             final StreamConfig operatorConfig) {
2170: 
2171:         // For each operator, make sure fractions are set for all use cases in the group, even if
2172:         // the operator does not have the use case (set the fraction to 0.0). This allows us to
2173:         // learn which use cases exist in the group from either one of the stream configs.
2174:         for (Map.Entry<ManagedMemoryUseCase, Integer> entry :
2175:                 groupManagedMemoryWeights.entrySet()) {
2176:             final ManagedMemoryUseCase useCase = entry.getKey();
2177:             final int groupWeight = entry.getValue();
2178:             final int operatorWeight = operatorScopeUseCaseWeights.getOrDefault(useCase, 0);
2179:             operatorConfig.setManagedMemoryFractionOperatorOfUseCase(
2180:                     useCase,
2181:                     operatorWeight > 0
2182:                             ? ManagedMemoryUtils.getFractionRoundedDown(operatorWeight, groupWeight)
2183:                             : 0.0);
2184:         }
2185:         for (ManagedMemoryUseCase useCase : groupSlotScopeUseCases) {
2186:             operatorConfig.setManagedMemoryFractionOperatorOfUseCase(
2187:                     useCase, slotScopeUseCases.contains(useCase) ? 1.0 : 0.0);
2188:         }
2189:     }
