168:     private void testSwitchingCompaction(
169:             String path, FileSink<Integer> originFileSink, FileSink<Integer> restoredFileSink)
170:             throws Exception {
171:         String cpPath = "file://" + tmpDir.toFile().getAbsolutePath();
172: 
173:         SharedReference<ConcurrentHashMap<Integer, Integer>> sendCountMap =
174:                 sharedObjects.add(new ConcurrentHashMap<>());
175:         JobGraph jobGraph = createJobGraph(cpPath, originFileSink, false, sendCountMap);
176:         JobGraph restoringJobGraph = createJobGraph(cpPath, restoredFileSink, true, sendCountMap);
177: 
178:         final MiniClusterConfiguration cfg =
179:                 new MiniClusterConfiguration.Builder()
180:                         .withRandomPorts()
181:                         .setNumTaskManagers(1)
182:                         .setNumSlotsPerTaskManager(4)
183:                         .build();
184: 
185:         try (MiniCluster miniCluster = new MiniCluster(cfg)) {
186:             miniCluster.start();
187:             miniCluster.submitJob(jobGraph);
188: 
189:             LATCH_MAP.get(latchId).await();
190: 
191:             String savepointPath =
192:                     miniCluster
193:                             .triggerSavepoint(
194:                                     jobGraph.getJobID(),
195:                                     tmpDir.toFile().getAbsolutePath(),
196:                                     true,
197:                                     SavepointFormatType.CANONICAL)
198:                             .get();
199: 
200:             // We wait for two successful checkpoints in sources before shutting down. This ensures
201:             // that the sink can commit its data.
202:             LATCH_MAP.put(latchId, new CountDownLatch(NUM_SOURCES * 2));
203: 
204:             restoringJobGraph.setSavepointRestoreSettings(
205:                     SavepointRestoreSettings.forPath(savepointPath, false));
206:             miniCluster.executeJobBlocking(restoringJobGraph);
207:         }
208: 
209:         checkIntegerSequenceSinkOutput(path, sendCountMap.get(), NUM_BUCKETS, NUM_SOURCES);
210:     }
