216:             SharedReference<ConcurrentHashMap<Integer, Integer>> sendCountMap) {
217:         StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();
218:         Configuration config = new Configuration();
219:         config.set(ExecutionOptions.RUNTIME_MODE, RuntimeExecutionMode.STREAMING);
220:         // disable changelog state in case it's randomly enabled, since it will fail the savepoint
221:         config.set(StateChangelogOptions.ENABLE_STATE_CHANGE_LOG, false);
222:         env.configure(config, getClass().getClassLoader());
223: 
224:         env.enableCheckpointing(100, CheckpointingMode.EXACTLY_ONCE);
225:         RestartStrategyUtils.configureNoRestartStrategy(env);
226:         CheckpointStorageUtils.configureFileSystemCheckpointStorage(env, cpPath);
227:         configureHashMapStateBackend(env);
228: 
229:         env.addSource(new CountingTestSource(latchId, NUM_RECORDS, isFinite, sendCountMap))
230:                 .setParallelism(NUM_SOURCES)
231:                 .sinkTo(fileSink)
232:                 .uid("sink")
233:                 .setParallelism(NUM_SINKS);
234: 
235:         StreamGraph streamGraph = env.getStreamGraph();
236:         return streamGraph.getJobGraph();
237:     }
