239:     private FileSink<Integer> createFileSink(
240:             String path, FileCompactStrategy compactStrategy, boolean disableCompact) {
241:         DefaultRowFormatBuilder<Integer> sinkBuilder =
242:                 FileSink.forRowFormat(new Path(path), new IntEncoder())
243:                         .withBucketAssigner(new ModuloBucketAssigner(NUM_BUCKETS))
244:                         .withRollingPolicy(new PartSizeAndCheckpointRollingPolicy<>(1024, false));
245: 
246:         if (compactStrategy != null) {
247:             sinkBuilder = sinkBuilder.enableCompact(compactStrategy, createFileCompactor());
248:         } else if (disableCompact) {
249:             sinkBuilder = sinkBuilder.disableCompact();
250:         }
251: 
252:         return sinkBuilder.build();
253:     }
