263:     private static void checkIntegerSequenceSinkOutput(
264:             String path, Map<Integer, Integer> countMap, int numBuckets, int numSources)
265:             throws Exception {
266:         assertThat(countMap).hasSize(numSources);
267: 
268:         File dir = new File(path);
269:         String[] subDirNames = dir.list();
270:         assertThat(subDirNames).isNotNull();
271: 
272:         Arrays.sort(subDirNames, Comparator.comparingInt(Integer::parseInt));
273:         assertThat(subDirNames).hasSize(numBuckets);
274:         for (int i = 0; i < numBuckets; ++i) {
275:             assertThat(subDirNames[i]).isEqualTo(Integer.toString(i));
276: 
277:             // now check its content
278:             File bucketDir = new File(path, subDirNames[i]);
279:             assertThat(bucketDir)
280:                     .isDirectory()
281:                     .as(bucketDir.getAbsolutePath() + " Should be a existing directory");
282: 
283:             Map<Integer, Integer> counts = new HashMap<>();
284:             File[] files = bucketDir.listFiles(f -> !f.getName().startsWith("."));
285:             assertThat(files).isNotNull();
286: 
287:             for (File file : files) {
288:                 assertThat(file).isFile();
289: 
290:                 try (DataInputStream dataInputStream =
291:                         new DataInputStream(new FileInputStream(file))) {
292:                     while (true) {
293:                         int value = dataInputStream.readInt();
294:                         counts.compute(value, (k, v) -> v == null ? 1 : v + 1);
295:                     }
296:                 } catch (EOFException e) {
297:                     // End the reading
298:                 }
299:             }
300: 
301:             int bucketId = i;
302:             int expectedCount =
303:                     countMap.values().stream()
304:                             .map(
305:                                     numRecords ->
306:                                             numRecords / numBuckets
307:                                                     + (bucketId < numRecords % numBuckets ? 1 : 0))
308:                             .mapToInt(num -> num)
309:                             .max()
310:                             .getAsInt();
311:             assertThat(counts).hasSize(expectedCount);
312: 
313:             List<Integer> countList = new ArrayList<>(countMap.values());
314:             Collections.sort(countList);
315:             for (int j = 0; j < countList.size(); j++) {
316:                 int rangeFrom = j == 0 ? 0 : countList.get(j - 1);
317:                 rangeFrom =
318:                         bucketId
319:                                 + (rangeFrom % numBuckets == 0
320:                                         ? rangeFrom
321:                                         : (rangeFrom + numBuckets - rangeFrom % numBuckets));
322:                 int rangeTo = countList.get(j);
323:                 for (int k = rangeFrom; k < rangeTo; k += numBuckets) {
324:                     assertThat(counts.getOrDefault(k, 0).intValue())
325:                             .as(
326:                                     "The record "
327:                                             + k
328:                                             + " should occur "
329:                                             + (numBuckets - j)
330:                                             + " times, "
331:                                             + " but only occurs "
332:                                             + counts.getOrDefault(k, 0)
333:                                             + "time")
334:                             .isEqualTo(numBuckets - j);
335:                 }
336:             }
337:         }
338:     }
