340:     private static class CountingTestSource extends RichParallelSourceFunction<Integer>
341:             implements CheckpointListener, CheckpointedFunction {
342: 
343:         private final String latchId;
344: 
345:         private final int numberOfRecords;
346: 
347:         private final boolean isFinite;
348: 
349:         private final SharedReference<ConcurrentHashMap<Integer, Integer>> sendCountMap;
350: 
351:         private ListState<Integer> nextValueState;
352: 
353:         private int nextValue;
354: 
355:         private volatile boolean isCanceled;
356: 
357:         private volatile boolean snapshottedAfterAllRecordsOutput;
358: 
359:         private volatile boolean isWaitingCheckpointComplete;
360: 
361:         public CountingTestSource(
362:                 String latchId,
363:                 int numberOfRecords,
364:                 boolean isFinite,
365:                 SharedReference<ConcurrentHashMap<Integer, Integer>> sendCountMap) {
366:             this.latchId = latchId;
367:             this.numberOfRecords = numberOfRecords;
368:             this.isFinite = isFinite;
369:             this.sendCountMap = sendCountMap;
370:         }
371: 
372:         @Override
373:         public void initializeState(FunctionInitializationContext context) throws Exception {
374:             nextValueState =
375:                     context.getOperatorStateStore()
376:                             .getListState(new ListStateDescriptor<>("nextValue", Integer.class));
377: 
378:             if (nextValueState.get() != null && nextValueState.get().iterator().hasNext()) {
379:                 nextValue = nextValueState.get().iterator().next();
380:             }
381:         }
382: 
383:         @Override
384:         public void run(SourceContext<Integer> ctx) throws Exception {
385:             // If we are not going to trigger failover or we have already triggered failover,
386:             // run until finished.
387:             sendRecordsUntil(isFinite ? (nextValue + numberOfRecords) : Integer.MAX_VALUE, ctx);
388: 
389:             // Wait the last checkpoint to commit all the pending records.
390:             isWaitingCheckpointComplete = true;
391:             CountDownLatch latch = LATCH_MAP.get(latchId);
392:             latch.await();
393:         }
394: 
395:         private void sendRecordsUntil(int targetNumber, SourceContext<Integer> ctx)
396:                 throws InterruptedException {
397:             while (!isCanceled && nextValue < targetNumber) {
398:                 synchronized (ctx.getCheckpointLock()) {
399:                     ctx.collect(nextValue++);
400:                     if (!isFinite && nextValue % 100 == 0) {
401:                         // slow down the source in case too many records are sent
402:                         Thread.sleep(1);
403:                     }
404:                 }
405:             }
406:         }
407: 
408:         @Override
409:         public void snapshotState(FunctionSnapshotContext context) throws Exception {
410:             nextValueState.update(Collections.singletonList(nextValue));
411:             sendCountMap.consumeSync(
412:                     m ->
413:                             m.put(
414:                                     getRuntimeContext().getTaskInfo().getIndexOfThisSubtask(),
415:                                     nextValue));
416: 
417:             if (isWaitingCheckpointComplete) {
418:                 snapshottedAfterAllRecordsOutput = true;
419:             }
420:         }
421: 
422:         @Override
423:         public void notifyCheckpointComplete(long checkpointId) throws Exception {
424:             if (!isFinite || (isWaitingCheckpointComplete && snapshottedAfterAllRecordsOutput)) {
425:                 CountDownLatch latch = LATCH_MAP.get(latchId);
426:                 latch.countDown();
427:             }
428:         }
429: 
430:         @Override
431:         public void cancel() {
432:             isCanceled = true;
433:         }
434:     }
435: }
