257:     private static class ThrottlingNumberSequenceSource extends NumberSequenceSource {
258:         private final int numbersPerSecond;
259: 
260:         public ThrottlingNumberSequenceSource(long from, long to, int numbersPerSecondPerReader) {
261:             super(from, to);
262:             this.numbersPerSecond = numbersPerSecondPerReader;
263:         }
264: 
265:         @Override
266:         public SourceReader<Long, NumberSequenceSplit> createReader(
267:                 SourceReaderContext readerContext) {
268:             return new ThrottlingIteratorSourceReader<>(
269:                     readerContext, new SourceRateLimiter(numbersPerSecond));
270:         }
271:     }
