273:     private static class ThrottlingIteratorSourceReader<
274:                     E, IterT extends Iterator<E>, SplitT extends IteratorSourceSplit<E, IterT>>
275:             extends IteratorSourceReader<E, IterT, SplitT> {
276:         private final SourceRateLimiter rateLimiter;
277: 
278:         public ThrottlingIteratorSourceReader(
279:                 SourceReaderContext context, SourceRateLimiter rateLimiter) {
280:             super(context);
281:             this.rateLimiter = rateLimiter;
282:         }
283: 
284:         @Override
285:         public InputStatus pollNext(ReaderOutput<E> output) {
286:             if (rateLimiter.request()) {
287:                 return super.pollNext(output);
288:             } else {
289:                 return InputStatus.NOTHING_AVAILABLE;
290:             }
291:         }
292:     }
293: 
294:     private static final class SourceRateLimiter {
295:         private final AtomicBoolean newTokensAdded = new AtomicBoolean(false);
296:         private final int tokensToAdd;
297:         private int tokensAvailable;
298: 
299:         public SourceRateLimiter(int tokensPerSecond) {
300:             this(
301:                     tokensPerSecond < 10 ? 1000 : 100,
302:                     tokensPerSecond < 10 ? tokensPerSecond : tokensPerSecond / 10);
303:         }
304: 
305:         public SourceRateLimiter(int intervalMs, int tokensToAdd) {
306:             checkArgument(intervalMs > 0);
307:             checkArgument(tokensToAdd > 0);
308:             this.tokensToAdd = tokensToAdd;
309:             this.tokensAvailable = tokensToAdd;
310:             new Timer("source-limiter", true)
311:                     .scheduleAtFixedRate(
312:                             new TimerTask() {
313:                                 @Override
314:                                 public void run() {
315:                                     newTokensAdded.set(true); // "catch up" is ok
316:                                 }
317:                             },
318:                             intervalMs,
319:                             intervalMs);
320:         }
321: 
322:         public boolean request() {
323:             if (tokensAvailable == 0 && newTokensAdded.compareAndSet(true, false)) {
324:                 tokensAvailable = tokensToAdd;
325:             }
326:             if (tokensAvailable > 0) {
327:                 tokensAvailable--;
328:                 return true;
329:             } else {
330:                 return false;
331:             }
332:         }
333:     }
