337:         cluster.getClusterClient().cancel(jobID).get();
338:         waitForSuccessfulTermination(jobID);
339:         return CommonTestUtils.getLatestCompletedCheckpointPath(jobID, cluster.getMiniCluster())
340:                 .<NoSuchElementException>orElseThrow(
341:                         () -> {
342:                             throw new NoSuchElementException("No checkpoint was created yet");
343:                         });
344:     }
