347:         CommonTestUtils.waitUntilCondition(
348:                 () ->
349:                         cluster.getClusterClient()
350:                                 .getJobStatus(jobID)
351:                                 .get()
352:                                 .isGloballyTerminalState());
353:         if (cluster.getClusterClient().getJobStatus(jobID).get().isGloballyTerminalState()) {
354:             cluster.getClusterClient()
355:                     .requestJobResult(jobID)
356:                     .get()
357:                     .getSerializedThrowable()
358:                     .ifPresent(
359:                             serializedThrowable -> {
360:                                 throw new RuntimeException(serializedThrowable);
361:                             });
362:         }
363:     }
