131:         public StreamingExecutionTestSource(
132:                 String latchId, int numberOfRecords, boolean isFailoverScenario) {
133:             this.latchId = latchId;
134:             this.numberOfRecords = numberOfRecords;
135:             this.isFailoverScenario = isFailoverScenario;
