138:         @Override
139:         public void initializeState(FunctionInitializationContext context) throws Exception {
140:             nextValueState =
141:                     context.getOperatorStateStore()
142:                             .getListState(new ListStateDescriptor<>("nextValue", Integer.class));
143: 
144:             if (nextValueState.get() != null && nextValueState.get().iterator().hasNext()) {
145:                 nextValue = nextValueState.get().iterator().next();
146:             }
147:         }
148: 
149:         @Override
150:         public void run(SourceContext<Integer> ctx) throws Exception {
151:             if (isFailoverScenario && getRuntimeContext().getTaskInfo().getAttemptNumber() == 0) {
152:                 // In the first execution, we first send a part of record...
153:                 sendRecordsUntil((int) (numberOfRecords * FAILOVER_RATIO * 0.5), ctx);
