158:                 }
159: 
160:                 // Then we write the second part of data...
161:                 sendRecordsUntil((int) (numberOfRecords * FAILOVER_RATIO), ctx);
162: 
163:                 // And then trigger the failover.
164:                 if (getRuntimeContext().getTaskInfo().getIndexOfThisSubtask() == 0) {
165:                     throw new RuntimeException("Designated Exception");
166:                 } else {
167:                     while (true) {
168:                         Thread.sleep(50);
169:                     }
170:                 }
171:             } else {
172:                 // If we are not going to trigger failover or we have already triggered failover,
173:                 // run until finished.
174:                 sendRecordsUntil(numberOfRecords, ctx);
175: 
176:                 // Wait the last checkpoint to commit all the pending records.
177:                 isWaitingCheckpointComplete = true;
178:                 CountDownLatch latch = LATCH_MAP.get(latchId);
179:                 latch.await();
180:             }
181:         }
182: 
183:         private void sendRecordsUntil(int targetNumber, SourceContext<Integer> ctx) {
184:             while (!isCanceled && nextValue < targetNumber) {
185:                 synchronized (ctx.getCheckpointLock()) {
186:                     ctx.collect(nextValue++);
187:                 }
188:             }
189:         }
190: 
191:         @Override
192:         public void snapshotState(FunctionSnapshotContext context) throws Exception {
193:             nextValueState.update(Collections.singletonList(nextValue));
194: 
195:             if (isWaitingCheckpointComplete) {
196:                 snapshottedAfterAllRecordsOutput = true;
197:             }
198:         }
199: 
200:         @Override
201:         public void notifyCheckpointComplete(long checkpointId) throws Exception {
202:             if (isWaitingCheckpointComplete && snapshottedAfterAllRecordsOutput) {
203:                 CountDownLatch latch = LATCH_MAP.get(latchId);
204:                 latch.countDown();
205:             }
206: 
207:             hasCompletedCheckpoint = true;
208:         }
209: 
210:         @Override
211:         public void cancel() {
212:             isCanceled = true;
213:         }
