477:     static Map<IntermediateResultPartitionID, ResultPartitionBytes>
478:             createResultPartitionBytesForExecution(Execution execution) {
479:         Map<IntermediateResultPartitionID, ResultPartitionBytes> partitionBytes = new HashMap<>();
480:         execution
481:                 .getVertex()
482:                 .getProducedPartitions()
483:                 .forEach(
484:                         (partitionId, partition) -> {
485:                             int numOfSubpartitions = partition.getNumberOfSubpartitions();
486:                             partitionBytes.put(
487:                                     partitionId,
488:                                     new ResultPartitionBytes(
489:                                             LongStream.range(0, numOfSubpartitions)
490:                                                     .boxed()
491:                                                     .mapToLong(ignored -> SUBPARTITION_BYTES)
492:                                                     .toArray()));
493:                         });
494:         return partitionBytes;
495:     }
