497:     /** Transit the state of all executions in the Job Vertex. */
498:     public static void transitionExecutionsState(
499:             final SchedulerBase scheduler, final ExecutionState state, final JobVertex jobVertex) {
500:         final ExecutionGraph executionGraph = scheduler.getExecutionGraph();
501:         List<Execution> executions =
502:                 Arrays.asList(executionGraph.getJobVertex(jobVertex.getID()).getTaskVertices())
503:                         .stream()
504:                         .map(ExecutionVertex::getCurrentExecutionAttempt)
505:                         .collect(Collectors.toList());
506:         transitionExecutionsState(scheduler, state, executions, null);
