436:     private void triggerFailedByPartitionNotFound(
437:             SchedulerBase scheduler,
438:             ExecutionVertex producerVertex,
439:             ExecutionVertex consumerVertex) {
440:         final Execution execution = consumerVertex.getCurrentExecutionAttempt();
441:         final IntermediateResultPartitionID partitionId =
442:                 getOnlyElement(producerVertex.getProducedPartitions().values()).getPartitionId();
443:         // trigger execution vertex failed by partition not found.
444:         transitionExecutionsState(
