454:     /** Transit the state of all executions. */
455:     public static void transitionExecutionsState(
456:             final SchedulerBase scheduler,
457:             final ExecutionState state,
458:             List<Execution> executions,
459:             @Nullable Throwable throwable) {
460:         for (Execution execution : executions) {
461:             TaskExecutionState taskExecutionState;
462:             if (state == ExecutionState.FINISHED) {
463:                 taskExecutionState =
464:                         createFinishedTaskExecutionState(
465:                                 execution.getAttemptId(),
466:                                 createResultPartitionBytesForExecution(execution));
467:             } else if (state == ExecutionState.FAILED) {
468:                 taskExecutionState =
469:                         createFailedTaskExecutionState(execution.getAttemptId(), throwable);
470:             } else {
471:                 taskExecutionState = new TaskExecutionState(execution.getAttemptId(), state);
472:             }
473:             scheduler.updateTaskExecutionState(taskExecutionState);
474:         }
475:     }
