477:     static Map<IntermediateResultPartitionID, ResultPartitionBytes>
478:             createResultPartitionBytesForExecution(Execution execution) {
479:         Map<IntermediateResultPartitionID, ResultPartitionBytes> partitionBytes = new HashMap<>();
480:         execution
481:                 .getVertex()
482:                 .getProducedPartitions()
483:                 .forEach(
484:                         (partitionId, partition) -> {
