192:         HOLD_AFTER_CHECKPOINT_ON_FIRST_RUN(true),
193:         FAIL_AFTER_CHECKPOINT_ON_FIRST_RUN(true);
194: 
195:         boolean waitForCheckpointOnFirstRun;
196: 
197:         StatefulSourceBehavior(boolean waitForCheckpointOnFirstRun) {
198:             this.waitForCheckpointOnFirstRun = waitForCheckpointOnFirstRun;
