202:     private static class StatefulSource extends RichSourceFunction<Integer>
203:             implements CheckpointedFunction, CheckpointListener {
204: 
205:         private final StatefulSourceBehavior behavior;
206: 
207:         private final int maxNumber;
208: 
209:         private final SharedReference<CountDownLatch> startWaitingForCheckpointLatch;
210: 
211:         private ListState<Integer> nextNumberState;
212: 
213:         private int nextNumber;
214: 
215:         private volatile boolean isCanceled;
216: 
217:         private volatile boolean isWaiting;
218: 
219:         private volatile long firstCheckpointIdAfterWaiting;
220: 
221:         private volatile boolean checkpointCompletedAfterWaiting;
222: 
223:         public StatefulSource(
224:                 StatefulSourceBehavior behavior,
225:                 int maxNumber,
226:                 SharedReference<CountDownLatch> startWaitingForCheckpointLatch) {
227:             this.behavior = behavior;
228:             this.maxNumber = maxNumber;
229:             this.startWaitingForCheckpointLatch = startWaitingForCheckpointLatch;
230:         }
231: 
232:         @Override
233:         public void initializeState(FunctionInitializationContext context) throws Exception {
234:             nextNumberState =
235:                     context.getOperatorStateStore()
236:                             .getListState(new ListStateDescriptor<>("next", Integer.class));
237:             if (nextNumberState.get().iterator().hasNext()) {
238:                 nextNumber = nextNumberState.get().iterator().next();
239:             }
240:         }
241: 
242:         @Override
243:         public void run(SourceContext<Integer> ctx) throws Exception {
244:             emitRecordsTill(maxNumber / 3, ctx);
245: 
246:             if (behavior.waitForCheckpointOnFirstRun
247:                     && getRuntimeContext().getTaskInfo().getAttemptNumber() == 0) {
248:                 // Wait till one checkpoint is triggered and completed
249:                 isWaiting = true;
250:                 startWaitingForCheckpointLatch.get().countDown();
251:                 while (!checkpointCompletedAfterWaiting) {
252:                     Thread.sleep(200);
253:                 }
254: 
255:                 if (behavior == StatefulSourceBehavior.FAIL_AFTER_CHECKPOINT_ON_FIRST_RUN) {
256:                     throw new RuntimeException("Artificial Exception");
257:                 } else if (behavior == StatefulSourceBehavior.HOLD_AFTER_CHECKPOINT_ON_FIRST_RUN) {
258:                     while (!isCanceled) {
259:                         Thread.sleep(200);
260:                     }
261:                 }
262:             } else {
263:                 emitRecordsTill(maxNumber, ctx);
264:             }
265:         }
266: 
267:         private void emitRecordsTill(int endExclusive, SourceContext<Integer> ctx) {
268:             while (!isCanceled && nextNumber < endExclusive) {
269:                 synchronized (ctx.getCheckpointLock()) {
270:                     ctx.collect(nextNumber);
271:                     nextNumber++;
272:                 }
273:             }
274:         }
275: 
276:         @Override
277:         public void snapshotState(FunctionSnapshotContext context) throws Exception {
278:             nextNumberState.update(Collections.singletonList(nextNumber));
279: 
280:             if (isWaiting && firstCheckpointIdAfterWaiting <= 0) {
281:                 firstCheckpointIdAfterWaiting = context.getCheckpointId();
282:             }
283:         }
284: 
285:         @Override
286:         public void notifyCheckpointComplete(long checkpointId) throws Exception {
287:             if (firstCheckpointIdAfterWaiting > 0
288:                     && checkpointId >= firstCheckpointIdAfterWaiting) {
289:                 checkpointCompletedAfterWaiting = true;
290:             }
291:         }
292: 
293:         @Override
294:         public void cancel() {
295:             isCanceled = true;
296:         }
297:     }
