299:     private static class CollectSink implements SinkFunction<Integer> {
300: 
301:         private final SharedReference<List<Integer>> result;
302: 
303:         public CollectSink(SharedReference<List<Integer>> result) {
304:             this.result = result;
305:         }
306: 
307:         @Override
308:         public void invoke(Integer value, Context context) throws Exception {
309:             result.get().add(value);
310:         }
311:     }
312: }
