208:     private static class StringGeneratingSourceFunction
209:             extends RichParallelSourceFunction<Tuple2<Integer, Integer>>
210:             implements CheckpointedFunction {
211: 
212:         private static final long serialVersionUID = 1L;
213: 
214:         private final long numElements;
215:         private final long checkpointLatestAt;
216: 
217:         private int index = -1;
218: 
219:         private int lastRegionIndex = -1;
220: 
221:         private volatile boolean isRunning = true;
222: 
223:         private ListState<Integer> listState;
224: 
225:         private static final ListStateDescriptor<Integer> stateDescriptor =
226:                 new ListStateDescriptor<>("list-1", Integer.class);
227: 
228:         private ListState<Integer> unionListState;
229: 
230:         private static final ListStateDescriptor<Integer> unionStateDescriptor =
231:                 new ListStateDescriptor<>("list-2", Integer.class);
232: 
233:         StringGeneratingSourceFunction(long numElements, long checkpointLatestAt) {
234:             this.numElements = numElements;
235:             this.checkpointLatestAt = checkpointLatestAt;
236:         }
237: 
238:         @Override
239:         public void run(SourceContext<Tuple2<Integer, Integer>> ctx) throws Exception {
240:             if (index < 0) {
241:                 // not been restored, so initialize
242:                 index = 0;
243:             }
244: 
245:             int subTaskIndex = getRuntimeContext().getTaskInfo().getIndexOfThisSubtask();
246:             while (isRunning && index < numElements) {
247: 
248:                 synchronized (ctx.getCheckpointLock()) {
249:                     int key = index / 2;
250:                     int forwardTaskIndex =
251:                             KeyGroupRangeAssignment.assignKeyToParallelOperator(
252:                                     key, MAX_PARALLELISM, NUM_OF_REGIONS);
253:                     // pre-partition output keys
254:                     if (forwardTaskIndex == subTaskIndex) {
255:                         // we would send data with the same key twice.
256:                         ctx.collect(Tuple2.of(key, index));
257:                     }
258:                     index += 1;
259:                 }
260: 
261:                 if (numCompletedCheckpoints.get() < 3) {
262:                     // not yet completed enough checkpoints, so slow down
263:                     if (index < checkpointLatestAt) {
264:                         // mild slow down
265:                         Thread.sleep(1);
266:                     } else {
267:                         // wait until the checkpoints are completed
268:                         while (isRunning && numCompletedCheckpoints.get() < 3) {
269:                             Thread.sleep(300);
270:                         }
271:                     }
272:                 }
273:                 if (jobFailedCnt.get() < NUM_OF_RESTARTS) {
274:                     // slow down if job has not failed for 'NUM_OF_RESTARTS' times.
275:                     Thread.sleep(1);
276:                 }
277:             }
278:         }
279: 
280:         @Override
281:         public void cancel() {
282:             isRunning = false;
283:         }
284: 
285:         @Override
286:         public void snapshotState(FunctionSnapshotContext context) throws Exception {
287:             int indexOfThisSubtask = getRuntimeContext().getTaskInfo().getIndexOfThisSubtask();
288:             if (indexOfThisSubtask != 0) {
289:                 listState.update(Collections.singletonList(index));
290:                 if (indexOfThisSubtask == NUM_OF_REGIONS - 1) {
291:                     lastRegionIndex = index;
292:                     snapshotIndicesOfSubTask.put(context.getCheckpointId(), lastRegionIndex);
293:                 }
294:             }
295:             unionListState.update(Collections.singletonList(indexOfThisSubtask));
296:         }
297: 
298:         @Override
299:         public void initializeState(FunctionInitializationContext context) throws Exception {
300:             int indexOfThisSubtask = getRuntimeContext().getTaskInfo().getIndexOfThisSubtask();
301:             if (context.isRestored()) {
302:                 restoredState = true;
303: 
304:                 unionListState =
305:                         context.getOperatorStateStore().getUnionListState(unionStateDescriptor);
306:                 Set<Integer> actualIndices =
307:                         StreamSupport.stream(unionListState.get().spliterator(), false)
308:                                 .collect(Collectors.toSet());
309:                 if (getRuntimeContext()
310:                         .getTaskInfo()
311:                         .getTaskName()
312:                         .contains(SINGLE_REGION_SOURCE_NAME)) {
313:                     Assert.assertTrue(
314:                             CollectionUtils.isEqualCollection(
315:                                     EXPECTED_INDICES_SINGLE_REGION, actualIndices));
316:                 } else {
317:                     Assert.assertTrue(
318:                             CollectionUtils.isEqualCollection(
319:                                     EXPECTED_INDICES_MULTI_REGION, actualIndices));
320:                 }
321: 
322:                 if (indexOfThisSubtask == 0) {
323:                     listState = context.getOperatorStateStore().getListState(stateDescriptor);
324:                     Assert.assertTrue(
325:                             "list state should be empty for subtask-0",
326:                             ((List<Integer>) listState.get()).isEmpty());
327:                 } else {
328:                     listState = context.getOperatorStateStore().getListState(stateDescriptor);
329:                     Assert.assertTrue(
330:                             "list state should not be empty for subtask-" + indexOfThisSubtask,
331:                             ((List<Integer>) listState.get()).size() > 0);
332: 
333:                     if (indexOfThisSubtask == NUM_OF_REGIONS - 1) {
334:                         index = listState.get().iterator().next();
335:                         if (index
336:                                 != snapshotIndicesOfSubTask.get(lastCompletedCheckpointId.get())) {
337:                             throw new RuntimeException(
338:                                     "Test failed due to unexpected recovered index: "
339:                                             + index
340:                                             + ", while last completed checkpoint record index: "
341:                                             + snapshotIndicesOfSubTask.get(
342:                                                     lastCompletedCheckpointId.get()));
343:                         }
344:                     }
345:                 }
346:             } else {
347:                 unionListState =
348:                         context.getOperatorStateStore().getUnionListState(unionStateDescriptor);
349: 
350:                 if (indexOfThisSubtask != 0) {
351:                     listState = context.getOperatorStateStore().getListState(stateDescriptor);
352:                 }
353:             }
354:         }
355:     }
