357:     private static class FailingMapperFunction
358:             extends RichMapFunction<Tuple2<Integer, Integer>, Tuple2<Integer, Integer>> {
359:         private final int restartTimes;
360:         private ValueState<Integer> valueState;
361: 
362:         @Override
363:         public void open(OpenContext openContext) throws Exception {
364:             super.open(openContext);
365:             valueState =
366:                     getRuntimeContext()
367:                             .getState(new ValueStateDescriptor<>("value", Integer.class));
368:         }
369: 
370:         FailingMapperFunction(int restartTimes) {
371:             this.restartTimes = restartTimes;
372:         }
373: 
374:         @Override
375:         public Tuple2<Integer, Integer> map(Tuple2<Integer, Integer> input) throws Exception {
376:             int indexOfThisSubtask = getRuntimeContext().getTaskInfo().getIndexOfThisSubtask();
377: 
378:             if (input.f1 > FAIL_BASE * (jobFailedCnt.get() + 1)) {
379: 
380:                 // we would let region-0 to failover first
381:                 if (jobFailedCnt.get() < 1 && indexOfThisSubtask == 0) {
382:                     jobFailedCnt.incrementAndGet();
383:                     throw new TestException();
384:                 }
385: 
386:                 // then let last region to failover
387:                 if (jobFailedCnt.get() < restartTimes && indexOfThisSubtask == NUM_OF_REGIONS - 1) {
388:                     jobFailedCnt.incrementAndGet();
389:                     throw new TestException();
390:                 }
391:             }
392: 
393:             // take input (1, 2) and (1, 3) for example, we would finally emit (1, 5) out with the
394:             // usage of keyed state.
395:             Integer value = valueState.value();
396:             if (value == null) {
397:                 valueState.update(input.f1);
398:                 return input;
399:             } else {
400:                 return Tuple2.of(input.f0, value + input.f1);
401:             }
402:         }
403:     }
