405:     private static class ValidatingSink extends RichSinkFunction<Tuple2<Integer, Integer>>
406:             implements ListCheckpointed<HashMap<Integer, Integer>> {
407: 
408:         @SuppressWarnings("unchecked")
409:         private static Map<Integer, Integer>[] maps =
410:                 (Map<Integer, Integer>[]) new Map<?, ?>[NUM_OF_REGIONS];
411: 
412:         private HashMap<Integer, Integer> counts = new HashMap<>();
413: 
414:         @Override
415:         public void invoke(Tuple2<Integer, Integer> input) {
416:             counts.merge(input.f0, input.f1, Math::max);
417:         }
418: 
419:         @Override
420:         public void close() throws Exception {
421:             maps[getRuntimeContext().getTaskInfo().getIndexOfThisSubtask()] = counts;
422:         }
423: 
424:         @Override
425:         public List<HashMap<Integer, Integer>> snapshotState(long checkpointId, long timestamp)
426:                 throws Exception {
427:             return Collections.singletonList(this.counts);
428:         }
429: 
430:         @Override
431:         public void restoreState(List<HashMap<Integer, Integer>> state) throws Exception {
432:             if (state.size() != 1) {
433:                 throw new RuntimeException(
434:                         "Test failed due to unexpected recovered state size " + state.size());
435:             }
436:             this.counts.putAll(state.get(0));
437:         }
438:     }
