190:     @Test
191:     void testSourceChain() {
192:         StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();
193:         env.setMaxParallelism(100);
194:         env.setParallelism(100);
195:         MultipleInputTransformation<Long> transform =
196:                 new MultipleInputTransformation<>(
197:                         "mit", new UnusedOperatorFactory(), Types.LONG, -1);
198: 
199:         Transformation<Long> input1 =
200:                 env.fromSource(
201:                                 new NumberSequenceSource(1, 2),
202:                                 WatermarkStrategy.noWatermarks(),
203:                                 "input1")
204:                         .setParallelism(100)
205:                         .getTransformation();
206:         Transformation<Long> input2 =
207:                 env.fromSource(
208:                                 new NumberSequenceSource(1, 2),
209:                                 WatermarkStrategy.noWatermarks(),
210:                                 "input2")
211:                         .setParallelism(1)
212:                         .getTransformation();
213:         Transformation<Long> input3 =
214:                 env.fromSource(
215:                                 new NumberSequenceSource(1, 2),
216:                                 WatermarkStrategy.noWatermarks(),
217:                                 "input3")
218:                         .setParallelism(1)
219:                         .getTransformation();
220:         transform.addInput(input1);
221:         transform.addInput(input2);
222:         transform.addInput(input3);
223:         transform.setChainingStrategy(ChainingStrategy.HEAD_WITH_SOURCES);
224:         DataStream<Long> dataStream = new DataStream<>(env, transform);
225:         // do not chain with sink operator.
226:         dataStream.rebalance().sinkTo(new DiscardingSink<>()).name("sink");
227:         env.addOperator(transform);
228:         StreamGraph streamGraph = env.getStreamGraph();
229:         streamGraph.setDynamic(true);
230:         JobGraph jobGraph = createStreamGraph(streamGraph);
231:         assertThat(jobGraph.getVerticesSortedTopologicallyFromSources().size()).isEqualTo(4);
232:     }
