234:     private static JobGraph generateJobGraphInLazilyMode(StreamGraph streamGraph) {
235:         AdaptiveGraphManager adaptiveGraphManager =
236:                 new AdaptiveGraphManager(
237:                         Thread.currentThread().getContextClassLoader(), streamGraph, Runnable::run);
238:         JobGraph jobGraph = adaptiveGraphManager.getJobGraph();
239:         List<JobVertex> jobVertices = jobGraph.getVerticesSortedTopologicallyFromSources();
240: 
241:         while (!jobVertices.isEmpty()) {
242:             List<JobVertex> newJobVertices = new ArrayList<>();
243:             for (JobVertex jobVertex : jobVertices) {
244:                 newJobVertices.addAll(adaptiveGraphManager.onJobVertexFinished(jobVertex.getID()));
245:             }
246:             jobVertices = newJobVertices;
247:         }
248:         return jobGraph;
249:     }
