251:     private static boolean isJobGraphEquivalent(JobGraph jobGraph1, JobGraph jobGraph2) {
252:         assertThat(jobGraph1.getJobConfiguration()).isEqualTo(jobGraph2.getJobConfiguration());
253:         assertThat(jobGraph1.getJobType()).isEqualTo(jobGraph2.getJobType());
254:         assertThat(jobGraph1.isDynamic()).isEqualTo(jobGraph2.isDynamic());
255:         assertThat(jobGraph1.isApproximateLocalRecoveryEnabled())
256:                 .isEqualTo(jobGraph2.isApproximateLocalRecoveryEnabled());
257:         assertThat(jobGraph1.getSerializedExecutionConfig())
258:                 .isEqualTo(jobGraph2.getSerializedExecutionConfig());
259:         assertThat(jobGraph1.getCheckpointingSettings().toString())
260:                 .isEqualTo(jobGraph2.getCheckpointingSettings().toString());
261:         assertThat(jobGraph1.getSavepointRestoreSettings())
262:                 .isEqualTo(jobGraph2.getSavepointRestoreSettings());
263:         assertThat(jobGraph1.getUserJars()).isEqualTo(jobGraph2.getUserJars());
264:         assertThat(jobGraph1.getUserArtifacts()).isEqualTo(jobGraph2.getUserArtifacts());
265:         assertThat(jobGraph1.getUserJarBlobKeys()).isEqualTo(jobGraph2.getUserJarBlobKeys());
266:         assertThat(jobGraph1.getClasspaths()).isEqualTo(jobGraph2.getClasspaths());
267:         assertThat(jobGraph1.getJobStatusHooks()).isEqualTo(jobGraph2.getJobStatusHooks());
268: 
269:         List<JobVertex> vertices1 = jobGraph1.getVerticesSortedTopologicallyFromSources();
270:         List<JobVertex> vertices2 = jobGraph2.getVerticesSortedTopologicallyFromSources();
271:         assertThat(vertices1.size()).isEqualTo(vertices2.size());
272:         for (int i = 1; i < vertices1.size(); i++) {
273:             JobVertex vertex1 = vertices1.get(i);
274:             JobVertex vertex2 = vertices2.get(i);
275:             assertThat(vertex1.getID()).isEqualTo(vertex2.getID());
276:             assertThat(vertex1.getInputs().size()).isEqualTo(vertex2.getInputs().size());
277:             assertThat(vertex1.getParallelism()).isEqualTo(vertex2.getParallelism());
278:             assertThat(vertex1.getMaxParallelism()).isEqualTo(vertex2.getMaxParallelism());
279:             assertThat(vertex1.getMinResources()).isEqualTo(vertex2.getMinResources());
280:             assertThat(vertex1.getPreferredResources()).isEqualTo(vertex2.getPreferredResources());
281:             assertThat(vertex1.getInvokableClassName()).isEqualTo(vertex2.getInvokableClassName());
282:             assertThat(vertex1.getName()).isEqualTo(vertex2.getName());
283:             assertThat(vertex1.getOperatorName()).isEqualTo(vertex2.getOperatorName());
284:             assertThat(vertex1.isSupportsConcurrentExecutionAttempts())
285:                     .isEqualTo(vertex2.isSupportsConcurrentExecutionAttempts());
286:             assertThat(vertex1.isAnyOutputBlocking()).isEqualTo(vertex2.isAnyOutputBlocking());
287:             assertThat(vertex1.isParallelismConfigured())
288:                     .isEqualTo(vertex2.isParallelismConfigured());
289:         }
290:         return true;
291:     }
