87:             NamespacedKubernetesClient kubernetesClient,
88:             KubernetesLeaderElectionConfiguration leaderConfig,
89:             LeaderCallbackHandler leaderCallbackHandler,
90:             ExecutorService executorService) {
91:         this.kubernetesClient = kubernetesClient;
92:         this.leaderElectionConfig =
93:                 new LeaderElectionConfigBuilder()
94:                         .withName(leaderConfig.getConfigMapName())
95:                         .withLeaseDuration(leaderConfig.getLeaseDuration())
96:                         .withLock(
97:                                 new ConfigMapLock(
98:                                         new ObjectMetaBuilder()
99:                                                 .withNamespace(kubernetesClient.getNamespace())
100:                                                 .withName(leaderConfig.getConfigMapName())
101:                                                 // Labels will be used to clean up the ha related
102:                                                 // ConfigMaps.
103:                                                 .withLabels(
104:                                                         KubernetesUtils.getConfigMapLabels(
105:                                                                 leaderConfig.getClusterId()))
106:                                                 .build(),
107:                                         leaderConfig.getLockIdentity()))
108:                         .withRenewDeadline(leaderConfig.getRenewDeadline())
109:                         .withRetryPeriod(leaderConfig.getRetryPeriod())
110:                         .withReleaseOnCancel(true)
111:                         .withLeaderCallbacks(
112:                                 new LeaderCallbacks(
113:                                         leaderCallbackHandler::isLeader,
114:                                         leaderCallbackHandler::notLeader,
115:                                         newLeader ->
116:                                                 LOG.info(
117:                                                         "New leader elected {} for {}.",
118:                                                         newLeader,
119:                                                         leaderConfig.getConfigMapName())))
120:                         .build();
121:         this.executorService = executorService;
