129:     private void resetInternalLeaderElector() {
130:         cancelCurrentLeaderElectionSession();
131: 
132:         currentLeaderElectionSession =
133:                 new LeaderElector(kubernetesClient, leaderElectionConfig, executorService).start();
134: 
135:         LOG.info(
136:                 "Triggered leader election on lock {}.", leaderElectionConfig.getLock().describe());
137:     }
