161:             // the shutdown of the executor needs to happen gracefully for scenarios where the
162:             // release is called in the executorService. Interrupting this logic will result in the
163:             // leadership-lost event not being sent to the client.
164:             final List<Runnable> outStandingTasks =
165:                     ExecutorUtils.gracefulShutdown(30, TimeUnit.SECONDS, executorService);
