167:             if (!outStandingTasks.isEmpty()) {
168:                 LOG.warn(
169:                         "{} events were not processed before stopping the {} instance.",
170:                         outStandingTasks.size(),
171:                         KubernetesLeaderElector.class.getSimpleName());
172:             }
173:         }
174:     }
