176:     public static boolean hasLeadership(KubernetesConfigMap configMap, String lockIdentity) {
177:         final String leader = configMap.getAnnotations().get(LEADER_ANNOTATION_KEY);
178:         return leader != null && leader.contains(lockIdentity);
