917:     private void testLeadershipChangeEventHandlingBeingIgnoredAfterLeaderElectionClose(
918:             TriConsumer<LeaderElectionDriver.Listener, Iterable<String>, LeaderInformationRegister>
919:                     callback)
920:             throws Exception {
921:         final AtomicReference<LeaderInformationRegister> storedLeaderInformation =
922:                 new AtomicReference<>();
923:         new Context(storedLeaderInformation) {
924:             {
925:                 runTestWithSynchronousEventHandling(
926:                         () -> {
927:                             grantLeadership();
928: 
929:                             assertThat(storedLeaderInformation.get().getRegisteredComponentIds())
930:                                     .containsExactlyInAnyOrder(
931:                                             contenderContext0.componentId,
932:                                             contenderContext1.componentId);
933: 
934:                             contenderContext0.leaderElection.close();
935: 
936:                             // another contender adds its information to the external storage
937:                             // having additional data stored in the register helps to check whether
938:                             // the register was touched later on (the empty
939:                             // LeaderInformationRegister is implemented as a singleton which would
940:                             // prevent us from checking the identity of the external storage at the
941:                             // end of the test)
942:                             final String otherComponentId = createRandomComponentId();
943:                             final LeaderInformation otherLeaderInformation =
944:                                     LeaderInformation.known(
945:                                             UUID.randomUUID(), "address-for-" + otherComponentId);
946:                             final LeaderInformationRegister registerWithUnknownContender =
947:                                     LeaderInformationRegister.of(
948:                                             otherComponentId, otherLeaderInformation);
949:                             storedLeaderInformation.set(registerWithUnknownContender);
950:                             callback.accept(
951:                                     leaderElectionService,
952:                                     Arrays.asList(
953:                                             contenderContext0.componentId,
954:                                             contenderContext1.componentId),
955:                                     storedLeaderInformation.get());
956: 
957:                             final LeaderInformationRegister correctedExternalStorage =
958:                                     storedLeaderInformation.get();
959:                             assertThat(correctedExternalStorage.getRegisteredComponentIds())
960:                                     .as(
961:                                             "Only the still registered contender and the unknown one should have corrected its LeaderInformation.")
962:                                     .containsExactlyInAnyOrder(
963:                                             contenderContext1.componentId, otherComponentId);
964: 
965:                             contenderContext1.leaderElection.close();
966: 
967:                             final LeaderInformationRegister leftOverData =
968:                                     storedLeaderInformation.get();
969: 
970:                             callback.accept(
971:                                     leaderElectionService,
972:                                     Collections.singleton(contenderContext1.componentId),
973:                                     leftOverData);
974: 
975:                             assertThat(storedLeaderInformation.get().getRegisteredComponentIds())
976:                                     .as(
977:                                             "The following identity check does only make sense if we're not using an empty register.")
978:                                     .hasSize(1);
979:                             assertThat(storedLeaderInformation.get())
980:                                     .as("The external storage shouldn't have been touched.")
981:                                     .isSameAs(leftOverData);
982:                         });
983:             }
984:         };
985:     }
