42: /** ZooKeeper based {@link LeaderElectionDriver} implementation. */
43: public class ZooKeeperLeaderElectionDriver implements LeaderElectionDriver, LeaderLatchListener {
44: 
45:     private static final Logger LOG = LoggerFactory.getLogger(ZooKeeperLeaderElectionDriver.class);
46: 
47:     private final CuratorFramework curatorFramework;
48: 
49:     private final LeaderElectionDriver.Listener leaderElectionListener;
50: 
51:     private final String leaderLatchPath;
52:     private final LeaderLatch leaderLatch;
53: 
54:     private final TreeCache treeCache;
55: 
56:     private final ConnectionStateListener listener =
57:             (client, newState) -> handleStateChange(newState);
58: 
59:     private AtomicBoolean running = new AtomicBoolean(true);
60: 
61:     public ZooKeeperLeaderElectionDriver(
62:             CuratorFramework curatorFramework, LeaderElectionDriver.Listener leaderElectionListener)
63:             throws Exception {
64:         this.curatorFramework = Preconditions.checkNotNull(curatorFramework);
65:         this.leaderElectionListener = Preconditions.checkNotNull(leaderElectionListener);
66: 
67:         this.leaderLatchPath =
68:                 ZooKeeperUtils.generateLeaderLatchPath(curatorFramework.getNamespace());
69:         this.leaderLatch = new LeaderLatch(curatorFramework, ZooKeeperUtils.getLeaderLatchPath());
70:         this.treeCache =
71:                 ZooKeeperUtils.createTreeCache(
72:                         curatorFramework,
73:                         "/",
74:                         new ZooKeeperLeaderElectionDriver.ConnectionInfoNodeSelector());
75: 
76:         treeCache
77:                 .getListenable()
78:                 .addListener(
79:                         (client, event) -> {
80:                             switch (event.getType()) {
81:                                 case NODE_ADDED:
82:                                 case NODE_UPDATED:
83:                                     Preconditions.checkNotNull(
84:                                             event.getData(),
85:                                             "The ZooKeeper event data must not be null.");
86:                                     handleChangedLeaderInformation(event.getData());
87:                                     break;
88:                                 case NODE_REMOVED:
89:                                     Preconditions.checkNotNull(
90:                                             event.getData(),
91:                                             "The ZooKeeper event data must not be null.");
92:                                     handleRemovedLeaderInformation(event.getData().getPath());
93:                                     break;
94:                             }
95:                         });
96: 
97:         leaderLatch.addListener(this);
98:         curatorFramework.getConnectionStateListenable().addListener(listener);
99:         leaderLatch.start();
100:         treeCache.start();
101:     }
102: 
103:     @Override
104:     public void close() throws Exception {
105:         if (running.compareAndSet(true, false)) {
106:             LOG.info("Closing {}.", this);
107: 
108:             curatorFramework.getConnectionStateListenable().removeListener(listener);
109: 
110:             Exception exception = null;
111: 
112:             try {
113:                 treeCache.close();
114:             } catch (Exception e) {
115:                 exception = e;
116:             }
117: 
118:             try {
119:                 leaderLatch.close();
120:             } catch (Exception e) {
121:                 exception = ExceptionUtils.firstOrSuppressed(e, exception);
122:             }
123: 
124:             ExceptionUtils.tryRethrowException(exception);
125:         }
126:     }
127: 
128:     @Override
129:     public boolean hasLeadership() {
130:         return leaderLatch.hasLeadership();
131:     }
132: 
133:     @Override
134:     public void publishLeaderInformation(String componentId, LeaderInformation leaderInformation) {
135:         Preconditions.checkState(running.get());
136: 
137:         if (!leaderLatch.hasLeadership()) {
138:             return;
139:         }
140: 
141:         final String connectionInformationPath =
142:                 ZooKeeperUtils.generateConnectionInformationPath(componentId);
143: 
144:         LOG.debug(
145:                 "Write leader information {} for component '{}' to {}.",
146:                 leaderInformation,
147:                 componentId,
148:                 ZooKeeperUtils.generateZookeeperPath(
149:                         curatorFramework.getNamespace(), connectionInformationPath));
150: 
151:         try {
152:             ZooKeeperUtils.writeLeaderInformationToZooKeeper(
153:                     leaderInformation,
154:                     curatorFramework,
155:                     leaderLatch::hasLeadership,
156:                     connectionInformationPath);
157:         } catch (Exception e) {
158:             leaderElectionListener.onError(e);
159:         }
160:     }
161: 
162:     @Override
163:     public void deleteLeaderInformation(String componentId) {
164:         try {
165:             ZooKeeperUtils.deleteZNode(
166:                     curatorFramework, ZooKeeperUtils.generateZookeeperPath(componentId));
167:         } catch (Exception e) {
168:             leaderElectionListener.onError(e);
169:         }
170:     }
171: 
172:     private void handleStateChange(ConnectionState newState) {
173:         switch (newState) {
174:             case CONNECTED:
175:                 LOG.debug("Connected to ZooKeeper quorum. Leader election can start.");
176:                 break;
177:             case SUSPENDED:
178:                 LOG.warn("Connection to ZooKeeper suspended, waiting for reconnection.");
179:                 break;
180:             case RECONNECTED:
181:                 LOG.info(
182:                         "Connection to ZooKeeper was reconnected. Leader election can be restarted.");
183:                 break;
184:             case LOST:
185:                 // Maybe we have to throw an exception here to terminate the JobManager
186:                 LOG.warn(
187:                         "Connection to ZooKeeper lost. None of the contenders participates in the leader election anymore.");
188:                 break;
189:         }
190:     }
191: 
192:     @Override
193:     public void isLeader() {
194:         final UUID leaderSessionID = UUID.randomUUID();
195:         LOG.debug("{} obtained the leadership with session ID {}.", this, leaderSessionID);
196:         leaderElectionListener.onGrantLeadership(leaderSessionID);
197:     }
198: 
199:     @Override
200:     public void notLeader() {
201:         LOG.debug("{} lost the leadership.", this);
202:         leaderElectionListener.onRevokeLeadership();
203:     }
204: 
205:     private void handleChangedLeaderInformation(ChildData childData) {
206:         if (shouldHandleLeaderInformationEvent(childData.getPath())) {
207:             final String componentId = extractComponentId(childData.getPath());
208: 
209:             final LeaderInformation leaderInformation =
210:                     tryReadingLeaderInformation(childData, componentId);
211: 
212:             leaderElectionListener.onLeaderInformationChange(componentId, leaderInformation);
213:         }
214:     }
215: 
216:     private String extractComponentId(String path) {
217:         final String[] splits = ZooKeeperUtils.splitZooKeeperPath(path);
218: 
219:         Preconditions.checkState(
220:                 splits.length >= 2,
221:                 String.format(
222:                         "Expecting path consisting of /<component-id>/connection_info. Got path '%s'",
223:                         path));
224: 
225:         return splits[splits.length - 2];
226:     }
227: 
228:     private void handleRemovedLeaderInformation(String removedNodePath) {
229:         if (shouldHandleLeaderInformationEvent(removedNodePath)) {
230:             final String leaderName = extractComponentId(removedNodePath);
231: 
232:             leaderElectionListener.onLeaderInformationChange(leaderName, LeaderInformation.empty());
233:         }
234:     }
235: 
236:     private boolean shouldHandleLeaderInformationEvent(String path) {
237:         return running.get()
238:                 && leaderLatch.hasLeadership()
239:                 && ZooKeeperUtils.isConnectionInfoPath(path);
240:     }
241: 
242:     private LeaderInformation tryReadingLeaderInformation(ChildData childData, String id) {
243:         LeaderInformation leaderInformation;
244:         try {
245:             leaderInformation = ZooKeeperUtils.readLeaderInformation(childData.getData());
246: 
247:             LOG.debug("Leader information for {} has changed to {}.", id, leaderInformation);
248:         } catch (IOException | ClassNotFoundException e) {
249:             LOG.debug(
250:                     "Could not read leader information for {}. Rewriting the information.", id, e);
251:             leaderInformation = LeaderInformation.empty();
252:         }
253: 
254:         return leaderInformation;
255:     }
256: 
257:     /**
258:      * This selector finds all connection info nodes. See {@link ZooKeeperLeaderElectionHaServices}
259:      * for more details on the Znode layout.
260:      */
261:     private static class ConnectionInfoNodeSelector implements TreeCacheSelector {
262:         @Override
263:         public boolean traverseChildren(String fullPath) {
264:             return true;
265:         }
266: 
267:         @Override
268:         public boolean acceptChild(String fullPath) {
269:             return !fullPath.endsWith(ZooKeeperUtils.getLeaderLatchPath());
270:         }
271:     }
272: 
273:     @Override
274:     public String toString() {
275:         return String.format(
276:                 "%s{leaderLatchPath='%s'}", getClass().getSimpleName(), leaderLatchPath);
277:     }
278: }
