257:     @Test
258:     void testLeaderElectionWithMultipleDrivers() throws Exception {
259:         final CuratorFrameworkWithUnhandledErrorListener curatorFramework = startCuratorFramework();
260: 
261:         try {
262:             Set<ElectionDriver> electionDrivers =
263:                     Stream.generate(
264:                                     () ->
265:                                             createLeaderElectionDriver(
266:                                                     curatorFramework.asCuratorFramework(),
267:                                                     testingFatalErrorHandlerResource
268:                                                             .getTestingFatalErrorHandler()))
269:                             .limit(3)
270:                             .collect(Collectors.toSet());
271: 
272:             while (!electionDrivers.isEmpty()) {
273:                 final CompletableFuture<Object> anyLeader =
274:                         CompletableFuture.anyOf(
275:                                 electionDrivers.stream()
276:                                         .map(ElectionDriver::getLeadershipFuture)
277:                                         .toArray(CompletableFuture[]::new));
278: 
279:                 // wait for any leader
280:                 anyLeader.join();
281: 
282:                 final Map<Boolean, Set<ElectionDriver>> leaderAndRest =
283:                         electionDrivers.stream()
284:                                 .collect(
285:                                         Collectors.partitioningBy(
286:                                                 ElectionDriver::hasLeadership, Collectors.toSet()));
287: 
288:                 assertThat(leaderAndRest.get(true)).hasSize(1);
289: 
290:                 // TODO: remove this line after CURATOR-645 is resolved
291:                 // CURATOR-645 covers a bug in the LeaderLatch implementation that causes a race
292:                 // condition if a child node, participating in the leader election, is removed too
293:                 // fast. This results in a different code branch being executed which triggers a
294:                 // reset of the LeaderLatch instead of re-collecting the children to determine the
295:                 // next leader.
296:                 // The issue occurs because LeaderLatch#checkLeadership is not executed
297:                 // transactionally, i.e. retrieving the children and setting up the watcher for the
298:                 // predecessor is not done atomically. This leads to the race condition where a
299:                 // children (the previous leader's node) is removed before setting up the watcher
300:                 // which results in an invalid handling of the situation using reset.
301:                 // Adding some sleep here (simulating the leader actually doing something) will
302:                 // reduce the risk of falling into the race condition because it will give the
303:                 // concurrently running LeaderLatch instances more time to set up the watchers
304:                 // properly.
305:                 Thread.sleep(100);
306: 
307:                 Iterables.getOnlyElement(leaderAndRest.get(true)).close();
308: 
309:                 electionDrivers = leaderAndRest.get(false);
310:             }
311:         } finally {
312:             curatorFramework.close();
313:         }
314:     }
