50: /** {@link LeaderElectionDriver} for Kubernetes. */
51: public class KubernetesLeaderElectionDriver implements LeaderElectionDriver {
52: 
53:     private static final Logger LOG = LoggerFactory.getLogger(KubernetesLeaderElectionDriver.class);
54: 
55:     private final FlinkKubeClient kubeClient;
56: 
57:     private final String configMapName;
58: 
59:     private final String lockIdentity;
60: 
61:     private final LeaderElectionDriver.Listener leaderElectionListener;
62: 
63:     private final KubernetesLeaderElector leaderElector;
64: 
65:     private final KubernetesSharedWatcher.Watch kubernetesWatch;
66: 
67:     private final AtomicBoolean running = new AtomicBoolean(true);
68: 
69:     public KubernetesLeaderElectionDriver(
70:             KubernetesLeaderElectionConfiguration leaderElectionConfiguration,
71:             FlinkKubeClient kubeClient,
72:             Listener leaderElectionListener,
73:             KubernetesConfigMapSharedWatcher configMapSharedWatcher,
74:             Executor watchExecutor) {
75:         Preconditions.checkNotNull(leaderElectionConfiguration);
76:         this.kubeClient = Preconditions.checkNotNull(kubeClient);
77:         this.leaderElectionListener = Preconditions.checkNotNull(leaderElectionListener);
78:         Preconditions.checkNotNull(configMapSharedWatcher);
79:         Preconditions.checkNotNull(watchExecutor);
80: 
81:         this.configMapName = leaderElectionConfiguration.getConfigMapName();
82:         this.lockIdentity = leaderElectionConfiguration.getLockIdentity();
83: 
84:         this.leaderElector =
85:                 kubeClient.createLeaderElector(
86:                         leaderElectionConfiguration, new LeaderCallbackHandlerImpl());
87: 
88:         kubernetesWatch =
89:                 configMapSharedWatcher.watch(
90:                         configMapName, new ConfigMapCallbackHandlerImpl(), watchExecutor);
91: 
92:         leaderElector.run();
93: 
94:         LOG.debug("Starting the {} for config map {}.", getClass().getSimpleName(), configMapName);
95:     }
96: 
97:     @Override
98:     public void close() throws Exception {
99:         if (running.compareAndSet(true, false)) {
100:             LOG.info("Closing {}.", this);
101: 
102:             leaderElector.stop();
103:             kubernetesWatch.close();
104:         }
105:     }
106: 
107:     @Override
108:     public boolean hasLeadership() {
109:         Preconditions.checkState(running.get());
110:         final Optional<KubernetesConfigMap> optionalConfigMap =
111:                 kubeClient.getConfigMap(configMapName);
112: 
113:         if (optionalConfigMap.isPresent()) {
114:             return KubernetesLeaderElector.hasLeadershipAsync(optionalConfigMap.get(), lockIdentity);
115:         } else {
116:             leaderElectionListener.onError(
117:                     new KubernetesException(
118:                             String.format(
119:                                     "ConfigMap %s does not exist. This indicates that somebody has interfered with Flink's operation.",
120:                                     configMapName)));
121:             return false;
122:         }
123:     }
124: 
125:     @Override
126:     public void publishLeaderInformation(String componentId, LeaderInformation leaderInformation) {
127:         Preconditions.checkState(running.get());
128: 
129:         try {
130:             kubeClient
131:                     .checkAndUpdateConfigMap(
132:                             configMapName,
133:                             updateConfigMapWithLeaderInformation(componentId, leaderInformation))
134:                     .get();
135:         } catch (InterruptedException | ExecutionException e) {
136:             leaderElectionListener.onError(e);
137:         }
138: 
139:         LOG.debug(
140:                 "Successfully wrote leader information {} for leader {} into the config map {}.",
141:                 leaderInformation,
142:                 componentId,
143:                 configMapName);
144:     }
145: 
146:     @Override
147:     public void deleteLeaderInformation(String componentId) {
148:         publishLeaderInformation(componentId, LeaderInformation.empty());
149:     }
150: 
151:     private Function<KubernetesConfigMap, Optional<KubernetesConfigMap>>
152:             updateConfigMapWithLeaderInformation(
153:                     String leaderName, LeaderInformation leaderInformation) {
154:         final String configMapDataKey = KubernetesUtils.createSingleLeaderKey(leaderName);
155: 
156:         return kubernetesConfigMap -> {
157:             if (KubernetesLeaderElector.hasLeadershipAsync(kubernetesConfigMap, lockIdentity)) {
158:                 final Map<String, String> data = kubernetesConfigMap.getData();
159: 
160:                 if (leaderInformation.isEmpty()) {
161:                     data.remove(configMapDataKey);
162:                 } else {
163:                     data.put(
164:                             configMapDataKey,
165:                             KubernetesUtils.encodeLeaderInformation(leaderInformation));
166:                 }
167: 
168:                 return Optional.of(kubernetesConfigMap);
169:             }
170: 
171:             return Optional.empty();
172:         };
173:     }
174: 
175:     private static LeaderInformationRegister extractLeaderInformation(
176:             KubernetesConfigMap configMap) {
177:         final Map<String, String> data = configMap.getData();
178: 
179:         final Map<String, LeaderInformation> extractedLeaderInformation = new HashMap<>();
180: 
181:         for (Map.Entry<String, String> keyValuePair : data.entrySet()) {
182:             final String key = keyValuePair.getKey();
183:             if (KubernetesUtils.isSingleLeaderKey(key)) {
184:                 final String leaderName = KubernetesUtils.extractLeaderName(key);
185:                 final LeaderInformation leaderInformation =
186:                         KubernetesUtils.parseLeaderInformationSafely(keyValuePair.getValue())
187:                                 .orElse(LeaderInformation.empty());
188:                 extractedLeaderInformation.put(leaderName, leaderInformation);
189:             }
190:         }
191: 
192:         return new LeaderInformationRegister(extractedLeaderInformation);
193:     }
