127:         Preconditions.checkState(running.get());
128: 
129:         try {
130:             kubeClient
131:                     .checkAndUpdateConfigMap(
132:                             configMapName,
133:                             updateConfigMapWithLeaderInformation(componentId, leaderInformation))
134:                     .get();
135:         } catch (InterruptedException | ExecutionException e) {
136:             leaderElectionListener.onError(e);
137:         }
138: 
139:         LOG.debug(
140:                 "Successfully wrote leader information {} for leader {} into the config map {}.",
141:                 leaderInformation,
142:                 componentId,
143:                 configMapName);
144:     }
145: 
146:     @Override
147:     public void deleteLeaderInformation(String componentId) {
148:         publishLeaderInformation(componentId, LeaderInformation.empty());
149:     }
150: 
151:     private Function<KubernetesConfigMap, Optional<KubernetesConfigMap>>
152:             updateConfigMapWithLeaderInformation(
153:                     String leaderName, LeaderInformation leaderInformation) {
154:         final String configMapDataKey = KubernetesUtils.createSingleLeaderKey(leaderName);
155: 
156:         return kubernetesConfigMap -> {
157:             if (KubernetesLeaderElector.hasLeadershipAsync(kubernetesConfigMap, lockIdentity)) {
158:                 final Map<String, String> data = kubernetesConfigMap.getData();
159: 
160:                 if (leaderInformation.isEmpty()) {
161:                     data.remove(configMapDataKey);
162:                 } else {
163:                     data.put(
164:                             configMapDataKey,
165:                             KubernetesUtils.encodeLeaderInformation(leaderInformation));
166:                 }
167: 
168:                 return Optional.of(kubernetesConfigMap);
169:             }
170: 
171:             return Optional.empty();
172:         };
173:     }
174: 
175:     private static LeaderInformationRegister extractLeaderInformation(
176:             KubernetesConfigMap configMap) {
177:         final Map<String, String> data = configMap.getData();
178: 
179:         final Map<String, LeaderInformation> extractedLeaderInformation = new HashMap<>();
180: 
181:         for (Map.Entry<String, String> keyValuePair : data.entrySet()) {
182:             final String key = keyValuePair.getKey();
183:             if (KubernetesUtils.isSingleLeaderKey(key)) {
184:                 final String leaderName = KubernetesUtils.extractLeaderName(key);
185:                 final LeaderInformation leaderInformation =
186:                         KubernetesUtils.parseLeaderInformationSafely(keyValuePair.getValue())
187:                                 .orElse(LeaderInformation.empty());
188:                 extractedLeaderInformation.put(leaderName, leaderInformation);
189:             }
190:         }
191: 
192:         return new LeaderInformationRegister(extractedLeaderInformation);
193:     }
194: 
195:     private class LeaderCallbackHandlerImpl extends KubernetesLeaderElector.LeaderCallbackHandler {
196:         @Override
197:         public void isLeader() {
198:             leaderElectionListener.onGrantLeadership(UUID.randomUUID());
199:         }
200: 
201:         @Override
202:         public void notLeader() {
203:             leaderElectionListener.onRevokeLeadership();
204:             leaderElector.run();
205:         }
206:     }
207: 
208:     private class ConfigMapCallbackHandlerImpl
209:             implements FlinkKubeClient.WatchCallbackHandler<KubernetesConfigMap> {
210:         @Override
211:         public void onAdded(List<KubernetesConfigMap> resources) {
212:             // nothing to do
213:         }
214: 
215:         @Override
216:         public void onModified(List<KubernetesConfigMap> configMaps) {
217:             final KubernetesConfigMap configMap = getOnlyConfigMap(configMaps, configMapName);
218: 
219:             if (KubernetesLeaderElector.hasLeadershipAsync(configMap, lockIdentity)) {
220:                 leaderElectionListener.onLeaderInformationChange(
221:                         extractLeaderInformation(configMap));
222:             }
223:         }
224: 
225:         @Override
226:         public void onDeleted(List<KubernetesConfigMap> configMaps) {
227:             final KubernetesConfigMap configMap = getOnlyConfigMap(configMaps, configMapName);
228:             if (KubernetesLeaderElector.hasLeadershipAsync(configMap, lockIdentity)) {
229:                 leaderElectionListener.onError(
230:                         new LeaderElectionException(
231:                                 String.format(
232:                                         "ConfigMap %s has been deleted externally.",
233:                                         configMapName)));
234:             }
235:         }
236: 
237:         @Override
238:         public void onError(List<KubernetesConfigMap> configMaps) {
239:             final KubernetesConfigMap configMap = getOnlyConfigMap(configMaps, configMapName);
240:             if (KubernetesLeaderElector.hasLeadershipAsync(configMap, lockIdentity)) {
241:                 leaderElectionListener.onError(
242:                         new LeaderElectionException(
243:                                 String.format(
244:                                         "Error while watching the ConfigMap %s.", configMapName)));
245:             }
246:         }
247: 
248:         @Override
249:         public void handleError(Throwable throwable) {
250:             leaderElectionListener.onError(
251:                     new LeaderElectionException(
252:                             String.format("Error while watching the ConfigMap %s.", configMapName),
253:                             throwable));
254:         }
255:     }
256: 
257:     @Override
258:     public String toString() {
259:         return String.format("%s{configMapName='%s'}", getClass().getSimpleName(), configMapName);
260:     }
261: }
