50: /** Base class for command line options that refer to a JAR file program. */
51: public class ProgramOptions extends CommandLineOptions {
52: 
53:     private String jarFilePath;
54: 
55:     protected String entryPointClass;
56: 
57:     private final List<URL> classpaths;
58: 
59:     private final String[] programArgs;
60: 
61:     private final boolean hasParallelismOpt;
62: 
63:     private final int parallelism;
64: 
65:     private final boolean detachedMode;
66: 
67:     private final boolean shutdownOnAttachedExit;
68: 
69:     private final SavepointRestoreSettings savepointSettings;
70: 
71:     protected ProgramOptions(CommandLine line) throws CliArgsException {
72:         super(line);
73: 
74:         this.entryPointClass =
75:                 line.hasOption(CLASS_OPTION.getOpt())
76:                         ? line.getOptionValue(CLASS_OPTION.getOpt())
77:                         : null;
78: 
79:         this.jarFilePath =
80:                 line.hasOption(JAR_OPTION.getOpt())
81:                         ? line.getOptionValue(JAR_OPTION.getOpt())
82:                         : null;
83: 
84:         this.programArgs = extractProgramArgs(line);
85: 
86:         List<URL> classpaths = new ArrayList<URL>();
87:         if (line.hasOption(CLASSPATH_OPTION.getOpt())) {
88:             for (String path : line.getOptionValues(CLASSPATH_OPTION.getOpt())) {
89:                 try {
90:                     classpaths.add(new URL(path));
91:                 } catch (MalformedURLException e) {
92:                     throw new CliArgsException("Bad syntax for classpath: " + path);
93:                 }
94:             }
95:         }
96:         this.classpaths = classpaths;
97: 
98:         if (line.hasOption(PARALLELISM_OPTION.getOpt())) {
99:             hasParallelismOpt = true;
100:             String parString = line.getOptionValue(PARALLELISM_OPTION.getOpt());
101:             try {
102:                 parallelism = Integer.parseInt(parString);
103:                 if (parallelism <= 0 && parallelism != ExecutionConfig.PARALLELISM_DEFAULT) {
104:                     throw new NumberFormatException();
105:                 }
106:             } catch (NumberFormatException e) {
107:                 throw new CliArgsException(
108:                         "The parallelism must be a positive number: " + parString);
109:             }
110:         } else {
111:             hasParallelismOpt = false;
112:             parallelism = ExecutionConfig.PARALLELISM_DEFAULT;
113:         }
114: 
115:         detachedMode =
116:                 line.hasOption(DETACHED_OPTION.getOpt())
117:                         || line.hasOption(YARN_DETACHED_OPTION.getOpt());
118:         shutdownOnAttachedExit = line.hasOption(SHUTDOWN_IF_ATTACHED_OPTION.getOpt());
119: 
120:         this.savepointSettings = CliFrontendParser.createSavepointRestoreSettings(line);
121:     }
122: 
123:     protected String[] extractProgramArgs(CommandLine line) {
124:         String[] args =
125:                 line.hasOption(ARGS_OPTION.getOpt())
126:                         ? line.getOptionValues(ARGS_OPTION.getOpt())
127:                         : line.getArgs();
128: 
129:         if (args.length > 0 && !line.hasOption(JAR_OPTION.getOpt())) {
130:             jarFilePath = args[0];
131:             args = Arrays.copyOfRange(args, 1, args.length);
132:         }
133: 
134:         return args;
135:     }
136: 
137:     public void validate() throws CliArgsException {
138:         // Java program should be specified a JAR file
139:         if (getJarFilePath() == null) {
140:             throw new CliArgsException("Java program should be specified a JAR file.");
141:         }
142:         if (savepointSettings.getRestoreMode().equals(RestoreMode.LEGACY)) {
143:             System.out.printf(
144:                     "Warning: The %s restore mode is deprecated, please use %s or"
145:                             + " %s mode instead.%n",
146:                     RestoreMode.LEGACY, RestoreMode.CLAIM, RestoreMode.NO_CLAIM);
147:         }
148:     }
149: 
150:     public String getJarFilePath() {
151:         return jarFilePath;
152:     }
153: 
154:     public String getEntryPointClassName() {
155:         return entryPointClass;
156:     }
157: 
158:     public List<URL> getClasspaths() {
159:         return classpaths;
160:     }
161: 
162:     public String[] getProgramArgs() {
163:         return programArgs;
164:     }
165: 
166:     public int getParallelism() {
167:         return parallelism;
168:     }
169: 
170:     public boolean getDetachedMode() {
171:         return detachedMode;
172:     }
173: 
174:     public boolean isShutdownOnAttachedExit() {
175:         return shutdownOnAttachedExit;
176:     }
177: 
178:     public SavepointRestoreSettings getSavepointRestoreSettings() {
179:         return savepointSettings;
180:     }
181: 
182:     public void applyToConfiguration(Configuration configuration) {
183:         if (hasParallelismOpt) {
184:             configuration.set(CoreOptions.DEFAULT_PARALLELISM, getParallelism());
185:         }
186: 
187:         configuration.set(DeploymentOptions.ATTACHED, !getDetachedMode());
188:         configuration.set(DeploymentOptions.SHUTDOWN_IF_ATTACHED, isShutdownOnAttachedExit());
189:         ConfigUtils.encodeCollectionToConfig(
190:                 configuration, PipelineOptions.CLASSPATHS, getClasspaths(), URL::toString);
191:         SavepointRestoreSettings.toConfiguration(getSavepointRestoreSettings(), configuration);
192:     }
193: 
194:     public static ProgramOptions create(CommandLine line) throws CliArgsException {
195:         if (isPythonEntryPoint(line) || containsPythonDependencyOptions(line)) {
196:             return createPythonProgramOptions(line);
197:         } else {
198:             return new ProgramOptions(line);
199:         }
200:     }
201: }
