73:      *     1). Adding more checkpoints than this results in older checkpoints being discarded.
74:      */
75:     public StandaloneCompletedCheckpointStore(
76:             int maxNumberOfCheckpointsToRetain,
77:             SharedStateRegistryFactory sharedStateRegistryFactory,
78:             Executor ioExecutor,
79:             RestoreMode recoveryClaimMode) {
80:         this(
81:                 maxNumberOfCheckpointsToRetain,
82:                 sharedStateRegistryFactory,
83:                 new ArrayDeque<>(maxNumberOfCheckpointsToRetain + 1),
84:                 ioExecutor,
85:                 recoveryClaimMode);
86:     }
87: 
88:     private StandaloneCompletedCheckpointStore(
89:             int maxNumberOfCheckpointsToRetain,
90:             SharedStateRegistryFactory sharedStateRegistryFactory,
91:             ArrayDeque<CompletedCheckpoint> checkpoints,
92:             Executor ioExecutor,
93:             RestoreMode recoveryClaimMode) {
94:         super(sharedStateRegistryFactory.create(ioExecutor, checkpoints, recoveryClaimMode));
95:         checkArgument(maxNumberOfCheckpointsToRetain >= 1, "Must retain at least one checkpoint.");
96:         this.maxNumberOfCheckpointsToRetain = maxNumberOfCheckpointsToRetain;
97:         this.checkpoints = checkpoints;
98:         this.ioExecutor = checkNotNull(ioExecutor);
99:     }
100: 
101:     @Nullable
102:     @Override
103:     public CompletedCheckpoint addCheckpointAndSubsumeOldestOne(
104:             CompletedCheckpoint checkpoint,
105:             CheckpointsCleaner checkpointsCleaner,
106:             Runnable postCleanup)
107:             throws Exception {
108: 
109:         checkpoints.addLast(checkpoint);
110: 
111:         CompletedCheckpoint completedCheckpoint =
112:                 CheckpointSubsumeHelper.subsume(
113:                                 checkpoints,
114:                                 maxNumberOfCheckpointsToRetain,
115:                                 (cc) -> {
116:                                     cc.markAsDiscardedOnSubsume();
117:                                     checkpointsCleaner.addSubsumedCheckpoint(cc);
118:                                 })
119:                         .orElse(null);
120: 
121:         findLowest(checkpoints)
122:                 .ifPresent(
123:                         id ->
124:                                 checkpointsCleaner.cleanSubsumedCheckpoints(
125:                                         id,
126:                                         getSharedStateRegistry().unregisterUnusedState(id),
127:                                         postCleanup,
128:                                         ioExecutor));
129: 
130:         return completedCheckpoint;
131:     }
132: 
133:     @Override
134:     public List<CompletedCheckpoint> getAllCheckpoints() {
135:         return new ArrayList<>(checkpoints);
136:     }
137: 
138:     @Override
139:     public int getNumberOfRetainedCheckpoints() {
140:         return checkpoints.size();
141:     }
142: 
143:     @Override
144:     public int getMaxNumberOfRetainedCheckpoints() {
145:         return maxNumberOfCheckpointsToRetain;
146:     }
147: 
148:     @Override
149:     public void shutdown(JobStatus jobStatus, CheckpointsCleaner checkpointsCleaner)
150:             throws Exception {
151:         super.shutdown(jobStatus, checkpointsCleaner);
152:         try {
153:             LOG.info("Shutting down");
154: 
155:             long lowestRetained = Long.MAX_VALUE;
156:             for (CompletedCheckpoint checkpoint : checkpoints) {
157:                 if (checkpoint.shouldBeDiscardedOnShutdown(jobStatus)) {
158:                     checkpoint.markAsDiscardedOnShutdown(jobStatus).discard();
159:                 } else {
160:                     LOG.info(
161:                             "Checkpoint with ID {} at '{}' not discarded.",
162:                             checkpoint.getCheckpointID(),
163:                             checkpoint.getExternalPointer());
164:                     lowestRetained = Math.min(checkpoint.getCheckpointID(), lowestRetained);
165:                 }
166:             }
167:             if (jobStatus.isGloballyTerminalState()) {
168:                 // Now discard the shared state of not subsumed checkpoints - only if:
169:                 // - the job is in a globally terminal state. Otherwise,
170:                 // it can be a suspension, after which this state might still be needed.
171:                 // - checkpoint is not retained (it might be used externally)
172:                 // - checkpoint handle removal succeeded (e.g. from ZK) - otherwise, it might still
173:                 // be used in recovery if the job status is lost
174:                 checkpointsCleaner.cleanSubsumedCheckpoints(
175:                         lowestRetained,
176:                         getSharedStateRegistry().unregisterUnusedState(lowestRetained),
177:                         () -> {},
178:                         ioExecutor);
179:             }
180: 
181:         } finally {
182:             checkpoints.clear();
183:         }
184:     }
185: 
186:     @Override
187:     public boolean requiresExternalizedCheckpoints() {
188:         return false;
189:     }
190: }
