589:     private static class HaltingCheckpointRecoveryFactory implements CheckpointRecoveryFactory {
590: 
591:         private final CompletedCheckpointStore completedCheckpointStore;
592:         private final CheckpointIDCounter checkpointIDCounter;
593: 
