596:         public HaltingCheckpointRecoveryFactory(
597:                 CompletableFuture<JobStatus> completableCheckpointStoreShutDownFuture,
598:                 CompletableFuture<JobStatus> checkpointIDCounterShutDownFuture) {
599:             this(
