479:     /**
480:      * Infinite source which notifies when all of its sub tasks have been started via the count down
481:      * latch.
482:      */
483:     public static class NotifyingInfiniteTupleSource
484:             extends ManualWindowSpeedITCase.InfiniteTupleSource {
485: 
486:         private static final long serialVersionUID = 8120981235081181746L;
487: 
488:         private static CountDownLatch countDownLatch;
489: 
490:         public NotifyingInfiniteTupleSource(int numKeys) {
491:             super(numKeys);
492:         }
493: 
494:         @Override
495:         public void run(SourceContext<Tuple2<String, Integer>> out) throws Exception {
496:             if (countDownLatch != null) {
497:                 countDownLatch.countDown();
498:             }
499: 
500:             super.run(out);
501:         }
502:     }
