504:     /**
505:      * This {@link WatermarkStrategy} assigns the current system time as the event-time timestamp.
506:      * In a real use case you should use proper timestamps and an appropriate {@link
507:      * WatermarkStrategy}.
508:      */
509:     private static class IngestionTimeWatermarkStrategy<T> implements WatermarkStrategy<T> {
510: 
511:         private IngestionTimeWatermarkStrategy() {}
512: 
513:         public static <T> IngestionTimeWatermarkStrategy<T> create() {
514:             return new IngestionTimeWatermarkStrategy<>();
515:         }
516: 
517:         @Override
518:         public WatermarkGenerator<T> createWatermarkGenerator(
519:                 WatermarkGeneratorSupplier.Context context) {
520:             return new AscendingTimestampsWatermarks<>();
521:         }
522: 
523:         @Override
524:         public TimestampAssigner<T> createTimestampAssigner(
525:                 TimestampAssignerSupplier.Context context) {
526:             return (event, timestamp) -> System.currentTimeMillis();
527:         }
528:     }
529: }
