399:     private static String runJobAndGetExternalizedCheckpoint(
400:             StateBackend backend,
401:             @Nullable String externalCheckpoint,
402:             MiniClusterWithClientResource cluster,
403:             RecoveryClaimMode restoreMode)
404:             throws Exception {
405:         // complete at least two checkpoints so that the initial checkpoint can be subsumed
406:         return runJobAndGetExternalizedCheckpoint(
407:                 backend, externalCheckpoint, cluster, restoreMode, new Configuration(), 2, true);
408:     }
409: 
410:     static String runJobAndGetExternalizedCheckpoint(
411:             StateBackend backend,
412:             @Nullable String externalCheckpoint,
413:             MiniClusterWithClientResource cluster,
414:             RecoveryClaimMode recoveryClaimMode,
415:             Configuration jobConfig,
416:             int consecutiveCheckpoints,
417:             boolean retainCheckpoints)
418:             throws Exception {
419:         JobGraph initialJobGraph =
420:                 getJobGraph(backend, externalCheckpoint,
421:                         recoveryClaimMode, jobConfig, retainCheckpoints);
422:         NotifyingInfiniteTupleSource.countDownLatch = new CountDownLatch(PARALLELISM);
423:         cluster.getClusterClient().submitJob(initialJobGraph).get();
424: 
425:         // wait until all sources have been started
426:         NotifyingInfiniteTupleSource.countDownLatch.await();
427: 
428:         waitForCheckpoint(
429:                 initialJobGraph.getJobID(), cluster.getMiniCluster(), consecutiveCheckpoints);
430:         cluster.getClusterClient().cancel(initialJobGraph.getJobID()).get();
431:         waitUntilJobCanceled(initialJobGraph.getJobID(), cluster.getClusterClient());
432: 
433:         return getLatestCompletedCheckpointPath(
434:                         initialJobGraph.getJobID(), cluster.getMiniCluster())
435:                 .<IllegalStateException>orElseThrow(
436:                         () -> {
437:                             throw new IllegalStateException("Checkpoint not generated");
438:                         });
439:     }
