441:     private static JobGraph getJobGraph(
442:             StateBackend backend,
443:             @Nullable String externalCheckpoint,
444:             RecoveryClaimMode recoveryClaimMode,
445:             Configuration jobConfig,
446:             boolean retainCheckpoints) {
447:         final StreamExecutionEnvironment env =
448:                 StreamExecutionEnvironment.getExecutionEnvironment(jobConfig);
449: 
450:         env.enableCheckpointing(500);
451:         env.setStateBackend(backend);
452:         env.setParallelism(PARALLELISM);
453:         env.getCheckpointConfig()
454:                 .setExternalizedCheckpointRetention(
455:                         retainCheckpoints
456:                                 ? ExternalizedCheckpointRetention.RETAIN_ON_CANCELLATION
457:                                 : ExternalizedCheckpointRetention.DELETE_ON_CANCELLATION);
458:         env.setRestartStrategy(RestartStrategies.noRestart());
459: 
460:         env.addSource(new NotifyingInfiniteTupleSource(10_000))
461:                 .assignTimestampsAndWatermarks(IngestionTimeWatermarkStrategy.create())
462:                 .keyBy(0)
463:                 .window(TumblingEventTimeWindows.of(Time.seconds(3)))
464:                 .reduce((value1, value2) -> Tuple2.of(value1.f0, value1.f1 + value2.f1))
465:                 .filter(value -> value.f0.startsWith("Tuple 0"));
466: 
467:         StreamGraph streamGraph = env.getStreamGraph();
468: 
469:         JobGraph jobGraph = streamGraph.getJobGraph();
470: 
471:         // recover from previous iteration?
472:         if (externalCheckpoint != null) {
473:             jobGraph.setSavepointRestoreSettings(
474:                     SavepointRestoreSettings.forPath(externalCheckpoint, false, recoveryClaimMode));
475:         }
476: 
477:         return jobGraph;
478:     }
