480:     /**
481:      * Infinite source which notifies when all of its sub tasks have been started via the count down
482:      * latch.
483:      */
484:     public static class NotifyingInfiniteTupleSource
485:             extends ManualWindowSpeedITCase.InfiniteTupleSource {
486: 
487:         private static final long serialVersionUID = 8120981235081181746L;
488: 
489:         private static CountDownLatch countDownLatch;
490: 
491:         public NotifyingInfiniteTupleSource(int numKeys) {
492:             super(numKeys);
493:         }
494: 
495:         @Override
496:         public void run(SourceContext<Tuple2<String, Integer>> out) throws Exception {
497:             if (countDownLatch != null) {
498:                 countDownLatch.countDown();
499:             }
500: 
501:             super.run(out);
502:         }
503:     }
504: 
505:     /**
506:      * This {@link WatermarkStrategy} assigns the current system time as the event-time timestamp.
507:      * In a real use case you should use proper timestamps and an appropriate {@link
508:      * WatermarkStrategy}.
509:      */
510:     private static class IngestionTimeWatermarkStrategy<T> implements WatermarkStrategy<T> {
511: 
512:         private IngestionTimeWatermarkStrategy() {}
513: 
514:         public static <T> IngestionTimeWatermarkStrategy<T> create() {
515:             return new IngestionTimeWatermarkStrategy<>();
516:         }
517: 
518:         @Override
519:         public WatermarkGenerator<T> createWatermarkGenerator(
520:                 WatermarkGeneratorSupplier.Context context) {
521:             return new AscendingTimestampsWatermarks<>();
522:         }
523: 
524:         @Override
525:         public TimestampAssigner<T> createTimestampAssigner(
526:                 TimestampAssignerSupplier.Context context) {
527:             return (event, timestamp) -> System.currentTimeMillis();
528:         }
529:     }
530: }
