584:     private HighAvailabilityServicesFactory createHighAvailabilityServicesFactory(
585:             Configuration configuration) {
586:         final HaServices customMiniClusterHaServicesMode = miniClusterConfiguration.getHaServices();
587:         if (customMiniClusterHaServicesMode == HaServices.WITH_LEADERSHIP_CONTROL) {
588:             // special feature of MiniClusters to allow the control of leadership
589:             // EmbeddedLeaderElection requires a single instance for leader election across multiple
590:             // JobManager instances on the same JVM (after FLINK-24038 was introduced); therefore,
591:             // SingletonHighAvailabilityServicesFactory is utilized here
592:             return new SingletonHighAvailabilityServicesFactory(
593:                     (config, embeddedLeaderElectionExecutor) ->
594:                             new EmbeddedHaServicesWithLeadershipControl(
595:                                     embeddedLeaderElectionExecutor));
596:         } else if (customMiniClusterHaServicesMode != HaServices.CONFIGURED) {
597:             throw new IllegalConfigurationException(
598:                     "Unknown HA Services Mode configured in MiniCluster configuration: "
599:                             + customMiniClusterHaServicesMode);
600:         }
601: 
602:         final HighAvailabilityMode highAvailabilityMode =
603:                 HighAvailabilityMode.fromConfig(configuration);
604:         if (highAvailabilityMode == HighAvailabilityMode.NONE) {
605:             // basic EmbeddedLeaderElection requires a single instance for leader election across
606:             // multiple JobManager instances on the same JVM (after FLINK-24038 was introduced);
607:             // therefore, SingletonHighAvailabilityServicesFactory is utilized here
608:             return new SingletonHighAvailabilityServicesFactory(
609:                     (config, embeddedLeaderElectionExecutor) ->
610:                             new EmbeddedHaServices(embeddedLeaderElectionExecutor));
611:         } else {
612:             return new RegularHighAvailabilityServicesFactory();
613:         }
614:     }
