661:     private CompletableFuture<Void> closeInternal(boolean cleanupHaData) {
662:         synchronized (lock) {
663:             if (running) {
664:                 LOG.info("Shutting down Flink Mini Cluster");
665:                 try {
666:                     final long shutdownTimeoutMillis =
667:                             miniClusterConfiguration
668:                                     .getConfiguration()
669:                                     .get(ClusterOptions.CLUSTER_SERVICES_SHUTDOWN_TIMEOUT)
670:                                     .toMillis();
671:                     final int numComponents = 2 + miniClusterConfiguration.getNumTaskManagers();
672:                     final Collection<CompletableFuture<Void>> componentTerminationFutures =
673:                             new ArrayList<>(numComponents);
674: 
675:                     componentTerminationFutures.addAll(terminateTaskManagers());
676: 
677:                     componentTerminationFutures.add(shutDownResourceManagerComponents());
678: 
679:                     final FutureUtils.ConjunctFuture<Void> componentsTerminationFuture =
680:                             FutureUtils.completeAll(componentTerminationFutures);
681: 
682:                     final CompletableFuture<Void> metricSystemTerminationFuture =
683:                             FutureUtils.composeAfterwards(
684:                                     componentsTerminationFuture, this::closeMetricSystem);
685: 
686:                     final CompletableFuture<Void> rpcServicesTerminationFuture =
687:                             FutureUtils.composeAfterwards(
688:                                     metricSystemTerminationFuture, this::terminateRpcServices);
689: 
690:                     final CompletableFuture<Void> remainingServicesTerminationFuture =
691:                             FutureUtils.runAfterwards(
692:                                     rpcServicesTerminationFuture,
693:                                     () -> terminateMiniClusterServices(cleanupHaData));
694: 
695:                     final CompletableFuture<Void> executorsTerminationFuture =
696:                             FutureUtils.composeAfterwards(
697:                                     remainingServicesTerminationFuture,
698:                                     () -> terminateExecutors(shutdownTimeoutMillis));
699: 
700:                     final CompletableFuture<Void> deleteDirectoriesFuture =
701:                             FutureUtils.runAfterwards(
702:                                     executorsTerminationFuture, this::deleteDirectories);
703: 
704:                     deleteDirectoriesFuture.whenComplete(
705:                             (Void ignored, Throwable throwable) -> {
706:                                 if (throwable != null) {
707:                                     terminationFuture.completeExceptionally(
708:                                             ExceptionUtils.stripCompletionException(throwable));
709:                                 } else {
710:                                     terminationFuture.complete(null);
711:                                 }
712:                             });
713:                 } finally {
714:                     running = false;
715:                 }
716:             }
717: 
718:             return terminationFuture;
719:         }
720:     }
721: 
722:     private CompletableFuture<Void> closeMetricSystem() {
723:         synchronized (lock) {
724:             final ArrayList<CompletableFuture<Void>> terminationFutures = new ArrayList<>(2);
725: 
726:             if (processMetricGroup != null) {
727:                 processMetricGroup.close();
728:                 processMetricGroup = null;
729:             }
730: 
731:             // metrics shutdown
732:             if (metricRegistry != null) {
733:                 terminationFutures.add(metricRegistry.closeAsync());
734:                 metricRegistry = null;
735:             }
736: 
737:             return FutureUtils.completeAll(terminationFutures);
738:         }
739:     }
