1008:     /**
1009:      * This method executes a job in detached mode. The method returns immediately after the job has
1010:      * been added to the
1011:      *
1012:      * @param job The Flink job to execute
1013:      * @throws JobExecutionException Thrown if anything went amiss during initial job launch, or if
1014:      *     the job terminally failed.
1015:      */
1016:     public void runDetached(JobGraph job) throws JobExecutionException, InterruptedException {
1017:         checkNotNull(job, "job is null");
1018: 
1019:         final CompletableFuture<JobSubmissionResult> submissionFuture = submitJob(job);
1020: 
1021:         try {
1022:             submissionFuture.get();
1023:         } catch (ExecutionException e) {
1024:             throw new JobExecutionException(
1025:                     job.getJobID(), ExceptionUtils.stripExecutionException(e));
1026:         }
1027:     }
