314:     /**
315:      * Starts the mini cluster, based on the configured properties.
316:      *
317:      * @throws Exception This method passes on any exception that occurs during the startup of the
318:      *     mini cluster.
319:      */
320:     public void start() throws Exception {
321:         synchronized (lock) {
322:             checkState(!running, "MiniCluster is already running");
323: 
324:             LOG.info("Starting Flink Mini Cluster");
325:             LOG.debug("Using configuration {}", miniClusterConfiguration);
326: 
327:             final Configuration configuration = miniClusterConfiguration.getConfiguration();
328:             final boolean useSingleRpcService =
329:                     miniClusterConfiguration.getRpcServiceSharing() == RpcServiceSharing.SHARED;
330: 
331:             try {
332:                 workingDirectory =
333:                         WorkingDirectory.create(
334:                                 ClusterEntrypointUtils.generateWorkingDirectoryFile(
335:                                         configuration,
336:                                         Optional.of(PROCESS_WORKING_DIR_BASE),
337:                                         "minicluster_" + ResourceID.generate()));
338: 
339:                 initializeIOFormatClasses(configuration);
340: 
341:                 rpcSystem = rpcSystemSupplier.get();
342: 
343:                 LOG.info("Starting Metrics Registry");
344:                 metricRegistry =
345:                         createMetricRegistry(
346:                                 configuration,
347:                                 rpcSystem.deref().getMaximumMessageSizeInBytes(configuration));
348: 
349:                 // bring up all the RPC services
350:                 LOG.info("Starting RPC Service(s)");
351: 
352:                 final RpcServiceFactory dispatcherResourceManagerComponentRpcServiceFactory;
353:                 final RpcService metricQueryServiceRpcService;
354: 
355:                 if (useSingleRpcService) {
356:                     // we always need the 'commonRpcService' for auxiliary calls
357:                     commonRpcService = createLocalRpcService(configuration, rpcSystem.deref());
358:                     final CommonRpcServiceFactory commonRpcServiceFactory =
359:                             new CommonRpcServiceFactory(commonRpcService);
360:                     taskManagerRpcServiceFactory = commonRpcServiceFactory;
361:                     dispatcherResourceManagerComponentRpcServiceFactory = commonRpcServiceFactory;
362:                     metricQueryServiceRpcService =
363:                             MetricUtils.startLocalMetricsRpcService(
364:                                     configuration, rpcSystem.deref());
365:                 } else {
366: 
367:                     // start a new service per component, possibly with custom bind addresses
368:                     final String jobManagerExternalAddress =
369:                             miniClusterConfiguration.getJobManagerExternalAddress();
370:                     final String taskManagerExternalAddress =
371:                             miniClusterConfiguration.getTaskManagerExternalAddress();
372:                     final String jobManagerExternalPortRange =
373:                             miniClusterConfiguration.getJobManagerExternalPortRange();
374:                     final String taskManagerExternalPortRange =
375:                             miniClusterConfiguration.getTaskManagerExternalPortRange();
376:                     final String jobManagerBindAddress =
377:                             miniClusterConfiguration.getJobManagerBindAddress();
378:                     final String taskManagerBindAddress =
379:                             miniClusterConfiguration.getTaskManagerBindAddress();
380: 
381:                     dispatcherResourceManagerComponentRpcServiceFactory =
382:                             new DedicatedRpcServiceFactory(
383:                                     configuration,
384:                                     jobManagerExternalAddress,
385:                                     jobManagerExternalPortRange,
386:                                     jobManagerBindAddress,
387:                                     rpcSystem.deref());
388:                     taskManagerRpcServiceFactory =
389:                             new DedicatedRpcServiceFactory(
390:                                     configuration,
391:                                     taskManagerExternalAddress,
392:                                     taskManagerExternalPortRange,
393:                                     taskManagerBindAddress,
394:                                     rpcSystem.deref());
395: 
396:                     // we always need the 'commonRpcService' for auxiliary calls
397:                     // bind to the JobManager address with port 0
398:                     commonRpcService =
399:                             createRemoteRpcService(
400:                                     configuration, jobManagerBindAddress, 0, rpcSystem.deref());
401:                     metricQueryServiceRpcService =
402:                             MetricUtils.startRemoteMetricsRpcService(
403:                                     configuration,
404:                                     commonRpcService.getAddress(),
405:                                     null,
406:                                     rpcSystem.deref());
407:                 }
408: 
409:                 metricRegistry.startQueryService(metricQueryServiceRpcService, null);
410: 
411:                 processMetricGroup =
412:                         MetricUtils.instantiateProcessMetricGroup(
413:                                 metricRegistry,
414:                                 RpcUtils.getHostname(commonRpcService),
415:                                 ConfigurationUtils.getSystemResourceMetricsProbingInterval(
416:                                         configuration));
417: 
418:                 ioExecutor =
419:                         Executors.newFixedThreadPool(
420:                                 ClusterEntrypointUtils.getPoolSize(configuration),
421:                                 new ExecutorThreadFactory("mini-cluster-io"));
422: 
423:                 delegationTokenManager =
424:                         DefaultDelegationTokenManagerFactory.create(
425:                                 configuration,
426:                                 miniClusterConfiguration.getPluginManager(),
427:                                 commonRpcService.getScheduledExecutor(),
428:                                 ioExecutor);
429:                 // Obtaining delegation tokens and propagating them to the local JVM receivers in a
430:                 // one-time fashion is required because BlobServer may connect to external file
431:                 // systems
432:                 delegationTokenManager.obtainDelegationTokens();
433: 
434:                 delegationTokenReceiverRepository =
435:                         new DelegationTokenReceiverRepository(
436:                                 configuration, miniClusterConfiguration.getPluginManager());
437: 
438:                 haServicesFactory = createHighAvailabilityServicesFactory(configuration);
439: 
440:                 haServices = createHighAvailabilityServices(configuration, ioExecutor);
441: 
442:                 blobServer =
443:                         BlobUtils.createBlobServer(
444:                                 configuration,
445:                                 Reference.borrowed(workingDirectory.getBlobStorageDirectory()),
446:                                 haServices.createBlobStore());
447:                 blobServer.start();
448: 
449:                 heartbeatServices = HeartbeatServices.fromConfiguration(configuration);
450: 
451:                 blobCacheService =
452:                         BlobUtils.createBlobCacheService(
453:                                 configuration,
454:                                 Reference.borrowed(workingDirectory.getBlobStorageDirectory()),
455:                                 haServices.createBlobStore(),
456:                                 new InetSocketAddress(
457:                                         InetAddress.getLocalHost(), blobServer.getPort()));
458: 
459:                 startTaskManagers();
460: 
461:                 MetricQueryServiceRetriever metricQueryServiceRetriever =
462:                         new RpcMetricQueryServiceRetriever(
463:                                 metricRegistry.getMetricQueryServiceRpcService());
464: 
465:                 setupDispatcherResourceManagerComponents(
466:                         configuration,
467:                         dispatcherResourceManagerComponentRpcServiceFactory,
468:                         metricQueryServiceRetriever);
469: 
470:                 resourceManagerLeaderRetriever = haServices.getResourceManagerLeaderRetriever();
471:                 dispatcherLeaderRetriever = haServices.getDispatcherLeaderRetriever();
472:                 clusterRestEndpointLeaderRetrievalService =
473:                         haServices.getClusterRestEndpointLeaderRetriever();
474: 
475:                 dispatcherGatewayRetriever =
476:                         new RpcGatewayRetriever<>(
477:                                 commonRpcService,
478:                                 DispatcherGateway.class,
479:                                 DispatcherId::fromUuid,
480:                                 new ExponentialBackoffRetryStrategy(
481:                                         21, Duration.ofMillis(5L), Duration.ofMillis(20L)));
482:                 resourceManagerGatewayRetriever =
483:                         new RpcGatewayRetriever<>(
484:                                 commonRpcService,
485:                                 ResourceManagerGateway.class,
486:                                 ResourceManagerId::fromUuid,
487:                                 new ExponentialBackoffRetryStrategy(
488:                                         21, Duration.ofMillis(5L), Duration.ofMillis(20L)));
489:                 webMonitorLeaderRetriever = new LeaderRetriever();
490: 
491:                 resourceManagerLeaderRetriever.start(resourceManagerGatewayRetriever);
492:                 dispatcherLeaderRetriever.start(dispatcherGatewayRetriever);
493:                 clusterRestEndpointLeaderRetrievalService.start(webMonitorLeaderRetriever);
494:             } catch (Exception e) {
495:                 // cleanup everything
496:                 try {
497:                     close();
498:                 } catch (Exception ee) {
499:                     e.addSuppressed(ee);
500:                 }
501:                 throw e;
502:             }
503: 
504:             // create a new termination future
505:             terminationFuture = new CompletableFuture<>();
506: 
507:             // now officially mark this as running
508:             running = true;
509: 
510:             LOG.info("Flink Mini Cluster started successfully");
511:         }
512:     }
