514:     @GuardedBy("lock")
515:     private void setupDispatcherResourceManagerComponents(
516:             Configuration configuration,
517:             RpcServiceFactory dispatcherResourceManagerComponentRpcServiceFactory,
518:             MetricQueryServiceRetriever metricQueryServiceRetriever)
519:             throws Exception {
520:         dispatcherResourceManagerComponents.addAll(
521:                 createDispatcherResourceManagerComponents(
522:                         configuration,
523:                         dispatcherResourceManagerComponentRpcServiceFactory,
524:                         blobServer,
525:                         heartbeatServices,
526:                         delegationTokenManager,
527:                         metricRegistry,
528:                         metricQueryServiceRetriever,
529:                         new ShutDownFatalErrorHandler()));
