741:     @GuardedBy("lock")
742:     private void startTaskManagers() throws Exception {
743:         final int numTaskManagers = miniClusterConfiguration.getNumTaskManagers();
744: 
745:         LOG.info("Starting {} TaskManager(s)", numTaskManagers);
746: 
747:         for (int i = 0; i < numTaskManagers; i++) {
748:             startTaskManager();
749:         }
750:     }
