752:     /**
753:      * Starts additional TaskManager process.
754:      *
755:      * <p>When the MiniCluster starts up, it always starts {@link
756:      * MiniClusterConfiguration#getNumTaskManagers} TaskManagers. All TaskManagers are indexed from
757:      * 0 to the number of TaskManagers, started so far, minus one. This method starts a TaskManager
758:      * with the next index which is the number of TaskManagers, started so far. The index always
759:      * increases with each new started TaskManager. The indices of terminated TaskManagers are not
760:      * reused after {@link #terminateTaskManager(int)}.
761:      */
762:     public void startTaskManager() throws Exception {
763:         synchronized (lock) {
764:             final Configuration configuration = miniClusterConfiguration.getConfiguration();
765: 
766:             final TaskExecutor taskExecutor =
767:                     TaskManagerRunner.startTaskManager(
768:                             configuration,
769:                             new ResourceID(UUID.randomUUID().toString()),
770:                             taskManagerRpcServiceFactory.createRpcService(),
771:                             haServices,
772:                             heartbeatServices,
773:                             metricRegistry,
774:                             blobCacheService,
775:                             useLocalCommunication(),
776:                             ExternalResourceInfoProvider.NO_EXTERNAL_RESOURCES,
777:                             workingDirectory.createSubWorkingDirectory("tm_" + taskManagers.size()),
778:                             taskManagerTerminatingFatalErrorHandlerFactory.create(
779:                                     taskManagers.size()),
780:                             delegationTokenReceiverRepository);
781: 
782:             taskExecutor.start();
783:             taskManagers.add(taskExecutor);
784:         }
785:     }
