807:     @GuardedBy("lock")
808:     private Collection<? extends CompletableFuture<Void>> terminateTaskManagers() {
809:         final Collection<CompletableFuture<Void>> terminationFutures =
810:                 new ArrayList<>(taskManagers.size());
811:         for (int i = 0; i < taskManagers.size(); i++) {
