1066:     public CompletableFuture<JobSubmissionResult> submitJob(JobGraph jobGraph) {
1067:         // When MiniCluster uses the local RPC, the provided JobGraph is passed directly to the
1068:         // Dispatcher. This means that any mutations to the JG can affect the Dispatcher behaviour,
1069:         // so we rather clone it to guard against this.
1070:         final JobGraph clonedJobGraph = InstantiationUtil.cloneUnchecked(jobGraph);
1071:         checkRecoveryClaimModeForChangelogStateBackend(clonedJobGraph);
1072:         final CompletableFuture<DispatcherGateway> dispatcherGatewayFuture =
1073:                 getDispatcherGatewayFuture();
1074:         final CompletableFuture<InetSocketAddress> blobServerAddressFuture =
1075:                 createBlobServerAddress(dispatcherGatewayFuture);
1076:         final CompletableFuture<Void> jarUploadFuture =
1077:                 uploadAndSetJobFiles(blobServerAddressFuture, clonedJobGraph);
1078:         final CompletableFuture<Acknowledge> acknowledgeCompletableFuture =
1079:                 jarUploadFuture
1080:                         .thenCombine(
1081:                                 dispatcherGatewayFuture,
1082:                                 (Void ack, DispatcherGateway dispatcherGateway) ->
1083:                                         dispatcherGateway.submitJob(clonedJobGraph, rpcTimeout))
1084:                         .thenCompose(Function.identity());
1085:         return acknowledgeCompletableFuture.thenApply(
1086:                 (Acknowledge ignored) -> new JobSubmissionResult(clonedJobGraph.getJobID()));
1087:     }
