1089:     // HACK: temporary hack to make the randomized changelog state backend tests work with forced
1090:     // full snapshots. This option should be removed once changelog state backend supports forced
1091:     // full snapshots
1092:     private void checkRecoveryClaimModeForChangelogStateBackend(JobGraph jobGraph) {
1093:         final SavepointRestoreSettings savepointRestoreSettings =
1094:                 jobGraph.getSavepointRestoreSettings();
1095:         if (overrideRestoreModeForChangelogStateBackend
1096:                 && savepointRestoreSettings.getRecoveryClaimMode() == RecoveryClaimMode.NO_CLAIM) {
1097:             final Configuration conf = new Configuration();
1098:             SavepointRestoreSettings.toConfiguration(savepointRestoreSettings, conf);
1099:             conf.set(StateRecoveryOptions.RECOVERY_CLAIM_MODE, RecoveryClaimMode.LEGACY);
1100:             jobGraph.setSavepointRestoreSettings(SavepointRestoreSettings.fromConfiguration(conf));
1101:         }
1102:     }
