1247:     @GuardedBy("lock")
1248:     private CompletableFuture<Void> shutDownResourceManagerComponents() {
1249: 
1250:         final Collection<CompletableFuture<Void>> terminationFutures =
1251:                 new ArrayList<>(dispatcherResourceManagerComponents.size());
1252: 
1253:         for (DispatcherResourceManagerComponent dispatcherResourceManagerComponent :
1254:                 dispatcherResourceManagerComponents) {
1255:             terminationFutures.add(dispatcherResourceManagerComponent.closeAsync());
1256:         }
1257: 
1258:         final FutureUtils.ConjunctFuture<Void> dispatcherTerminationFuture =
1259:                 FutureUtils.completeAll(terminationFutures);
1260: 
1261:         return FutureUtils.runAfterwards(
1262:                 dispatcherTerminationFuture,
1263:                 () -> {
1264:                     Exception exception = null;
1265: 
1266:                     synchronized (lock) {
1267:                         if (resourceManagerLeaderRetriever != null) {
1268:                             try {
1269:                                 resourceManagerLeaderRetriever.stop();
1270:                             } catch (Exception e) {
1271:                                 exception = ExceptionUtils.firstOrSuppressed(e, exception);
1272:                             }
1273: 
1274:                             resourceManagerLeaderRetriever = null;
1275:                         }
1276: 
1277:                         if (dispatcherLeaderRetriever != null) {
1278:                             try {
1279:                                 dispatcherLeaderRetriever.stop();
1280:                             } catch (Exception e) {
1281:                                 exception = ExceptionUtils.firstOrSuppressed(e, exception);
1282:                             }
1283: 
1284:                             dispatcherLeaderRetriever = null;
1285:                         }
1286: 
1287:                         if (clusterRestEndpointLeaderRetrievalService != null) {
1288:                             try {
1289:                                 clusterRestEndpointLeaderRetrievalService.stop();
1290:                             } catch (Exception e) {
1291:                                 exception = ExceptionUtils.firstOrSuppressed(e, exception);
1292:                             }
1293: 
1294:                             clusterRestEndpointLeaderRetrievalService = null;
1295:                         }
1296:                     }
1297: 
1298:                     if (exception != null) {
1299:                         throw exception;
1300:                     }
1301:                 });
1302:     }
