1351:         synchronized (lock) {
1352:             final int numRpcServices = 1 + rpcServices.size();
1353: 
1354:             final Collection<CompletableFuture<?>> rpcTerminationFutures =
1355:                     new ArrayList<>(numRpcServices);
1356: 
1357:             rpcTerminationFutures.add(commonRpcService.closeAsync());
1358: 
1359:             for (RpcService rpcService : rpcServices) {
1360:                 rpcTerminationFutures.add(rpcService.closeAsync());
1361:             }
1362: 
1363:             commonRpcService = null;
1364:             rpcServices.clear();
1365: 
1366:             return FutureUtils.completeAll(rpcTerminationFutures);
1367:         }
