307:     private String submitJobAndTakeSavepoint(
308:             MiniClusterWithClientResource cluster,
309:             SavepointFormatType formatType,
310:             int checkpointBeforeSavepoint,
311:             Configuration config)
312:             throws Exception {
313:         final JobGraph jobGraph = createJobGraph(config);
314: 
315:         final JobID jobId = jobGraph.getJobID();
316:         ClusterClient<?> client = cluster.getClusterClient();
317:         client.submitJob(jobGraph).get();
318:         waitForAllTaskRunning(cluster.getMiniCluster(), jobId, false);
319: 
320:         for (int i = 0; i < checkpointBeforeSavepoint; i++) {
321:             cluster.getMiniCluster().triggerCheckpoint(jobId).get();
322:         }
323: 
324:         return client.stopWithSavepoint(
325:                         jobId, false, originalSavepointDir.toUri().toString(), formatType)
326:                 .get();
