329:     private static JobGraph createJobGraph(Configuration config) {
330:         StreamExecutionEnvironment env =
331:                 StreamExecutionEnvironment.getExecutionEnvironment(
332:                         /* pass configuration to prevent any conflicting randomization*/
333:                         config);
334:         env.setParallelism(4);
335:         env.setRuntimeMode(RuntimeExecutionMode.STREAMING);
336:         env.disableOperatorChaining();
337: 
338:         env.fromSequence(Long.MIN_VALUE, Long.MAX_VALUE)
339:                 .keyBy(i -> i % 1000)
340:                 .map(new StatefulCounter())
341:                 .sinkTo(new DiscardingSink<>());
342: 
343:         return env.getStreamGraph().getJobGraph();
344:     }
