388:     protected StreamTask(
389:             Environment environment,
390:             @Nullable TimerService timerService,
391:             Thread.UncaughtExceptionHandler uncaughtExceptionHandler,
392:             StreamTaskActionExecutor actionExecutor,
393:             TaskMailbox mailbox)
394:             throws Exception {
395:         // The registration of all closeable resources. The order of registration is important.
396:         resourceCloser = new AutoCloseableRegistry();
397:         try {
398:             this.environment = environment;
399:             this.configuration = new StreamConfig(environment.getTaskConfiguration());
400: 
401:             // Initialize mailbox metrics
402:             MailboxMetricsController mailboxMetricsControl =
403:                     new MailboxMetricsController(
404:                             environment.getMetricGroup().getIOMetricGroup().getMailboxLatency(),
405:                             environment
406:                                     .getMetricGroup()
407:                                     .getIOMetricGroup()
408:                                     .getNumMailsProcessedCounter());
409:             environment
410:                     .getMetricGroup()
411:                     .getIOMetricGroup()
412:                     .registerMailboxSizeSupplier(() -> mailbox.size());
413: 
414:             this.mailboxProcessor =
415:                     new MailboxProcessor(
416:                             this::processInput, mailbox, actionExecutor, mailboxMetricsControl);
417: 
418:             // Should be closed last.
419:             resourceCloser.registerCloseable(mailboxProcessor);
420: 
421:             this.channelIOExecutor =
422:                     MdcUtils.scopeToJob(
423:                             environment.getJobID(),
424:                             Executors.newSingleThreadExecutor(
425:                                     new ExecutorThreadFactory("channel-state-unspilling")));
426:             resourceCloser.registerCloseable(channelIOExecutor::shutdown);
427: 
428:             this.recordWriter = createRecordWriterDelegate(configuration, environment);
429:             // Release the output resources. this method should never fail.
430:             resourceCloser.registerCloseable(this::releaseOutputResources);
431:             // If the operators won't be closed explicitly, register it to a hard close.
432:             resourceCloser.registerCloseable(this::closeAllOperators);
433:             resourceCloser.registerCloseable(this::cleanUpInternal);
434: 
435:             this.actionExecutor = Preconditions.checkNotNull(actionExecutor);
436:             this.mainMailboxExecutor = mailboxProcessor.getMainMailboxExecutor();
437:             this.asyncExceptionHandler = new StreamTaskAsyncExceptionHandler(environment);
438: 
439:             // With maxConcurrentCheckpoints + 1 we more or less adhere to the
440:             // maxConcurrentCheckpoints configuration, but allow for a small leeway with allowing
441:             // for simultaneous N ongoing concurrent checkpoints and for example clean up of one
442:             // aborted one.
443:             this.asyncOperationsThreadPool =
444:                     MdcUtils.scopeToJob(
445:                             getEnvironment().getJobID(),
446:                             new ThreadPoolExecutor(
447:                                     0,
448:                                     configuration.getMaxConcurrentCheckpoints() + 1,
449:                                     60L,
450:                                     TimeUnit.SECONDS,
451:                                     new LinkedBlockingQueue<>(),
452:                                     new ExecutorThreadFactory(
453:                                             "AsyncOperations", uncaughtExceptionHandler)));
454: 
455:             // Register all asynchronous checkpoint threads.
456:             resourceCloser.registerCloseable(this::shutdownAsyncThreads);
457:             resourceCloser.registerCloseable(cancelables);
458: 
459:             environment.setMainMailboxExecutor(mainMailboxExecutor);
460:             environment.setAsyncOperationsThreadPool(asyncOperationsThreadPool);
461: 
462:             this.stateBackend = createStateBackend();
463:             this.checkpointStorage = createCheckpointStorage(stateBackend);
464:             this.changelogWriterAvailabilityProvider =
465:                     environment.getTaskStateManager().getStateChangelogStorage() == null
466:                             ? null
467:                             : environment
468:                                     .getTaskStateManager()
469:                                     .getStateChangelogStorage()
470:                                     .getAvailabilityProvider();
471: 
472:             CheckpointStorageAccess checkpointStorageAccess =
473:                     checkpointStorage.createCheckpointStorage(getEnvironment().getJobID());
474:             checkpointStorageAccess =
475:                     tryApplyFileMergingCheckpoint(
476:                             checkpointStorageAccess,
477:                             environment.getTaskStateManager().getFileMergingSnapshotManager());
478:             environment.setCheckpointStorageAccess(checkpointStorageAccess);
479: 
480:             // if the clock is not already set, then assign a default TimeServiceProvider
481:             if (timerService == null) {
482:                 this.timerService = createTimerService("Time Trigger for " + getName());
483:             } else {
484:                 this.timerService = timerService;
485:             }
486: 
487:             this.systemTimerService = createTimerService("System Time Trigger for " + getName());
488:             final CheckpointStorageAccess finalCheckpointStorageAccess = checkpointStorageAccess;
489: 
490:             ChannelStateWriter channelStateWriter =
491:                     configuration.isUnalignedCheckpointsEnabled()
492:                             ? openChannelStateWriter(
493:                                     getName(),
494:                                     // Note: don't pass checkpointStorageAccess directly to channel
495:                                     // state writer.
496:                                     // The fileSystem of checkpointStorageAccess may be an instance
497:                                     // of SafetyNetWrapperFileSystem, which close all held streams
498:                                     // when thread exits. Channel state writers are invoked in other
499:                                     // threads instead of task thread, therefore channel state
500:                                     // writer cannot share file streams directly, otherwise
501:                                     // conflicts will occur on job exit.
502:                                     () -> {
503:                                         if (finalCheckpointStorageAccess
504:                                                 instanceof FsMergingCheckpointStorageAccess) {
505:                                             // FsMergingCheckpointStorageAccess using unguarded
506:                                             // fileSystem, which can be shared.
507:                                             return finalCheckpointStorageAccess;
508:                                         } else {
509:                                             // Other checkpoint storage access should be lazily
510:                                             // initialized to avoid sharing.
511:                                             return checkpointStorage.createCheckpointStorage(
512:                                                     getEnvironment().getJobID());
513:                                         }
514:                                     },
515:                                     environment,
516:                                     configuration.getMaxSubtasksPerChannelStateFile())
517:                             : ChannelStateWriter.NO_OP;
518:             this.subtaskCheckpointCoordinator =
519:                     new SubtaskCheckpointCoordinatorImpl(
520:                             checkpointStorageAccess,
521:                             getName(),
522:                             actionExecutor,
523:                             getAsyncOperationsThreadPool(),
524:                             environment,
525:                             this,
526:                             this::prepareInputSnapshot,
527:                             configuration.getMaxConcurrentCheckpoints(),
528:                             channelStateWriter,
529:                             configuration
530:                                     .getConfiguration()
531:                                     .get(
532:                                             CheckpointingOptions
533:                                                     .ENABLE_CHECKPOINTS_AFTER_TASKS_FINISH),
534:                             BarrierAlignmentUtil.createRegisterTimerCallback(
535:                                     mainMailboxExecutor, systemTimerService),
536:                             environment.getTaskStateManager().getFileMergingSnapshotManager());
537:             resourceCloser.registerCloseable(subtaskCheckpointCoordinator::close);
538: 
539:             // Register to stop all timers and threads. Should be closed first.
540:             resourceCloser.registerCloseable(this::tryShutdownTimerService);
541: 
542:             injectChannelStateWriterIntoChannels();
543: 
544:             environment.getMetricGroup().getIOMetricGroup().setEnableBusyTime(true);
545:             Configuration taskManagerConf = environment.getTaskManagerInfo().getConfiguration();
546: 
547:             this.bufferDebloatPeriod = taskManagerConf.get(BUFFER_DEBLOAT_PERIOD).toMillis();
548:             mailboxMetricsControl.setupLatencyMeasurement(systemTimerService, mainMailboxExecutor);
549:         } catch (Exception ex) {
550:             try {
551:                 resourceCloser.close();
552:             } catch (Throwable throwable) {
553:                 ex.addSuppressed(throwable);
554:             }
555:             throw ex;
556:         }
557:     }
