629:     /**
630:      * This method implements the default action of the task (e.g. processing one event from the
631:      * input). Implementations should (in general) be non-blocking.
632:      *
633:      * @param controller controller object for collaborative interaction between the action and the
634:      *     stream task.
635:      * @throws Exception on any problems in the action.
636:      */
637:     protected void processInput(MailboxDefaultAction.Controller controller) throws Exception {
638:         DataInputStatus status = inputProcessor.processInput();
639:         switch (status) {
640:             case MORE_AVAILABLE:
641:                 if (taskIsAvailable()) {
642:                     return;
643:                 }
644:                 break;
645:             case NOTHING_AVAILABLE:
646:                 break;
647:             case END_OF_RECOVERY:
648:                 throw new IllegalStateException("We should not receive this event here.");
649:             case STOPPED:
650:                 endData(StopMode.NO_DRAIN);
651:                 return;
652:             case END_OF_DATA:
653:                 endData(StopMode.DRAIN);
654:                 notifyEndOfData();
655:                 return;
656:             case END_OF_INPUT:
657:                 // Suspend the mailbox processor, it would be resumed in afterInvoke and finished
658:                 // after all records processed by the downstream tasks. We also suspend the default
659:                 // actions to avoid repeat executing the empty default operation (namely process
660:                 // records).
661:                 controller.suspendDefaultAction();
662:                 mailboxProcessor.suspend();
663:                 return;
664:         }
665: 
666:         TaskIOMetricGroup ioMetrics = getEnvironment().getMetricGroup().getIOMetricGroup();
667:         PeriodTimer timer;
668:         CompletableFuture<?> resumeFuture;
669:         if (!recordWriter.isAvailable()) {
670:             timer = new GaugePeriodTimer(ioMetrics.getSoftBackPressuredTimePerSecond());
671:             resumeFuture = recordWriter.getAvailableFuture();
672:         } else if (!inputProcessor.isAvailable()) {
673:             timer = new GaugePeriodTimer(ioMetrics.getIdleTimeMsPerSecond());
674:             resumeFuture = inputProcessor.getAvailableFuture();
675:         } else if (changelogWriterAvailabilityProvider != null
676:                 && !changelogWriterAvailabilityProvider.isAvailable()) {
677:             // waiting for changelog availability is reported as busy
678:             timer = new GaugePeriodTimer(ioMetrics.getChangelogBusyTimeMsPerSecond());
679:             resumeFuture = changelogWriterAvailabilityProvider.getAvailableFuture();
680:         } else {
681:             // data availability has changed in the meantime; retry immediately
682:             return;
683:         }
684:         assertNoException(
685:                 resumeFuture.thenRun(
686:                         new ResumeWrapper(controller.suspendDefaultAction(timer), timer)));
687:     }
