1339:     private boolean triggerUnfinishedChannelsCheckpoint(
1340:             CheckpointMetaData checkpointMetaData, CheckpointOptions checkpointOptions)
1341:             throws Exception {
1342:         Optional<CheckpointBarrierHandler> checkpointBarrierHandler = getCheckpointBarrierHandler();
1343:         checkState(
1344:                 checkpointBarrierHandler.isPresent(),
1345:                 "CheckpointBarrier should exist for tasks with network inputs.");
1346: 
1347:         CheckpointBarrier barrier =
1348:                 new CheckpointBarrier(
1349:                         checkpointMetaData.getCheckpointId(),
1350:                         checkpointMetaData.getTimestamp(),
1351:                         checkpointOptions);
1352: 
1353:         for (IndexedInputGate inputGate : getEnvironment().getAllInputGates()) {
1354:             if (!inputGate.isFinished()) {
1355:                 for (InputChannelInfo channelInfo : inputGate.getUnfinishedChannels()) {
1356:                     checkpointBarrierHandler.get().processBarrier(barrier, channelInfo, true);
1357:                 }
1358:             }
1359:         }
1360: 
1361:         return true;
1362:     }
