1411:     private boolean performCheckpoint(
1412:             CheckpointMetaData checkpointMetaData,
1413:             CheckpointOptions checkpointOptions,
1414:             CheckpointMetricsBuilder checkpointMetrics)
1415:             throws Exception {
1416: 
1417:         final SnapshotType checkpointType = checkpointOptions.getCheckpointType();
1418:         LOG.debug(
1419:                 "Starting checkpoint {} {} on task {}",
1420:                 checkpointMetaData.getCheckpointId(),
1421:                 checkpointType,
1422:                 getName());
1423: 
1424:         if (isRunning) {
1425:             actionExecutor.runThrowing(
1426:                     () -> {
1427:                         if (isSynchronous(checkpointType)) {
1428:                             setSynchronousSavepoint(checkpointMetaData.getCheckpointId());
1429:                         }
1430: 
1431:                         if (areCheckpointsWithFinishedTasksEnabled()
1432:                                 && endOfDataReceived
1433:                                 && this.finalCheckpointMinId == null) {
1434:                             this.finalCheckpointMinId = checkpointMetaData.getCheckpointId();
1435:                         }
1436: 
1437:                         subtaskCheckpointCoordinator.checkpointState(
1438:                                 checkpointMetaData,
1439:                                 checkpointOptions,
1440:                                 checkpointMetrics,
1441:                                 operatorChain,
1442:                                 finishedOperators,
1443:                                 this::isRunning);
1444:                     });
1445: 
1446:             return true;
1447:         } else {
1448:             actionExecutor.runThrowing(
1449:                     () -> {
1450:                         // we cannot perform our checkpoint - let the downstream operators know that
1451:                         // they
1452:                         // should not wait for any input from this operator
1453: 
1454:                         // we cannot broadcast the cancellation markers on the 'operator chain',
1455:                         // because it may not
1456:                         // yet be created
1457:                         final CancelCheckpointMarker message =
1458:                                 new CancelCheckpointMarker(checkpointMetaData.getCheckpointId());
1459:                         recordWriter.broadcastEvent(message);
1460:                     });
1461: 
1462:             return false;
1463:         }
1464:     }
1465: 
1466:     private boolean isSynchronous(SnapshotType checkpointType) {
1467:         return checkpointType.isSavepoint() && ((SavepointType) checkpointType).isSynchronous();
1468:     }
