1537:     private Future<Void> notifyCheckpointOperation(
1538:             RunnableWithException runnable, String description) {
1539:         CompletableFuture<Void> result = new CompletableFuture<>();
1540:         mailboxProcessor
1541:                 .getMailboxExecutor(TaskMailbox.MAX_PRIORITY)
1542:                 .execute(
1543:                         () -> {
1544:                             try {
1545:                                 runnable.run();
1546:                             } catch (Exception ex) {
1547:                                 result.completeExceptionally(ex);
1548:                                 throw ex;
1549:                             }
1550:                             result.complete(null);
1551:                         },
1552:                         description);
1553:         return result;
1554:     }
