1589:     private void tryShutdownTimerService(long timeoutMs, TimerService timerService) {
1590:         if (!timerService.isTerminated()) {
1591:             if (!timerService.shutdownServiceUninterruptible(timeoutMs)) {
1592:                 LOG.warn(
1593:                         "Timer service shutdown exceeded time limit of {} ms while waiting for pending "
1594:                                 + "timers. Will continue with shutdown procedure.",
1595:                         timeoutMs);
