1789:                             environment.getUserCodeClassLoader().asClassLoader());
1790:         } catch (Exception e) {
1791:             ExceptionUtils.rethrow(e);
1792:         }
1793: 
1794:         LOG.debug(
1795:                 "Using partitioner {} for output {} of task {}",
1796:                 outputPartitioner,
1797:                 outputIndex,
1798:                 taskNameWithSubtask);
