1800:         ResultPartitionWriter bufferWriter = environment.getWriter(outputIndex);
1801: 
1802:         // we initialize the partitioner here with the number of key groups (aka max. parallelism)
1803:         if (outputPartitioner instanceof ConfigurableStreamPartitioner) {
1804:             int numKeyGroups = bufferWriter.getNumTargetKeyGroups();
1805:             if (0 < numKeyGroups) {
1806:                 ((ConfigurableStreamPartitioner) outputPartitioner).configure(numKeyGroups);
1807:             }
1808:         }
1809: 
1810:         RecordWriter<SerializationDelegate<StreamRecord<OUT>>> output =
1811:                 new RecordWriterBuilder<SerializationDelegate<StreamRecord<OUT>>>()
1812:                         .setChannelSelector(outputPartitioner)
1813:                         .setTimeout(bufferTimeout)
1814:                         .setTaskName(taskNameWithSubtask)
1815:                         .build(bufferWriter);
