926:     private void scheduleBufferDebloater() {
927:         // See https://issues.apache.org/jira/browse/FLINK-23560
928:         // If there are no input gates, there is no point of calculating the throughput and running
929:         // the debloater. At the same time, for SourceStreamTask using legacy sources and checkpoint
930:         // lock, enqueuing even a single mailbox action can cause performance regression. This is
931:         // especially visible in batch, with disabled checkpointing and no processing time timers.
932:         if (getEnvironment().getAllInputGates().length == 0
933:                 || !environment
934:                         .getTaskManagerInfo()
935:                         .getConfiguration()
936:                         .get(TaskManagerOptions.BUFFER_DEBLOAT_ENABLED)) {
937:             return;
938:         }
939:         systemTimerService.registerTimer(
940:                 systemTimerService.getCurrentProcessingTime() + bufferDebloatPeriod,
941:                 timestamp ->
942:                         mainMailboxExecutor.execute(
943:                                 () -> {
944:                                     debloat();
945:                                     scheduleBufferDebloater();
946:                                 },
947:                                 "Buffer size recalculation"));
948:     }
