1288:     private boolean triggerCheckpointAsyncInMailbox(
1289:             CheckpointMetaData checkpointMetaData, CheckpointOptions checkpointOptions)
1290:             throws Exception {
1291:         FlinkSecurityManager.monitorUserSystemExitForCurrentThread();
1292:         try {
1293:             latestAsyncCheckpointStartDelayNanos =
1294:                     1_000_000
1295:                             * Math.max(
1296:                                     0,
1297:                                     System.currentTimeMillis() - checkpointMetaData.getTimestamp());
1298: 
1299:             // No alignment if we inject a checkpoint
1300:             CheckpointMetricsBuilder checkpointMetrics =
1301:                     new CheckpointMetricsBuilder()
1302:                             .setAlignmentDurationNanos(0L)
1303:                             .setBytesProcessedDuringAlignment(0L)
1304:                             .setCheckpointStartDelayNanos(latestAsyncCheckpointStartDelayNanos);
1305: 
1306:             subtaskCheckpointCoordinator.initInputsCheckpoint(
1307:                     checkpointMetaData.getCheckpointId(), checkpointOptions);
1308: 
1309:             boolean success =
1310:                     performCheckpoint(checkpointMetaData, checkpointOptions, checkpointMetrics);
1311:             if (!success) {
1312:                 declineCheckpoint(checkpointMetaData.getCheckpointId());
1313:             }
1314:             return success;
1315:         } catch (Exception e) {
1316:             // propagate exceptions only if the task is still in "running" state
1317:             if (isRunning) {
1318:                 throw new Exception(
1319:                         "Could not perform checkpoint "
1320:                                 + checkpointMetaData.getCheckpointId()
1321:                                 + " for operator "
1322:                                 + getName()
1323:                                 + '.',
1324:                         e);
1325:             } else {
1326:                 LOG.debug(
1327:                         "Could not perform checkpoint {} for operator {} while the "
1328:                                 + "invokable was not in state running.",
1329:                         checkpointMetaData.getCheckpointId(),
1330:                         getName(),
1331:                         e);
1332:                 return false;
1333:             }
1334:         } finally {
1335:             FlinkSecurityManager.unmonitorUserSystemExitForCurrentThread();
1336:         }
1337:     }
