1773:     @SuppressWarnings("unchecked")
1774:     private static <OUT> RecordWriter<SerializationDelegate<StreamRecord<OUT>>> createRecordWriter(
1775:             NonChainedOutput streamOutput,
1776:             int outputIndex,
1777:             Environment environment,
1778:             String taskNameWithSubtask,
1779:             long bufferTimeout) {
1780: 
1781:         StreamPartitioner<OUT> outputPartitioner = null;
1782: 
1783:         // Clones the partition to avoid multiple stream edges sharing the same stream partitioner,
1784:         // like the case of https://issues.apache.org/jira/browse/FLINK-14087.
1785:         try {
1786:             outputPartitioner =
1787:                     InstantiationUtil.clone(
1788:                             (StreamPartitioner<OUT>) streamOutput.getPartitioner(),
1789:                             environment.getUserCodeClassLoader().asClassLoader());
1790:         } catch (Exception e) {
1791:             ExceptionUtils.rethrow(e);
1792:         }
1793: 
1794:         LOG.debug(
1795:                 "Using partitioner {} for output {} of task {}",
1796:                 outputPartitioner,
1797:                 outputIndex,
1798:                 taskNameWithSubtask);
1799: 
1800:         ResultPartitionWriter bufferWriter = environment.getWriter(outputIndex);
1801: 
1802:         // we initialize the partitioner here with the number of key groups (aka max. parallelism)
1803:         if (outputPartitioner instanceof ConfigurableStreamPartitioner) {
1804:             int numKeyGroups = bufferWriter.getNumTargetKeyGroups();
1805:             if (0 < numKeyGroups) {
1806:                 ((ConfigurableStreamPartitioner) outputPartitioner).configure(numKeyGroups);
1807:             }
1808:         }
1809: 
1810:         RecordWriter<SerializationDelegate<StreamRecord<OUT>>> output =
1811:                 new RecordWriterBuilder<SerializationDelegate<StreamRecord<OUT>>>()
1812:                         .setChannelSelector(outputPartitioner)
1813:                         .setTimeout(bufferTimeout)
1814:                         .setTaskName(taskNameWithSubtask)
1815:                         .build(bufferWriter);
1816:         output.setMetricGroup(environment.getMetricGroup().getIOMetricGroup());
1817:         return output;
1818:     }
