68:     private final CheckpointsCleaner checkpointsCleaner;
69:     private final SharedStateRegistryFactory sharedStateRegistryFactory;
70:     private final Configuration jobManagerConfiguration;
71:     private final Executor cleanupExecutor;
72: 
73:     private final long initializationTimestamp;
74: 
75:     private final CompletableFuture<Void> cleanupFuture;
76:     private final CompletableFuture<JobManagerRunnerResult> resultFuture;
77: 
78:     public CheckpointResourcesCleanupRunner(
79:             JobResult jobResult,
80:             CheckpointRecoveryFactory checkpointRecoveryFactory,
81:             SharedStateRegistryFactory sharedStateRegistryFactory,
82:             Configuration jobManagerConfiguration,
83:             Executor cleanupExecutor,
84:             long initializationTimestamp) {
85:         this.jobResult = Preconditions.checkNotNull(jobResult);
86:         this.checkpointRecoveryFactory = Preconditions.checkNotNull(checkpointRecoveryFactory);
87:         this.sharedStateRegistryFactory = Preconditions.checkNotNull(sharedStateRegistryFactory);
88:         this.jobManagerConfiguration = Preconditions.checkNotNull(jobManagerConfiguration);
89:         this.cleanupExecutor = Preconditions.checkNotNull(cleanupExecutor);
90:         this.initializationTimestamp = initializationTimestamp;
91: 
92:         this.checkpointsCleaner =
93:                 new CheckpointsCleaner(
94:                         jobManagerConfiguration.get(CheckpointingOptions.CLEANER_PARALLEL_MODE));
95: 
96:         this.resultFuture = new CompletableFuture<>();
97:         this.cleanupFuture = resultFuture.thenCompose(ignored -> runCleanupAsync());
98:     }
