100:     private CompletableFuture<Void> runCleanupAsync() {
101:         return CompletableFuture.runAsync(
102:                         () -> {
103:                             try {
104:                                 cleanupCheckpoints();
105:                             } catch (Exception e) {
106:                                 throw new CompletionException(e);
107:                             }
