142:                         log);
143:         final String savepointPath =
144:                 fromRequestBodyOrQueryParameter(
145:                         emptyToNull(requestBody.getSavepointPath()),
146:                         () ->
147:                                 emptyToNull(
148:                                         getQueryParameter(
149:                                                 request, SavepointPathQueryParameter.class)),
150:                         effectiveConfiguration.get(StateRecoveryOptions.SAVEPOINT_PATH),
151:                         log);
152:         final RecoveryClaimMode restoreMode =
153:                 Optional.ofNullable(requestBody.getRestoreMode())
154:                         .orElseGet(
155:                                 () ->
156:                                         effectiveConfiguration.get(
157:                                                 StateRecoveryOptions.RECOVERY_CLAIM_MODE));
