262:         final AtomicInteger actualGlobalCleanupCallCount = new AtomicInteger();
263:         final OneShotLatch firstCleanupTriggered = new OneShotLatch();
264:         final CompletableFuture<JobID> successfulJobGraphCleanup = new CompletableFuture<>();
265:         final JobGraphStore jobGraphStore =
266:                 TestingJobGraphStore.newBuilder()
267:                         .setGlobalCleanupFunction(
