271:                                     firstCleanupTriggered.trigger();
272: 
273:                                     if (callCount < 1) {
274:                                         return FutureUtils.completedExceptionally(
275:                                                 new RuntimeException(
276:                                                         "Expected RuntimeException: Unable to remove job graph."));
277:                                     }
278: 
279:                                     successfulJobGraphCleanup.complete(actualJobId);
280:                                     return FutureUtils.completedVoidFuture();
281:                                 })
282:                         .build();
283: 
284:         jobGraphStore.start(NoOpJobGraphListener.INSTANCE);
285:         haServices.setJobGraphStore(jobGraphStore);
286: 
287:         // Construct leader election.
288:         final TestingLeaderElection leaderElection = new TestingLeaderElection();
289:         haServices.setJobMasterLeaderElection(jobId, leaderElection);
290: 
291:         // start the dispatcher with no retries on cleanup
292:         configuration.set(
293:                 CleanupOptions.CLEANUP_STRATEGY,
294:                 CleanupOptions.NONE_PARAM_VALUES.iterator().next());
295:         final Dispatcher dispatcher = createTestingDispatcherBuilder().build(rpcService);
296:         dispatcher.start();
297: 
298:         toTerminate.add(dispatcher);
299:         final CompletableFuture<LeaderInformation> confirmedLeaderInformation =
300:                 leaderElection.isLeader(UUID.randomUUID());
301:         final DispatcherGateway dispatcherGateway =
302:                 dispatcher.getSelfGateway(DispatcherGateway.class);
303:         dispatcherGateway.submitJob(jobGraph, TIMEOUT).get();
304: 
305:         waitForJobToFinish(confirmedLeaderInformation, dispatcherGateway, jobId);
306:         firstCleanupTriggered.await();
307: 
308:         assertThat(
309:                 "The cleanup should have been triggered only once.",
310:                 actualGlobalCleanupCallCount.get(),
311:                 equalTo(1));
312:         assertThat(
313:                 "The cleanup should not have reached the successful cleanup code path.",
314:                 successfulJobGraphCleanup.isDone(),
315:                 equalTo(false));
316: 
317:         assertThat(
318:                 "The JobGraph is still stored in the JobGraphStore.",
319:                 haServices.getJobGraphStore().getJobIds(),
320:                 equalTo(Collections.singleton(jobId)));
321:         assertThat(
322:                 "The JobResultStore should have this job marked as dirty.",
323:                 haServices.getJobResultStore().getDirtyResults().stream()
324:                         .map(JobResult::getJobId)
325:                         .collect(Collectors.toSet()),
326:                 equalTo(Collections.singleton(jobId)));
327: 
328:         // Run a second dispatcher, that restores our finished job.
329:         final Dispatcher secondDispatcher =
330:                 createTestingDispatcherBuilder()
331:                         .setRecoveredDirtyJobs(haServices.getJobResultStore().getDirtyResults())
332:                         .build(rpcService);
333:         secondDispatcher.start();
334: 
335:         toTerminate.add(secondDispatcher);
336:         leaderElection.isLeader(UUID.randomUUID());
337: 
338:         CommonTestUtils.waitUntilCondition(
339:                 () -> haServices.getJobResultStore().getDirtyResults().isEmpty());
340: 
341:         assertThat(
342:                 "The JobGraph is not stored in the JobGraphStore.",
343:                 haServices.getJobGraphStore().getJobIds(),
344:                 IsEmptyCollection.empty());
345:         assertTrue(
346:                 "The JobResultStore has the job listed as clean.",
347:                 haServices.getJobResultStore().hasJobResultEntryAsync(jobId).get());
348: 
349:         assertThat(successfulJobGraphCleanup.get(), equalTo(jobId));
350: 
351:         assertThat(actualGlobalCleanupCallCount.get(), equalTo(2));
352:     }
