354:     private void waitForJobToFinish(
355:             CompletableFuture<LeaderInformation> confirmedLeaderInformation,
356:             DispatcherGateway dispatcherGateway,
357:             JobID jobId)
358:             throws Exception {
359:         final JobMasterGateway jobMasterGateway =
360:                 connectToLeadingJobMaster(confirmedLeaderInformation).get();
361:         try (final JobMasterTester tester =
362:                 new JobMasterTester(rpcService, jobId, jobMasterGateway)) {
363:             final CompletableFuture<List<TaskDeploymentDescriptor>> descriptorsFuture =
364:                     tester.deployVertices(2);
365:             awaitStatus(dispatcherGateway, jobId, JobStatus.RUNNING);
366:             tester.transitionTo(descriptorsFuture.get(), ExecutionState.INITIALIZING).get();
367:             tester.transitionTo(descriptorsFuture.get(), ExecutionState.RUNNING).get();
368:             tester.getCheckpointFuture(1L).get();
369:             tester.transitionTo(descriptorsFuture.get(), ExecutionState.FINISHED).get();
370:         }
371:         awaitStatus(dispatcherGateway, jobId, JobStatus.FINISHED);
372:     }
373: 
374:     private JobGraph createJobGraph() {
375:         final JobVertex firstVertex = new JobVertex("first");
376:         firstVertex.setInvokableClass(NoOpInvokable.class);
377:         firstVertex.setParallelism(1);
378: 
379:         final JobVertex secondVertex = new JobVertex("second");
380:         secondVertex.setInvokableClass(NoOpInvokable.class);
381:         secondVertex.setParallelism(1);
382: 
383:         final CheckpointCoordinatorConfiguration checkpointCoordinatorConfiguration =
384:                 CheckpointCoordinatorConfiguration.builder()
385:                         .setCheckpointInterval(20L)
386:                         .setMinPauseBetweenCheckpoints(20L)
387:                         .setCheckpointTimeout(10_000L)
388:                         .build();
389:         final JobCheckpointingSettings checkpointingSettings =
390:                 new JobCheckpointingSettings(checkpointCoordinatorConfiguration, null);
391:         return JobGraphBuilder.newStreamingJobGraphBuilder()
392:                 .addJobVertex(firstVertex)
393:                 .addJobVertex(secondVertex)
394:                 .setJobCheckpointingSettings(checkpointingSettings)
395:                 .build();
396:     }
397: 
398:     private static CompletableFuture<JobMasterGateway> connectToLeadingJobMaster(
399:             CompletableFuture<LeaderInformation> confirmedLeaderInformation) {
400:         return confirmedLeaderInformation.thenCompose(
401:                 leaderInformation ->
402:                         rpcService.connect(
403:                                 leaderInformation.getLeaderAddress(),
404:                                 JobMasterId.fromUuidOrNull(leaderInformation.getLeaderSessionID()),
405:                                 JobMasterGateway.class));
406:     }
407: }
