543:     /**
544:      * Creates a config map with the given name if it does not exist.
545:      *
546:      * @param flinkKubeClient to use for creating the config map
547:      * @param configMapName name of the config map
548:      * @param clusterId clusterId to which the map belongs
549:      * @throws FlinkException if the config map could not be created
550:      */
551:     public static void createConfigMapIfItDoesNotExist(
552:             FlinkKubeClient flinkKubeClient, String configMapName, String clusterId)
553:             throws FlinkException {
554: 
555:         int attempt = 0;
556:         CompletionException lastException = null;
557: 
558:         final int maxAttempts = 10;
559:         final KubernetesConfigMap configMap =
560:                 new KubernetesConfigMap(
561:                         new ConfigMapBuilder()
562:                                 .withNewMetadata()
563:                                 .withName(configMapName)
564:                                 .withLabels(
565:                                         getConfigMapLabels(
566:                                                 clusterId, LABEL_CONFIGMAP_TYPE_HIGH_AVAILABILITY))
567:                                 .endMetadata()
568:                                 .build());
569: 
570:         while (!flinkKubeClient.getConfigMap(configMapName).isPresent() && attempt < maxAttempts) {
571:             try {
572:                 flinkKubeClient.createConfigMap(configMap).join();
573:             } catch (CompletionException e) {
574:                 // retrying
575:                 lastException = ExceptionUtils.firstOrSuppressed(e, lastException);
576:             }
577: 
578:             attempt++;
579:         }
580: 
581:         if (attempt >= maxAttempts && lastException != null) {
582:             throw new FlinkException(
583:                     String.format("Could not create the config map %s.", configMapName),
584:                     lastException);
585:         }
586:     }
