172:     /**
173:      * Starts a {@link CuratorFramework} instance and connects it to the given ZooKeeper quorum.
174:      *
175:      * @param configuration {@link Configuration} object containing the configuration values
176:      * @param fatalErrorHandler {@link FatalErrorHandler} fatalErrorHandler to handle unexpected
177:      *     errors of {@link CuratorFramework}
178:      * @return {@link CuratorFrameworkWithUnhandledErrorListener} instance
179:      */
180:     public static CuratorFrameworkWithUnhandledErrorListener startCuratorFramework(
181:             Configuration configuration, FatalErrorHandler fatalErrorHandler) {
182:         checkNotNull(configuration, "configuration");
183:         String zkQuorum = configuration.getValue(HighAvailabilityOptions.HA_ZOOKEEPER_QUORUM);
184: 
185:         if (zkQuorum == null || StringUtils.isBlank(zkQuorum)) {
186:             throw new RuntimeException(
187:                     "No valid ZooKeeper quorum has been specified. "
188:                             + "You can specify the quorum via the configuration key '"
189:                             + HighAvailabilityOptions.HA_ZOOKEEPER_QUORUM.key()
190:                             + "'.");
191:         }
192: 
193:         int sessionTimeout =
194:                 Math.toIntExact(
195:                         configuration
196:                                 .get(HighAvailabilityOptions.ZOOKEEPER_SESSION_TIMEOUT)
197:                                 .toMillis());
198: 
199:         int connectionTimeout =
200:                 Math.toIntExact(
201:                         configuration
202:                                 .get(HighAvailabilityOptions.ZOOKEEPER_CONNECTION_TIMEOUT)
203:                                 .toMillis());
204: 
205:         int retryWait =
206:                 Math.toIntExact(
207:                         configuration.get(HighAvailabilityOptions.ZOOKEEPER_RETRY_WAIT).toMillis());
208: 
209:         int maxRetryAttempts =
210:                 configuration.get(HighAvailabilityOptions.ZOOKEEPER_MAX_RETRY_ATTEMPTS);
211: 
212:         String root = configuration.getValue(HighAvailabilityOptions.HA_ZOOKEEPER_ROOT);
213: 
214:         String namespace = configuration.getValue(HighAvailabilityOptions.HA_CLUSTER_ID);
215: 
216:         boolean disableSaslClient = configuration.get(SecurityOptions.ZOOKEEPER_SASL_DISABLE);
217: 
218:         ACLProvider aclProvider;
219: 
220:         ZkClientACLMode aclMode = ZkClientACLMode.fromConfig(configuration);
221: 
222:         if (disableSaslClient && aclMode == ZkClientACLMode.CREATOR) {
223:             String errorMessage =
224:                     "Cannot set ACL role to "
225:                             + ZkClientACLMode.CREATOR
226:                             + "  since SASL authentication is "
227:                             + "disabled through the "
228:                             + SecurityOptions.ZOOKEEPER_SASL_DISABLE.key()
229:                             + " property";
230:             LOG.warn(errorMessage);
231:             throw new IllegalConfigurationException(errorMessage);
232:         }
233: 
234:         if (aclMode == ZkClientACLMode.CREATOR) {
235:             LOG.info("Enforcing creator for ZK connections");
236:             aclProvider = new SecureAclProvider();
237:         } else {
238:             LOG.info("Enforcing default ACL for ZK connections");
239:             aclProvider = new DefaultACLProvider();
240:         }
241: 
242:         String rootWithNamespace = generateZookeeperPath(root, namespace);
243: 
244:         LOG.info("Using '{}' as Zookeeper namespace.", rootWithNamespace);
245: 
246:         boolean ensembleTracking =
247:                 configuration.get(HighAvailabilityOptions.ZOOKEEPER_ENSEMBLE_TRACKING);
248: 
249:         final CuratorFrameworkFactory.Builder curatorFrameworkBuilder =
250:                 CuratorFrameworkFactory.builder()
251:                         .connectString(zkQuorum)
252:                         .sessionTimeoutMs(sessionTimeout)
253:                         .connectionTimeoutMs(connectionTimeout)
254:                         .retryPolicy(new ExponentialBackoffRetry(retryWait, maxRetryAttempts))
255:                         // Curator prepends a '/' manually and throws an Exception if the
256:                         // namespace starts with a '/'.
257:                         .namespace(trimStartingSlash(rootWithNamespace))
258:                         .ensembleTracker(ensembleTracking)
259:                         .aclProvider(aclProvider);
260: 
261:         if (configuration.contains(HighAvailabilityOptions.ZOOKEEPER_CLIENT_AUTHORIZATION)) {
262:             Map<String, String> authMap =
263:                     configuration.get(HighAvailabilityOptions.ZOOKEEPER_CLIENT_AUTHORIZATION);
264:             List<AuthInfo> authInfos =
265:                     authMap.entrySet().stream()
266:                             .map(
267:                                     entry ->
268:                                             new AuthInfo(
269:                                                     entry.getKey(),
270:                                                     entry.getValue()
271:                                                             .getBytes(
272:                                                                     ConfigConstants
273:                                                                             .DEFAULT_CHARSET)))
274:                             .collect(Collectors.toList());
275:             curatorFrameworkBuilder.authorization(authInfos);
276:         }
277: 
278:         if (configuration.contains(HighAvailabilityOptions.ZOOKEEPER_MAX_CLOSE_WAIT)) {
279:             long maxCloseWait =
280:                     configuration.get(HighAvailabilityOptions.ZOOKEEPER_MAX_CLOSE_WAIT).toMillis();
281:             if (maxCloseWait < 0 || maxCloseWait > Integer.MAX_VALUE) {
282:                 throw new IllegalConfigurationException(
283:                         "The value (%d ms) is out-of-range for %s. The milliseconds timeout is expected to be between 0 and %d ms.",
284:                         maxCloseWait,
285:                         HighAvailabilityOptions.ZOOKEEPER_MAX_CLOSE_WAIT.key(),
286:                         Integer.MAX_VALUE);
287:             }
288:             curatorFrameworkBuilder.maxCloseWaitMs((int) maxCloseWait);
289:         }
290: 
291:         if (configuration.contains(
292:                 HighAvailabilityOptions.ZOOKEEPER_SIMULATED_SESSION_EXP_PERCENT)) {
293:             curatorFrameworkBuilder.simulatedSessionExpirationPercent(
294:                     configuration.get(
295:                             HighAvailabilityOptions.ZOOKEEPER_SIMULATED_SESSION_EXP_PERCENT));
296:         }
297: 
298:         if (configuration.get(HighAvailabilityOptions.ZOOKEEPER_TOLERATE_SUSPENDED_CONNECTIONS)) {
299:             curatorFrameworkBuilder.connectionStateErrorPolicy(
300:                     new SessionConnectionStateErrorPolicy());
301:         }
302:         return startCuratorFramework(curatorFrameworkBuilder, fatalErrorHandler);
303:     }
