305:     /**
306:      * Starts a {@link CuratorFramework} instance and connects it to the given ZooKeeper quorum from
307:      * a builder.
308:      *
309:      * @param builder {@link CuratorFrameworkFactory.Builder} A builder for curatorFramework.
310:      * @param fatalErrorHandler {@link FatalErrorHandler} fatalErrorHandler to handle unexpected
311:      *     errors of {@link CuratorFramework}
312:      * @return {@link CuratorFrameworkWithUnhandledErrorListener} instance
313:      */
314:     @VisibleForTesting
315:     public static CuratorFrameworkWithUnhandledErrorListener startCuratorFramework(
316:             CuratorFrameworkFactory.Builder builder, FatalErrorHandler fatalErrorHandler) {
317:         CuratorFramework cf = builder.build();
318:         UnhandledErrorListener unhandledErrorListener =
319:                 (message, throwable) -> {
320:                     LOG.error(
321:                             "Unhandled error in curator framework, error message: {}",
322:                             message,
323:                             throwable);
324:                     // The exception thrown in UnhandledErrorListener will be caught by
325:                     // CuratorFramework. So we mostly trigger exit process or interact with main
326:                     // thread to inform the failure in FatalErrorHandler.
327:                     fatalErrorHandler.onFatalError(throwable);
328:                 };
329:         cf.getUnhandledErrorListenable().addListener(unhandledErrorListener);
330:         cf.start();
331:         return new CuratorFrameworkWithUnhandledErrorListener(cf, unhandledErrorListener);
332:     }
