498:     public static LeaderInformation readLeaderInformation(byte[] data)
499:             throws IOException, ClassNotFoundException {
500:         if (data != null && data.length > 0) {
501:             final ByteArrayInputStream bais = new ByteArrayInputStream(data);
502:             final String leaderAddress;
503:             final UUID leaderSessionID;
504: 
505:             try (final ObjectInputStream ois = new ObjectInputStream(bais)) {
506:                 leaderAddress = ois.readUTF();
507:                 leaderSessionID = (UUID) ois.readObject();
508:             }
509: 
510:             return LeaderInformation.known(leaderSessionID, leaderAddress);
511:         } else {
512:             return LeaderInformation.empty();
513:         }
514:     }
