533:         // ZooKeeper submitted jobs root dir
534:         String zooKeeperJobsPath =
535:                 configuration.get(HighAvailabilityOptions.HA_ZOOKEEPER_JOBGRAPHS_PATH);
536: 
537:         // Ensure that the job graphs path exists
538:         client.newNamespaceAwareEnsurePath(zooKeeperJobsPath).ensure(client.getZookeeperClient());
