751:             final TreeCacheSelector selector) {
752:         return TreeCache.newBuilder(client, pathToNode)
753:                 .setCacheData(true)
754:                 .setCreateParentNodes(false)
755:                 .setSelector(selector)
756:                 // see FLINK-32204 for further details on why the task rejection shouldn't
