762:     @VisibleForTesting
763:     static TreeCacheListener createTreeCacheListener(RunnableWithException nodeChangeCallback) {
764:         return (ignored, event) -> {
765:             // only notify listener if nodes have changed
766:             // connection issues are handled separately from the cache
767:             switch (event.getType()) {
768:                 case NODE_ADDED:
769:                 case NODE_UPDATED:
770:                 case NODE_REMOVED:
771:                     nodeChangeCallback.run();
772:             }
773:         };
