435:     public static void writeLeaderInformationToZooKeeper(
436:             LeaderInformation leaderInformation,
437:             CuratorFramework curatorFramework,
438:             BooleanSupplier hasLeadershipCheck,
439:             String connectionInformationPath)
440:             throws Exception {
441:         final byte[] data;
442: 
443:         if (leaderInformation.isEmpty()) {
444:             data = null;
445:         } else {
446:             final ByteArrayOutputStream baos = new ByteArrayOutputStream();
447:             final ObjectOutputStream oos = new ObjectOutputStream(baos);
448: 
449:             oos.writeUTF(leaderInformation.getLeaderAddress());
450:             oos.writeObject(leaderInformation.getLeaderSessionID());
451: 
452:             oos.close();
453: 
454:             data = baos.toByteArray();
455:         }
456: 
457:         boolean dataWritten = false;
458: 
459:         while (!dataWritten && hasLeadershipCheck.getAsBoolean()) {
460:             Stat stat = curatorFramework.checkExists().forPath(connectionInformationPath);
461: 
462:             if (stat != null) {
463:                 long owner = stat.getEphemeralOwner();
464:                 long sessionID =
465:                         curatorFramework.getZookeeperClient().getZooKeeper().getSessionId();
466: 
467:                 if (owner == sessionID) {
468:                     try {
469:                         curatorFramework.setData().forPath(connectionInformationPath, data);
470: 
471:                         dataWritten = true;
472:                     } catch (KeeperException.NoNodeException noNode) {
473:                         // node was deleted in the meantime
474:                     }
475:                 } else {
476:                     try {
477:                         curatorFramework.delete().forPath(connectionInformationPath);
478:                     } catch (KeeperException.NoNodeException noNode) {
479:                         // node was deleted in the meantime --> try again
480:                     }
481:                 }
482:             } else {
483:                 try {
484:                     curatorFramework
485:                             .create()
486:                             .creatingParentsIfNeeded()
487:                             .withMode(CreateMode.EPHEMERAL)
488:                             .forPath(connectionInformationPath, data);
489: 
490:                     dataWritten = true;
491:                 } catch (KeeperException.NodeExistsException nodeExists) {
492:                     // node has been created in the meantime --> try again
493:                 }
494:             }
495:         }
496:     }
