683:     private static String trimSlashes(String input) {
684:         int left = 0;
685:         int right = input.length() - 1;
686: 
687:         while (left <= right && input.charAt(left) == '/') {
688:             left++;
689:         }
690: 
691:         while (right >= left && input.charAt(right) == '/') {
692:             right--;
693:         }
694: 
695:         if (left <= right) {
696:             return input.substring(left, right + 1);
697:         } else {
698:             return "";
699:         }
700:     }
